WITH payload AS (SELECT $archive_payload$[{"id":"519da771-6eb1-59e7-b8b9-e7ed845e1fe1","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -انتهاك حرمة منزل -دخول منزل لغرض السرقة -سرقة بعض محتويات املنزل -تصريف مسروقات -إقرار حتقيق ا -مطالبة املدعي العام بحد السرقة -درء حد السرقة لتنازل املسروق منه عن حقه اخلاص -صرف نظر عن مطالبة بحد السرقة -تعزير بالسجن واجللد -ظروف مخففة للعقوبة.","document_number":"33465260","case_number":"33556797","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة األحساء","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/24","year":"1434","subject":"سرقة -انتهاك حرمة منزل -دخول منزل لغرض السرقة -سرقة بعض محتويات املنزل -تصريف مسروقات -إقرار حتقيق ا -مطالبة املدعي العام بحد السرقة -درء حد السرقة لتنازل املسروق منه عن حقه اخلاص -صرف نظر عن مطالبة بحد السرقة -تعزير بالسجن واجللد -ظروف مخففة للعقوبة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33465260:‬تاريخه ‪1433/11/24:‬هـ‬\n                         ‫رقم الدعوى ‪33556797:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                    ‫‪ 3454473‬تاريخه‪1434/3/3:‬هـ‬\n\n\n\n     ‫ســرقة ‪ -‬انتهــاك حرمــة منــزل‪ -‬دخــول منــزل لغــرض الســرقة‪ -‬ســرقة‬\n     ‫بعــض محتويــات املنــزل ‪ -‬تصريــف مســروقات‪ -‬إقــرار حتقيقـ ًا‪ -‬مطالبة‬\n     ‫املدعــي العــام بحــد الســرقة‪ -‬درء حــد الســرقة لتنــازل املســروق منــه‬\n     ‫عــن حقــه اخلــاص ‪ -‬صــرف نظــر عــن مطالبــة بحــد الســرقة ‪ -‬تعزيــر‬\n                               ‫بالســجن واجللــد ‪ -‬ظــروف مخففــة للعقوبــة‪.‬‬\n\n\n\n\n     ‫قــال يف كشــاف القنــاع ( ويشــترط أن يطالــب املســروق منــه مبالــه أو‬\n                      ‫يطالــب بــه وكيلــه ألن املــال يبــاح بالبــذل واإلباحــة )‪.‬‬\n\n\n\n\n     ‫دعــوى املدعــي العــام ضــد املدعــى عليــه بانتهــاك حرمــة منــزل‬\n     ‫بالدخــول إليــه بالقفــز علــى الســور اخللفــي وســرقة أجهــزة كهربائيــة‬\n     ‫وأكسســورات نســائية وســاعات وتصريــف املســروقات‪ ،‬طالــب املدعي‬\n     ‫العــام بحــد الســرقة‪ ،‬مت القبــض علــى املدعى عليــه بعد البحث والتحري‬\n     ‫ـاء علــى بــاغ مفــاده تعــرض أحــد املنــازل للســرقة ‪ ،‬تنــازل صاحــب‬  ‫بنـ ً‬\n     ‫احلــق اخلــاص عــن حقــه اخلــاص‪ ،‬إقــرار املدعــى عليــه بالدعــوى‪ ،‬صــرف‬\n     ‫النظــر عــن دعــوى املدعــى العــام‪ ،‬إقامــة حــد الســرقة لتنــازل املســروق‬\n     ‫منــه عــن حقــه اخلــاص‪ ،‬درء حــد الســرقة‪ ،‬صــدر احلكــم بتعزيــر املدعــى‬\n‫‪69‬‬\n\f‫عليــه بالســجن واجللــد‪ ،‬مت تصديــق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلدينــا نحــن ‪ .............‬و‪.............‬و‪ ............‬القضــاة‬\n‫باحملكمــة العامــة مبحافظــة األحســاء وبنــاء علــى املعاملــة احملالــة لنــا‬\n‫مــن فضيلــة رئيــس احملكمــة برقــم ‪ ........‬وتاريــخ ‪.......‬ه ـ واملقيــدة برقــم‬\n‫‪ .........‬وتاريــخ ‪..........‬ه ـ أنــه يف يــوم األربعــاء ‪..........‬ه ـ انعقــدت اجللســة‬\n‫وفيهــا حضــر املدعــي العــام واملدعــى عليــه ‪ ..............‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ ..........‬وقــال املدعــي العــام فبصفتي مدعي ًا‬\n‫عامــا بدائــرة االدعــاء العــام مبحافظــة األحســاء أدعــي علــى ‪، .............‬‬     ‫ً‬\n‫‪ 19‬عام ـ ًا ‪ ،‬غيــر محصــن ‪ ،‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم (‪ ، )...............‬طالــب ‪ ،‬أوقــف بتاريــخ ‪........‬ه ـ ‪ ،‬ومت بعثــه إلى شــعبة‬\n‫ا لديهــم برقــم ( ‪ ) .......‬اســتنا ًدا‬  ‫ســجن محافظــة األحســاء وســجل نزي ـ ً‬\n‫للمــادة (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة الفقــرة ( ‪ ) 1‬مــن القــرار‬\n‫الــوزاري ( ‪ ) 1900‬املــؤرخ يف ‪ ،....../ 7 / 9‬يســكن محافظــة األحســاء‬\n‫حــي ‪ ....‬إنــه بتاريخ‪.........‬ه ـ ورد تقريــر دوريــة األمــن باألحســاء رقــم‬\n‫(‪ )7683‬املتضمــن بــاغ املواطــن ‪( .........‬ســعودي) عــن تعــرض منزلــه‬\n‫للدخــول وســرقة منــه أربعــة أجهــزة كمبيوتــر البتــوب وكاميرتــا‬\n‫تصويــر وســاعات ومجموعــة أكسســوارات نســائية ‪ ،‬وال يتهــم أحــد ًا‬\n‫بذلــك ‪ .‬ومبعاينــة املوقــع اتضــح بــأن املنــزل يقــع بحــي (‪ ).....‬فلــه (‪)000‬‬\n‫خلــف مســجد ‪ ، ....‬واتضــح بــأن اجلانــي متكــن مــن دخــول املنــزل عــن‬\n‫طريــق القفــز مــن علــى الســور اخلارجــي والدخــول إلــى التهويــة وفتــح‬\n‫قفــل بــاب األملنيــوم بعــد كســره واملــؤدي علــى داخــل املنــزل وفتــح أربعــة‬\n\n                                                                                              ‫‪70‬‬\n\f     ‫غــرف مخصصــة للنــوم وبعثــرة محتوياتهــا وســرقة منهــا أربعــة أجهــزة‬\n     ‫كمبيوتــر وكاميرتــا تصويــر وســاعات ومجموعــة إكسســوارات‬\n     ‫نســائية وجــرى تصويــر املوقــع ورفــع بعــض اآلثــار ‪ .‬بعــد تلقــي البــاغ مت‬\n     ‫مكاتبــة شــعبة التحريــات والبحــث اجلنائــي برقــم ‪ ....‬يف ‪........‬ه ـ للبحــث‬\n     ‫والتحــري عــن القضيــة والقبــض علــى اجلنــاة ‪ .‬وقــد ورود تقريــر مــن دورية‬\n     ‫البحــث اجلنائــي رقــم (‪ )...‬يف ‪........‬ه ـ يفيــد القبــض علــى املدعــى عليــه‬\n     ‫بتهمــة ســرقة منــزل املدعــو ‪ ، .......‬وقــد جــرى ضبــط جهازيــن كمبيوتر‬\n     ‫(البتــوب) وكاميرتــا تصويــر وجهــاز هاردســك وجهــاز ألفــا وســماعات‬\n     ‫كمبيوتــر وشــاحن كمبيوتــر بحيــازة وباســتجواب املدعــى عليــه أقــر‬\n     ‫بأنــه يف يــوم األربعــاء املوافــق ‪ .......‬ه ـ وعندمــا كان مبنزلــه املجــاور‬\n     ‫ملنــزل املدعــو ‪ ، .....‬وكان معــه ابــن خالــه املدعــو ‪ ........‬قــام بوضــع ســلم‬\n     ‫علــى ســور منــزل جــاره ‪ ،‬والدخــول إلــى املنــزل بعــد فتــح بــاب األملنيــوم‬\n     ‫املــؤدي إلــى داخــل املنــزل وفتــح الغــرف وتفتيشــها وســرقة منهــا أربعــة‬\n     ‫أجهــزة كمبيوتــر البتــوب وكاميرتــا تصويــر وجهــاز هاردســك وجهــاز‬\n     ‫ألفــا وشــاحن كمبيوتــر ومجموعــة ســاعات وإكسســوارات نســائية ‪،‬‬\n     ‫ويف اليــوم التالــي توجــه إلــى ســوق اخلــردة وقــام ببيــع جهازيــن كمبيوتــر‬\n     ‫علــى شــخص مجهــول مببلــغ ســبعمائة ريــال والتصــرف بالقيمة وضبطت‬\n     ‫باقــي املســروقات التــي بحوزتــه والقبــض عليــه مــن قبــل شــعبة التحريــات‬\n     ‫والبحــث اجلنائــي وتســليمه ملركــز الشــرطة ‪.‬وقــد أســفر التحقيــق عــن‬\n     ‫توجيــه االتهــام لــه بانتهــاك حرمــة منــزل املواطــن ‪ .....‬بالدخــول للمنــزل‬\n     ‫وســرقة أجهــزة كهربائيــة وســاعات وإكسســوارات نســائية بعــد‬\n     ‫متكنــه مــن القفــز علــى الســور اخللفــي وتصريــف بعــض املســروقات ؛‬\n     ‫وذلــك لألدلــة والقرائــن التاليــة ‪ - 1 :‬إقــراره املنــوه عنــه املــدون علــى‬\n\n\n‫‪71‬‬\n\f‫الصفحــات رقــم ( ‪ ) 12‬مــن ملــف التحقيــق رقــم (‪ -2.)2‬محضــر املعاينــة‬\n‫املنــوه عنــه‪ ،‬املــدون علــى الصفحــات رقــم ( ‪ ) 3 ، 2‬مــن ملــف التحقيــق‬\n‫رقــم (‪ -3 . )1‬تطابــق أقــوال املدعــى عليــه عــن كيفيــة ارتكابه للســرقة‬\n‫مــع مــا جــاء يف البــاغ ومحضــر املعاينــة ‪ -4.‬محضر القبــض على املدعى‬\n‫عليــه مــن قبــل شــعبة التحريــات والبحــث اجلنائــي لقيامــه بدخــول منــزل‬\n‫املدعــو ‪ ......‬والســرقة منــه وضبــط املســروقات بحيازتــه ‪ ،‬املــدون علــى‬\n‫اللفــة رقــم (‪ -5. )13‬بــاغ املدعــو ‪ .......‬عــن تعــرض منزلــه للســرقة أثنــاء‬\n‫ســفره خــارج احملافظــة وســرق منــه أربعــة أجهــزة كمبيوتــر البتــوب‬\n‫وكاميرتــا تصويــر وجهــاز هاردســك وجهــاز ألفــا وشــاحن كمبيوتــر‬\n‫ومجموعــة ســاعات وإكسســوارات نســائية واليتهــم أحـ ًـدا بذلــك ‪،‬‬\n‫املــدون علــى اللفــة رقــم (‪ -6. )1‬ضبــط املســروقات بحيــازة املدعــى عليــه‬\n‫وهــي جهازيــن كمبيوتــر البتــوب وكاميرتــا تصويــر وجهــاز هاردســك‬\n‫وجهــاز ألفــا وســماعات كمبيوتــر وشــاحن كمبيوتــر وتعــرف عليهــا‬\n‫املبلــغ بأنهــا املســروقات التــي أوردهــا وقــت تقــدمي البــاغ يــدل بأنــه مــن‬\n‫قــام بالســرقة ‪ ،‬املــدون علــى اللفــة رقــم (‪ .)13‬وبالبحــث عمــا إذا كان‬\n‫عليــه ســوابق عثــر لــه علــى ســابقة إزعــاج ‪.‬وحيــث إن مــا أقــدم عليــه‬\n‫املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم ومعاقــب‬\n‫عليــه شــرع ًا لقيامــه بســرقة مــال محــرم يزيــد عــن النصــاب مــن حــرزه‬\n‫مكلفــا غيــر‬\n         ‫ً‬       ‫بعــد هتكــه ال شــبهة لــه فيــه وطالــب بــه صاحبــه ولكونــه‬\n‫مكــره ؛ لــذا أطلــب إثبــات مــا أســند إليــه ‪ .‬واحلكــم عليــه بحــد الســرقة‬\n‫علمــا أن احلــق‬\n              ‫الــوارد يف اآليــة الكرميــة رقــم ( ‪ ) 38‬مــن ســورة املائــدة ً‬\n‫اخلــاص انتهــى بالتنــازل هــذه دعــواي وبعــرض دعــوى املدعــي العــام علــى‬\n‫املدعــى عليــه احلاضــر أجــاب قائــا الصحيــح أننــي دخلــت ثــاث غــرف‬\n\n\n                                                                                       ‫‪72‬‬\n\f     ‫ولــم يقبضــوا علــي بــل أنــا ذهبــت بنفســي ‪ .....‬واملســروقات املذكــورة‬\n     ‫أخذتهــا مــن البيــت وأنــا تائــب واإلقــرار صحيــح ويف اليــوم التالــي بعــد أن‬\n     ‫بعــت بعــض املســروقات ذهبــت لصاحــب املنــزل واعتــذرت منــه وأنــا تائــب‬\n     ‫هلل عــز وجــل هكــذا أجــاب و يف جلســة أخــرى حضــر املدعــي العــام و‬\n     ‫املدعــى عليــه و يف وقــت ســابق جــرى دراســة الدعــوى و مــا ذكــر فيهــا‬\n     ‫مــن أدلــة و حتقيقــات و محاضــر و تبــن أن حــد الســرقة لــم يثبــت الثبــوت‬\n     ‫الشــرعي لكــون صاحــب احلــق اخلــاص تنــازل و هــذا الشــرط متفــق عليــه‬\n     ‫عنــد جمهــور أهــل العلــم مــن احلنابلــة والشــافعية و غيرهــم قــال صاحــب‬\n     ‫كشــاف القنــاع (و يشــترط أن يطالــب املســروق منــه مبالــه أو يطالــب‬\n     ‫بــه وكيلــه ألن املــال يبــاح بالبــذل و اإلباحــة) وحكمنــا مبــا يلــي أوال‪:‬‬\n     ‫صــرف النظــر عــن طلــب املدعــي العــام بإقامــة حــد الســرقة و درء احلــد‬\n     ‫عــن املدعــى عليــه لعــدم حتقــق الشــروط ثانيــا ‪ :‬حكمنــا بتعزيــر املدعــى‬\n     ‫عليــه بالســجن ملــدة ســنة تبــدأ مــن تاريــخ إيقافــه و يجلــد ثالثمائــة جلــدة‬\n     ‫مفرقــة علــى ســت دفعــات كل دفعــة خمســون جلــدة بــن الدفعــة و التــي‬\n     ‫تليهــا مــدة ال تقــل عــن عشــرة أيــام يف مــكان عــام و جــرى تخفيــف‬\n     ‫العقوبــة لكــون املدعــى عليــه مــازال صغيــر الســن و ليــس عليــه ســوابق‬\n     ‫و قــد أبــدى أســفه و ندمــه ممــا يرجــى لــه الصــاح و االســتقامة و بعــرض‬\n     ‫احلكــم علــى األطــراف اعتــرض املدعــي العــام و قنــع بــه املدعــى عليــه‬\n     ‫فأفهــم املدعــي العــام بــأن لــه مهلــة اعتراضيــة مدتهــا ثالثــون يومــا إذا‬\n     ‫لــم يتقــدم خاللهــا بالئحتــه االعتراضيــة ســوف يرفــع احلكــم حملكمــة‬\n     ‫االســتئناف لتقــرر مــا تــراه وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينا محمد‬\n                   ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪.........‬ه ـ الســاعة ‪.9:40‬‬\n     ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعنــا نحــن ق ــضاة الدائـ ــرة اجلزائـي ــة‬\n\n\n‫‪73‬‬\n\f‫اخلماسـي ــة األولــى يف محكمــة االســتئناف باملنطقــة الشــرقية علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة‬\n‫األحســاء املســاعد برقــم ‪ .........‬وتاريــخ ‪......‬ه ـ واملقيــدة لــدى احملكمــة‬\n‫برقــم ‪ .........‬وتاريــخ ‪......‬ه ـ املرفــق بهــا القــرار الشــرعي ذو الرقــم ‪.........‬‬\n‫والتاريــخ ‪......‬ه ـ الصــادر مــن أصحــاب الفضيلــة القضــاة باحملكمــة‬\n‫الشــيخ‪ ........../‬والشيخ‪........./‬والشــيخ‪ ........../‬اخلــاص بدعــوى‪ /‬املدعــي‬\n‫العــام ضــد‪ ....../‬يف قضيــة انتهــاك حرمــة منــزل وســرقه وقــد تضمــن‬\n‫القــرار حكــم أصحــاب الفضيلــة مبــا هــو مــدون ومفصــل فيــه ‪.‬‬\n‫وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى‬\n‫احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‬\n                                                               ‫حــرر يف ‪ ........‬هـ ـ ـ ـ ‪.‬‬\n\n\n\n\n                                                                                              ‫‪74‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":69,"source_page_end":74,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c67249dfe0cec10218fd0db88c7b1cc05328352655f0003a0949fb26488a38ea","normalized_text_hash":"1f8292d70f6e0de7f63726b7272b47105ea7d18a73796c29f0e425000e2da03a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p69-33465260"},{"id":"931e84b1-a751-56bf-9144-0fe0365c761e","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة سيارة -املدعى عليهم أحداث وشخص بالغ - التفحيط بالسيارة املسروقة -املراقبة للسرقة -االعتراف حتقيق ا -إقرار غير املكلف غير معتبر -الدعوى على الصبي تسمع بالبينة -التعزير بالسجن واجللد -التكليف شرط لصحة اإلقرار -أسباب تخفيف العقوبة -شبهة ضعيفة -ال أثر للشبهة إذا لم تكن قوية.","document_number":"33412831","case_number":"33567286","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/09/17","year":"1434","subject":"سرقة -سرقة سيارة -املدعى عليهم أحداث وشخص بالغ - التفحيط بالسيارة املسروقة -املراقبة للسرقة -االعتراف حتقيق ا -إقرار غير املكلف غير معتبر -الدعوى على الصبي تسمع بالبينة -التعزير بالسجن واجللد -التكليف شرط لصحة اإلقرار -أسباب تخفيف العقوبة -شبهة ضعيفة -ال أثر للشبهة إذا لم تكن قوية.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"                   ‫رقم الصك ‪ 33412831 :‬تاريخه ‪:‬‬\n           ‫‪1433/09/17‬هـ رقم الدعوى ‪33567286 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34186594‬تاريخه‪1434/4/14 :‬ه‬\n\n\n\n     ‫ســرقة ‪ -‬ســرقة ســيارة ‪ -‬املدعــى عليهــم أحــداث وشــخص بالــغ ‪-‬‬\n     ‫التفحيــط بالســيارة املســروقة ‪ -‬املراقبــة للســرقة ‪ -‬االعتــراف حتقيقـ ًا‬\n     ‫‪ -‬إقــرار غيــر املكلــف غيــر معتبــر‪ -‬الدعــوى علــى الصبــي تســمع بالبينــة‬\n     ‫‪ -‬التعزيــر بالســجن واجللــد ‪ -‬التكليــف شــرط لصحــة اإلقــرار ‪ -‬أســباب‬\n     ‫تخفيــف العقوبــة ‪ -‬شــبهة ضعيفــة ‪ -‬ال أثــر للشــبهة إذا لــم تكــن قويــة‪.‬‬\n\n\n\n\n                                              ‫‪-1‬قاعدة ‪ ( :‬اإلقرار حجة على املقر ) ‪.‬‬\n                                                        ‫‪-2‬قاعدة ‪ ( :‬ال عذر ملن أقر ) ‪.‬‬\n     ‫‪-3‬مــا قــرره األصحــاب رحمهــم اهلل ‪( :‬بــأن مــن ادعــى علــى صبــي فــإن‬\n                                                             ‫دعــواه تســمع بالبينــة ) ‪.‬‬\n     ‫‪-4‬مــا قــرره األصحــاب رحمهــم اهلل ‪ ( :‬أن مــن شــرط صحــة اإلقــرار‬\n     ‫التكليــف ) ‪ .‬جــاء يف املقنــع املطبــوع مــن الشــرح الكبيــر (‪)142/30‬؛‬\n     ‫(يصــح اإلقــرار مــن كل مكلــف مختــار غيــر الصبــي واملجنــون فــا‬\n     ‫يصــح إقرارهمــا ‪ ،‬إال أن يكــون الصبــي مأذون ـ ًا لــه يف البيــع والشــراء‬\n     ‫فيصــح إقــراره يف قــدر مــا أذن لــه دون مــا زاد ‪ .‬وقــال يف الشــرح ‪ :‬فأمــا‬\n     ‫الطفــل واملجنــون فــا يصــح إقرارهمــا وكذلــك املبرســم والنائــم‬\n                                      ‫واملغمــى عليــه ‪ ،‬ال نعلــم يف هــذا خالف ـ ًا )‪.‬‬\n     ‫‪-5‬الشــرط عنــد األصوليــن مــا يلــزم مــن عدمــه العــدم وال يلــزم مــن‬\n\n\n‫‪75‬‬\n\f                                          ‫وجــوده وجــود وال عــدم لذاتــه ‪.‬‬\n‫‪-6‬قرر الســيوطي رحمه اهلل يف األشــباه والنظائر ‪ ( :‬انه ال اثر للشــبهة‬\n                                                        ‫إذا لــم تكــن قويــه ) ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام علــى عــدة أشــخاص أحدهــم بالــغ والباقــي أحــداث‬\n‫قصــر‪ ،‬بســرقة ســيارتني والتفحيــط عليهــا‪ ،‬حيــث تقــدم مواطنــن‬\n‫ببــاغ ملركــز الشــرطة عــن تعــرض ســيارتهم للســرقه أثنــاء وقوفهــا‬\n‫أمــام املنــزل‪ ،‬قبــض علــى املدعــى عليهــم مــن قبــل أحــد املواطنــن بعدمــا‬\n‫اشــتبه بهــم وشــاهدهم يقتــادوا أحــدى الســيارتني املســروقتني‪ ،‬قامــوا‬\n‫بالفــرار علــى الطريــق الســريع‪ ،‬طلــب املدعــي العــام إثبــات مــا نســب‬\n‫إليهــم واحلكــم عليهــم بعقوبــة تعزيريــة (علمـ ًا بــأن احلــق اخلــاص انتهــى)‬\n‫أنكــر البالــغ الســرقة‪ ،‬واقــر باملراقبــة وقيــادة الســيارة والتفحيــط‪،‬‬\n‫أقــر القصــار مبــا نســب إليهــم‪ ،‬صــدر احلكــم بتعزيــر البالــغ بالســجن‬\n‫عشــرين يوم ـ ًا واجللــد ثالثــن جلــده‪ ،‬خففــت عنــه العقوبــة لصغــر ســنه‬\n‫ولعــدم وجــود ســوابق‪ ،‬صــرف النظــر عــن بقيــة املدعــى عليهــم القصــار‬\n‫ألن مــن شــرط صحــة اإلقــرار التكليــف‪ ،‬لوحــظ علــى احلكــم ـ ثــم‬\n                                             ‫صــدق مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n                                                                                     ‫‪76‬‬\n\f     ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ........‬القاضــي باحملكمــة اجلزائيــة‬\n     ‫بالقطيــف والقائــم بعمــل فضيلــة القاضــي الشــيخ ‪........‬وبنــاء علــى‬\n     ‫املعاملــة احملالــة إلــى فضيلتــه مــن فضيلــة الرئيــس برقــم ‪33567286‬‬\n     ‫يف ‪1433/9 / 9‬ه ـ والــواردة بكتــاب رئيــس دائــرة التحقيــق واالدعــاء‬\n     ‫العــام مبحافظــة القطيــف ذي الرقــم ه ـ ق‪ 2507/2/4‬يف ‪1433/9/9‬ه ـ‬\n     ‫حضــر املدعــي العــام ع ‪ ..............‬مبوجــب كتــاب التكليــف رقــم ه ـ ق‬\n     ‫‪ 2156/2/4‬يف ‪1431/9/15‬هـ وادعى على احلاضر معه ‪........‬السعودي‬\n     ‫بالســجل املدنــي رقــم ‪........‬املولــود يف ‪1417/11/22‬ه ـ و‪........‬الســعودي‬\n     ‫بالســجل املدنــي رقــم ‪........‬املولــود يف ‪1419/4/25‬ه ـ بصحبــة والدهمــا‬\n     ‫‪........‬الســعودي بالســجل املدنــي رقــم ‪........‬و‪ ........‬الســعودي بالســجل‬\n     ‫املدني رقم ‪........‬املولود يف ‪1422/10/5‬هـ بصحبة والده ‪........‬السعودي‬\n     ‫بالســجل املدنــي رقــم ‪........‬وعلــى و‪........‬الســعودي بالســجل املدنــي رقــم‬\n     ‫‪........‬املولــود يف ‪1419/7/26‬ه ـ بصحبــة والــده ‪........‬الســعودي بالســجل‬\n     ‫املدني رقم ‪........‬وكان تاريخ والدة كل منهم حسب ما أثبت يف سجل‬\n     ‫ا يف دعــواه إنــه بتاريــخ ‪1433/4/9‬ه ـ تقــدم‬    ‫أســرة والــد كل منهــم قائـ ً‬\n     ‫لضابــط خفــر شــرطة مركــز ‪......../........‬ببالغــه عــن تعــرض ســيارته‬\n     ‫مــن نــوع ‪ .........‬لوحــه رقــم (‪ )........‬بيضــاء اللــون للســرقة عنــد إيقافهــا‬\n     ‫أمــام منزلــه يف متــام الســاعة الثالثــة صباح ـ ًا وعنــد خروجــه مــن منزلــه‬\n     ‫لــم يشــاهد ســيارته يف مكانهــا كمــا تقــدم ‪......../‬ببالغــه عــن تعــرض‬\n     ‫ســيارته مــن نــوع ‪......‬لوحــه رقــم (‪ )........‬للســرقة عنــد إيقافهــا أمام منزله‬\n     ‫ـاء وعنــد خروجــه مــن منزلــه يف متــام‬\n                                             ‫يف متــام الســاعة احلاديــة عشــر مسـ ً‬\n\n‫‪77‬‬\n\f‫الســاعة الســابعة صباحـ ًا للذهــاب لعملــه لــم يشــاهد ســيارته يف مكانها‬\n‫وبتاريــخ ‪1433/4/9‬ه ـ قبــض علــى املدعــى عليهــم مــن قبل‪......../‬بعدمــا‬\n‫اشــتبه بهــم وشــاهدهم علــى ســيارة ‪ ........‬حتمــل لوحــة رقــم‪ .......‬وقامــوا‬\n‫بالفــرار علــى الطريــق الســريع وباســتجواب املدعــى عليــه األول (‪)........‬‬\n‫أفــاد بأنــه يف يــوم اجلمعــة املوافــق ‪1433/4/8‬ه ـ كان مــع املدعــو‪........ /‬‬\n‫علــى ســيارة مســروقة مــن نــوع ‪ .......‬هــو وشــقيقه‪......../‬و‪........‬و‪........‬‬\n‫واجتهــوا إلــى قريــة ‪........‬مبحافظــة ‪........‬وقــام ‪ ...‬بفتــح ســيارة أخــرى مــن‬\n‫نــوع ‪ .....‬نفــس النــوع والشــكل ثــم تولــى قيادتهــا شــقيقه‪......../‬وذهبوا‬\n‫إلــى ســاحة التفحيــط وهنــاك قــام ‪........‬بالتفحيــط بالســيارة األولــى وقام‬\n‫بتقطيــع الكفــرات بواســطة ســكني وذهبــوا مــن املوقــع ومت القبــض‬\n‫عليهــم يف طريــق ‪........‬حيــث تعطلــت الســيارة عليهم‪،‬وصــدق اعترافــه‬\n‫شــرع ًا وباســتجواب بقيــة املدعــى عليهــم جــاءت أقوالهــم مطابقــة ألقــوال‬\n‫املدعــى عليــه األول وصــدق اعترافهــم شــرع ًا وقــد انتهــى التحقيــق معهــم‬\n‫إلــى توجيــه االتهــام لهــم بســرقة ســيارتني وحيــث أن مــا أقــدم عليــه‬\n‫املذكــورون‪ ،‬وهــم بكامــل قواهــم العقليــة املعتبــرة شــرعاً‪-‬فعل محــرم‬\n‫ومعاقــب عليــه شــرع ًا لــذا أطلــب إثبــات مــا نســب إليهــم واحلكــم عليهــم‬\n‫بعقوبــة تعزيريــه تزجرهــم وتــردع غيرهــم (علمـ ًا أن احلــق اخلــاص انتهــى)‬\n‫هــذا مــا ادعــى بــه وبعرضــه علــى املدعــى عليهــم وبســؤالهم عنــه أجــاب‬\n‫ا مــا ذكــره املدعــي العــام يف دعــواه ضــدي مــن‬      ‫املدعــى عليــه ‪........‬قائـ ً‬\n‫قيامــي بســرقة ســيارتني غيــر صحيــح والصحيــح أنــي خرجــت مــع كل‬\n‫مــن ‪........‬و‪ ........‬وقامــا بفتــح ســيارة مــن نــوع ‪......‬اللــون‪ ......‬وكان دوري‬\n‫محصــور ًا باملراقبــة لهــم فقــط ثــم قــدت الســيارة وكان معــي كل مــن‬\n‫‪........‬و‪ ........‬ثــم بعــد تعطلهــا ورجوعنــا قمــت بقيــادة ســيارة أخــرى مــن‬\n\n\n                                                                                           ‫‪78‬‬\n\f     ‫نــوع ‪ ......‬بعــد أن قــام ‪........‬بفتــح فراملهــا وقــد كانــت الســيارة مفتوحــة‬\n     ‫وقمــت بالتفحيــط بهــا وكان معــي بقيــة املدعــى عليهــم حتــى ‪........‬إذ‬\n     ‫ا مــا‬‫مررنــا بــه الحقـ ًا هــذا مــا أجــاب بــه وأجــاب املدعــى عليــه ‪ .......‬قائـ ً‬\n     ‫ذكــره املدعــي العــام مــن قيامــي بالســرقة صحيــح فقــد حضــرت مــع ‪.....‬‬\n     ‫وذكرنــا ل‪ ........‬بأنــا سنســرق أحــد الســيارات وأبــدا اســتعداده بقيــادة‬\n     ‫الســيارة وقمــت بفتــح الســيارة مــع ‪........‬وقــد كانــت مفتوحــة وقــام ‪........‬‬\n     ‫بتشــغيلها ثــم بعــد تعطلهــا حاولــت فتــح فرامــل الســيارة الثانيــة التــي مــن‬\n     ‫نــوع ‪ ......‬إال أنــي لــم أمتكــن وقمــت بتحريكهــا مســافة قصيــرة جــد ًا‬\n     ‫ا مــا ذكــره املدعــي‬     ‫هــذا مــا أجــاب بــه وأجــاب املدعــى عليــه ‪........‬قائ ـ ً‬\n     ‫العــام مــن قيامــي بالســرقة صحيــح فقــد قمــت رفــق ‪........‬بفتــح الســيارة‬\n     ‫وكانــت مفتوحــة وقمــت بتشــغيلها ثــم بعــد تعطلهــا فتحــت ســيارة‬\n     ‫أخــرى وقــد كانــت مفتوحــة وقمــت بالتفحيــط عليهــا هــذا مــا أجــاب‬\n     ‫ا مــا ذكــره املدعــي العــام يف دعــواه‬         ‫بــه وأجــاب املدعــى عليــه ‪........‬قائـ ً‬\n     ‫ضــدي مــن قيامــي بالســرقة غيــر صحيــح ولقــد مــر بــي املدعــى عليهــم‬\n     ‫بالســيارة التــي مــن نــوع ‪ ......‬وكنــت أعلــم بقيامهــم بســرقتها وقمــت‬\n     ‫بالتفحيــط عليهــا هــذا مــا أجــاب بــه وبــرده علــى املدعــي العــام أفــاد‬\n     ‫ا إنــكار املنكــر غيــر صحيــح والصحيــح مــا جــاء يف دعــواي هــذا‬                 ‫قائـ ً‬\n     ‫مــا أفــاد بــه وبســؤال املدعــي العــام عــن بينتــه علــى طبــق دعــواه يف حــق‬\n     ‫مــن أنكــر ويف حــق مــن لــم ينكــر لقصورهــم عــن ســن الرشــد ســوى‬\n     ‫ا لــدي شــاهد واحــد واعترافــات‬              ‫املدعــى عليــه األول ‪........‬فقــرر قائ ـ ً‬\n     ‫املدعــى عليهــم هــذا مــا قــرره وباالطــاع علــى اعتــراف املدعــى عليــه‬\n     ‫األول املــدون علــى الصحيفــة رقــم ‪ 9‬مــن ملــف التحقيــق املرفــق باملعاملــة‬\n     ‫باللفــة رقــم ‪ 1‬وإفــادة الشــاهد املدونــة علــى الصحيفــة رقــم ‪10-11‬‬\n\n\n‫‪79‬‬\n\f‫مــن ملــف التحقيــق املرفــق باملعاملــة باللفــة رقــم ‪ 4‬ولــم أجــد فيهمــا مــا‬\n‫يثبــت دعــوى املدعــي العــام فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n‫وإلقــرار املدعــى عليــه األول ‪........‬يف إجابتــه عــن الدعــوى وهــو بالــغ‬\n‫عاقــل بقيامــه باملراقبــة يف الســرقة وبتفحيطــه علــى ســيارة مســروقة‬\n‫وألن اإلقــرار حجــة علــى املقــر وال عــذر ملــن أقــر وألن مــن شــرط صحــة‬\n‫اإلقــرار أن يكــون مــن مكلــف ولعــدم حتقــق شــرط التكليــف يف حــق‬\n‫كل مــن املدعــى عليــه ‪........‬و‪........‬و‪........‬وملــا قــرره األصحــاب رحمهــم‬\n‫اهلل بــأن مــن ادعــى علــى صبــي فــإن دعــواه تســمع بالبينــة وألنــه ال بينــة‬\n‫تامــة يف هــذه الدعــوى إذ أقاريــر املدعــى عليهــم قــد اختــل شــرطها ســوى‬\n‫مــا كان مــن إقــرار املدعــى عليــه األول وإفــادة الشــاهد لــم تتضمــن قيــام‬\n‫املدعــى عليهــم بالســرقة وعلــى فــرض تضمنهــا فهــي شــهادة لــم يكمــل‬\n‫نصابهــا لــذا وجلميــع مــا تقــدم فقــد ثبــت لــدي مراقبــة املدعــى عليــه األول‬\n‫‪........‬يف الســرقة وتفحيطــه علــى ســيارة مســروقة وقــررت أو ًال تعزيــر‬\n‫املدعــى عليــه األول ‪........‬بســجنه مــدة عشــرين يومـ ًا يحتســب منهــا مــدة‬\n‫إيقافــه بســبب هــذه القضيــة وجلــده ثالثــن جلــدة دفعــة واحــدة ثاني ـ ًا‬\n‫صــرف النظــر عــن تعزيــر بقيــة املدعــى عليهــم لعــدم الثبــوت ومبــا ذكــر‬\n‫حكمــت وبعــرض احلكــم علــى الطرفــن اعتــرض عليــه املدعــي العــام‬\n‫وطلــب اســتئنافه دون تقــدمي الئحــة اعتراضيــة وقنــع بــه املدعــى عليهــم‬\n‫وســيتم بعــث كامــل املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم‬\n‫حســب املتبــع وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                         ‫أجمعــن ‪.‬‬\n\n\n\n\n                                                                                       ‫‪80‬‬\n\f     ‫احلمــدهلل وحــده وبعــد لــدي أنــا ‪........‬القاضــي باحملكمــة اجلزائيــة‬\n     ‫بالقطيــف وبنــاء علــى قــرار التكليــف رقــم ‪ 33/18‬يف ‪1433/12/18‬ه ـ‬\n     ‫بالقيام بعمل املكتب القضائي الرابع مدة خمسة أيام ابتداء من تاريخ‬\n     ‫‪1433/12/18‬ه ـ لقــد عــادت املعاملــة من محكمة االســتئناف باملنطقة‬\n     ‫الشرقية بكتاب فضيلة رئيسها رقم ‪ ........‬يف ‪1433/11/10‬هـ املقيدة‬\n     ‫يف هــذه احملكمــة برقــم ‪ ........‬يف ‪1433/11/14‬ه ـ واحملالــة من فضيلة‬\n     ‫الرئيــس وبرفقهــا القــرار الصــادر مــن أصحــاب الفضيلــة قضــاة الدائــرة‬\n     ‫اجلزائيــة الثانيــة رقــم ‪ ........‬يف ‪1433/10/18‬ه ـ ونصــه بعــد املقدمــة‬\n     ‫وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة لوحــظ مــا يلــي أو ًال‬\n     ‫مــا حكــم بــه فضيلتــه علــى املدعــى عليهــم الثالثــة وهــم ‪ ........‬و‪........‬‬\n     ‫و‪........‬مــن صــرف النظــر محــل نظــر حيــث أن لهــم اعترافــات حيــث ان‬\n     ‫كل مــن ‪........‬و‪ ........‬اعترفــا بالســرقة و‪ ........‬اعتــرف بعلمــه بالســرقة‬\n     ‫وقــام بالتفحيــط بالســيارة املســروقة وكونهــم أحــداث ال يعفيهــم مــن‬\n     ‫العقوبــة ثانيــا مــا حكــم بــه فضيلتــه علــى املدعــى عليــه ‪........‬قليــل جــد ًا‬\n     ‫فعلــى فضيلتــه مالحظــة مــا ذكــر وإكمــال الــازم ومــن ثــم إعــادة‬\n     ‫املعاملــة إلكمــال الــازم ومــن ثــم إعــادة املعاملــة إلكمــال الزمهــا واهلل‬\n     ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم قاضــي‬\n     ‫اســتئناف ‪........‬ختمــه وتوقيعــه قاضــي اســتئناف ‪........‬ختمــه وتوقيعــه‬\n     ‫رئيــس الدائــرة ‪........‬ختمــه وتوقيعــه أ‪.‬ه ـ وأجيــب أصحــاب الفضيلــة‬\n     ‫وفقنــي اهلل وإياهــم إلصابــة الصــواب عمــا ذكــروه يف أو ًال بأنــه ســبق‬\n     ‫وأن ذكــرت يف تســبيب احلكــم بأنــه وإن اعتــرف غيــر احملكــوم عليــه‬\n     ‫يف هــذه القضيــة بعقوبــة باجلنايــة املنســوبة إليهــم إال أن اعترافهــم بهــا‬\n     ‫اعتــراف لــم يكتمــل شــرطه مــن تكليــف املقــر ولــذا فــا يعتــد بــه مــع‬\n\n\n‫‪81‬‬\n\f‫اختــال الشــرط ولــم يحضــر املدعــي العــام أي بينــة تعضــد دعــواه ســوى‬\n‫أقاريرهــم وقــد علــم مــا فيهــا فــا يصــح أن تكــون مســتند ًا للحكــم‬\n‫عليهــم وقــد قــرر األصحــاب رحمهــم اهلل أن مــن شــرط صحــة اإلقــرار‬\n‫التكليــف جــاء يف املقنــع املطبــوع مــع الشــرح ‪ : 142/30‬يصــح اإلقــرار‬\n‫مــن كل مكلــف مختــار غيــر الصبــي واملجنــون فــا يصــح إقرارهمــا‬\n‫إال أن يكــون الصبــي مأذون ـ ًا لــه يف البيــع والشــراء فيصــح إقــراره يف‬\n‫قــدر مــا أذن لــه دون مــا زاد أ‪.‬ه ـ وقــال يف الشــرح فأمــا الطفــل واملجنــون‬\n‫فــا يصــح إقرارهمــا وكذلــك املبرســم والنائــم واملغمــى عليــه ال نعلــم يف‬\n‫الف ـ ًا أ‪.‬ه ـ وأجيــب عمــا ذكــره أصحــاب الفضيلــة عمــا ذكــروه‬        ‫هــذا خ ً‬\n‫يف ثانيـ ًا بــأن احملكــوم عليــه جــرى التخفيــف عنــه حلداثــة ســنه وصغــره‬\n‫ولعــدم وجــود ســوابق جنائيــة عليــه وهمــا ســببان للتخفيــف واملقصــود‬\n‫مــن العقوبــة إصــاح اجلانــي ويف القــدر احملكــوم بــه مــع حداثــة ســنه ردع‬\n‫لــه مــن العــود ملثــل مــا بــدر منــه أو نظيــره ال ســيما مــع مــا ظهــر مــن يف‬\n‫مجلــس احلكــم مــن نــدم وتأثــر بعــد إعالمــه باحلكــم هــذا مــا لــزم جوابـ ًا‬\n‫علــى مالحظــة أصحــاب الفضيلــة ولفضيلتهــم فائــق التقديــر واالحتــرام‬\n‫وللبيــان حــرر يف ‪1433/12/22‬ه ـ وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                                                     ‫وعلــى آلــه وصحبــه أجمعــن ‪.‬‬\n‫احلمــد هلل وحــده وبعــد لقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫باملنطقــة الشــرقية بكتــاب فضيلــة رئيســها رقــم (‪ )..............‬يف‬\n‫‪1434/3/2‬ه ـ واملقيــدة يف هــذه احملكمــة برقــم (‪ )..............‬يف‬\n‫‪1434/3/7‬ه ـ واحملالــة مــن فضيلــة الرئيــس وبرفقهــا القــرار الصــادر‬\n‫مــن أصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة الثانيــة برقــم ‪..............‬‬\n‫يف ‪1434/2/24‬ه ـ ونصــه بعــد املقدمــة وبدراســة القــرار وصــورة ضبطــه‬\n\n\n                                                                                         ‫‪82‬‬\n\f     ‫و اوراق املعاملــة وباإلطــاع علــى مــا اجــاب بــه فضيلتــه علــى قرارنــا رقــم‬\n     ‫‪/ ..............‬ج‪/2‬ب وتاريــخ ‪1433/10/18‬ه ـ وبعــد االطــاع علــى خطــاب‬\n     ‫فضيلــة رئيــس احملكمــة اجلزائيــة بالقطيــف املشــار إليــه اعــاه فــإن‬\n     ‫الدائــرة تقــرر أن علــى مــن اصــدر احلكــم ابتــداء اجلــواب علــى املالحظــة‬\n     ‫ثــم اعــادة املعاملــة إلكمــال الزمهــا واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n     ‫محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/2/24‬ه ـ قاضــي اســتئناف‬\n     ‫‪........‬ختمــه وتوقيعــه قاضــي اســتئناف ‪........‬ختمــه وتوقيعــه رئيــس‬\n     ‫الدائــرة ‪........‬ختمــه وتوقيعــه أ‪.‬ه ـ وبرفقهــا قــرار اصحــاب الفضيلــة رقــم‬\n     ‫‪ ..............‬يف ‪1434/1/20‬ه ـ ونصــه بعــد املقدمــة لوحــظ أن مــا اجــاب بــه‬\n     ‫فضيلتــه عــن املالحظــة األولــى غيــر مقنــع ألنــه وإن ســلمنا بــأن املدعــي‬\n     ‫العــام لــم يحضــر مــا يعضــد دعــواه إال أن اعتــراف املدعــى عليهــم وإن‬\n     ‫لــم يكتمــل شــرطه لإلثبــات فانــه يوجــه التهمــة عليهــم مبــا نســب اليهــم‬\n     ‫ويوجــب تعزيرهــم فعلــى فضيلتــه مالحظــة مــا ذكــر وإكمــال مــا يلــزم‬\n     ‫ومــن ثــم إعــادة املعاملــة إلكمــال الزمهــا وصلــى اهلل علــى نبينــا محمــد‬\n     ‫وآلــه وصحبــه وســلم حــرر يف ‪1434/1/20‬ه ـ قاضــي اســتئناف ‪........‬‬\n     ‫ختمــه وتوقيعــه قاضــي اســتئناف ‪........‬ختمــه وتوقيعــه رئيــس الدائــرة‬\n     ‫‪........‬ختمــه وتوقيعــه أ‪ .‬ه ـ وأجيــب أصحــاب الفضيلــة وفقنــي اهلل وإياهــم‬\n     ‫إلصابــة الصــواب بــأن االعتــراف مبفــرده مــع اختــال شــرطه ال يوجــب‬\n     ‫توجــه الشــبهة كــون الشــرط عنــد االصوليــن مــا يلــزم مــن عدمــه العــدم‬\n     ‫وال يلــزم مــن وجــوده وجــود وال عــدم وعليــه فــإذا عــدم الشــرط لــم يقــم‬\n     ‫للمشــروط قائمــة ولــذا فــا تتجــه الشــبهة بــه مبفــرده مــا لــم يعضــد‬\n     ‫بعاضــد وعلــى فــرض توجــه الشــبهة بــه مــع فقــد شــرطه فهــي شــبهة‬\n     ‫ضعيفــة وقــد قــرر الســيوطي رحمــه اهلل يف أشــباهه بأنــه ال أثــر للشــبهة‬\n\n\n‫‪83‬‬\n\f‫اذا لــم تكــن قويــة هــذا مــا لــزم جوابـ ًا علــى مالحظــة أصحــاب الفضيلــة‬\n‫ولفضيلتهــم فائــق التقديــر واالحتــرام وللبيــان حــرر يف ‪1434/3/21‬ه ـ‬\n       ‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة‬\n‫املقيــدة لــدى احملكمــة برقــم ‪/34/853246‬ج‪ 2‬وتاريــخ ‪1434/4/8‬ه ـ‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة القطيــف برقــم‬\n‫‪ 34582659‬وتاريــخ ‪1434/4/3‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ‪ .......... /‬املســجل برقــم ‪..............‬‬\n‫كل‬\n ‫ٍ‬        ‫وتاريــخ ‪1433/9/17‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد‬\n‫مــن‪......../1‬و‪......../2‬و‪ ......../3‬و‪......../4‬يف قضيــة ســرقة وقــد تضمــن‬\n‫القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار‬\n‫وصــورة ضبطــه وأوراق املعاملــة وباإلطــاع علــى مــا أجــاب بــه فضيلتــه‬\n‫علــى قرارنــا رقــم ‪ ..............‬ج‪/2‬ب وتاريــخ ‪1434/2/24‬ه ـ وقرارنــا‬\n‫رقــم ‪ ..............‬وتاريــخ ‪1434/01/20‬ه ـ وقرارنــا رقــم ‪ ..............‬وتاريــخ‬\n‫‪1433/10/18‬ه ـ قررنــا املصادقــة علــى احلكــم بعــد اإليضــاح األخيــر‪.‬‬\n‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف‬\n                                                                   ‫‪1434/4/13‬هــ‪.‬‬\n\n\n\n\n                                                                                         ‫‪84‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":75,"source_page_end":84,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a78e312c70c21ebd938d183d37666f44fe91b94dd724fdcd7abf3fdad42c8ff6","normalized_text_hash":"bdde72333b22a0250c43b79792f22a148846dc4e21ec867999de0e4ebd79598f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p75-33412831"},{"id":"32f7ae6a-6bba-5abb-9e22-004bad4a8744","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -نشل -نشل نقود من بيت اهلل احلرام -تشكيل عصابي - رجوع عن إقرار -وجود سوابق قضائية -درء حد السرقة -تعزير بالسجن واجللد والتشهير ومصادرة املبالغ وإيداع املبالغ يف اخلزنة العامة للدولة.","document_number":"34183961","case_number":"33581292","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/9","year":"1434","subject":"سرقة -نشل -نشل نقود من بيت اهلل احلرام -تشكيل عصابي - رجوع عن إقرار -وجود سوابق قضائية -درء حد السرقة -تعزير بالسجن واجللد والتشهير ومصادرة املبالغ وإيداع املبالغ يف اخلزنة العامة للدولة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34183961 :‬تاريخه ‪1434/4/9 :‬هـ‬\n                         ‫رقم الدعوى ‪33581292 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34384288‬تاريخه‪1434/12/23 :‬هـ‬\n\n\n\n     ‫ســرقة ‪ -‬نشــل ‪ -‬نشــل نقــود مــن بيــت اهلل احلــرام ‪ -‬تشــكيل عصابــي ‪-‬‬\n     ‫رجــوع عــن إقــرار ‪ -‬وجــود ســوابق قضائيــة ‪ -‬درء حــد الســرقة ‪ -‬تعزيــر‬\n     ‫بالســجن واجللــد والتشــهير ومصــادرة املبالــغ وإيــداع املبالــغ يف اخلزنــة‬\n                                                                    ‫العامــة للدولــة‪.‬‬\n\n\n\n                                ‫‪1 .1‬املادة(‪ )50‬من النظام األساسي احلكومي‪.‬‬\n                                  ‫‪ 2 .2‬املادة(‪ )3‬من نظام اإلجراءات اجلزائية‪.‬‬\n                                ‫‪3 .3‬املادة(‪ )159‬من نظام اإلجراءات اجلزائية‪.‬‬\n                                ‫‪4 .4‬املادة(‪ )205‬من نظام اإلجراءات اجلزائية‪.‬‬\n                                ‫‪5 .5‬املادة(‪ )219‬من نظام اإلجراءات اجلزائية‪.‬‬\n     ‫ـدرا‬\n       ‫‪6 .6‬ومــن املتقــرر أن التعزيــر عقوبــة مفوضــة للقضــاة واحلــكام قـ ً‬\n     ‫وحتديـ ًـدا‪ ،‬ومــا دام أنهــا خاضعــة لنظرهــم‪ ،‬فهــم املنــوط بهــم‬\n     ‫مالحظــة املناســب وتقديــره واعتمــاده‪ ،‬وإليهــم يرجــع وضــع‬\n     ‫العقوبــة املالئمــة للظــروف‪ ،‬واحملققــة للمقاصــد حســب األحــوال‬\n     ‫املختلفــة‪ .‬فقــد يكــون التعزيــر بالضــرب أو احلبــس أو التوبيــخ أو‬\n     ‫التشــهير أو ببعضهــا أو بهــا جمعيــا وغيــر ذلــك‪ ،‬حســب اختــاف‬\n     ‫مراتــب النــاس‪ ،‬واختــاف املعاصــي‪ ،‬واختــاف اإلعصــار واألمصــار‪.‬‬\n     ‫وعلــى ذلــك فالتعزيــر بالتشــهير جائــز إذا علــم احلاكــم أن‬\n     ‫املصلحــة فيــه‪ ،‬وهــذا احلكــم هــو بالنســبة لــكل معصيــة ال حــد فيهــا‬\n\n‫‪85‬‬\n\f‫وال كفــارة يف اجلملــة‪ .‬ينظــر يف تقريــر هــذا املعنــى ـ أي تفويــض‬\n‫وحتديدا ‪( -:‬السياســة الشــرعية‪،‬‬\n                              ‫ً‬         ‫قدرا‬\n                                         ‫العقوبــة التعزيريــة للقضــاء ً‬\n‫البــن تيميــة ص ‪ ،91‬حاشــية ابــن عابديــن ‪ ،183 / 3‬ونهايــة احملتــاج‬\n‫للرملــي ‪ ،175 - 174 / 7‬واألحــكام الســلطانية للمــاوردي ص ‪،224‬‬\n                                        ‫واحلســبة البــن تيميــة ص ‪.) 38‬‬\n‫‪7 .7‬قــال املــاوردي ‪ -‬رحمــه اهلل ‪ ( :-‬لألميــر إذا رأى مــن الصــاح يف ردع‬\n‫الســفلة‪ :‬أن يشــهرهم وينــادي عليهــم بجرائمهــم‪ ،‬ســاغ لــه ذلــك )‬\n‫[ األحــكام الســلطانية للمــاوردي ص ‪ .]ٍ 221‬وقــال أيضــا‪ ( :‬يجــوز يف‬\n‫نــكال التعزيــر أن يجــرد مــن ثيابــه‪ ،‬إال قــدر مــا يســتر عورتــه‪ ،‬ويشــهر‬\n           ‫يف النــاس‪ ،‬وينــادى عليــه بذنبــه إذا تكــرر منــه ولــم يتــب )‪.‬‬\n‫‪8 .8‬وقــال البهوتــي‪ -‬رحمــه اهلل ‪ ( :-‬القــوادة ‪ -‬التــي تفســد النــاس‬\n‫والرجــال ‪ -‬أقــل مــا يجــب فيهــا الضــرب البليــغ‪ ،‬وينبغــي شــهرة‬\n‫ذلــك بحيــث يســتفيض يف الرجــال والنســاء لتجتنــب ) ( كشــاف‬\n                                                           ‫القنــاع ‪.) 6/127‬‬\n‫‪9 .9‬قــال‪ :‬املوفــق ابــن قدامــه‪ -‬رحمــه اهلل ‪ ( :-‬فمتــى ثبــت عنــد احلاكــم‬\n‫عــن رجــل أنــه شــهد بــزور عمــدا عــزره وشــهره يف قــول أكثــر أهــل‬\n‫العلــم‪ ،‬روي ذلــك عــن عمــر رضــي اهلل عنــه‪ ،‬وبــه يقــول شــريح‬\n‫والقاســم بــن محمــد وســالم بــن عبــد اهلل واألوزاعــي وابــن أبــي‬\n‫ليلــى ومالــك والشــافعي وعبــد امللــك بــن يعلــي قاضــي البصــرة )‬\n                          ‫[ املغنــي يف شــرح مختصــر اخلرقــي ‪.261/9‬‬\n‫‪1010‬وقــال البهوتــي رحمــه اهلل‪( :‬إذا عــزر مــن وجــب عليــه التعزيــر‬\n‫وجــب علــى احلاكــم أن يشــهره ملصلحــة كشــاهد زور ليجتنــب)‪.‬‬\n                                          ‫[كشــاف القنــاع ‪.]127-125/6‬‬\n\n\n                                                                                  ‫‪86‬‬\n\f     ‫‪1111‬قــال القــرايف رحمــه اهلل‪( :‬إن التعزيــر يختلــف باختــاف األعصــار‬\n     ‫إكرامــا يف بلــد آخــر‪ ،‬كقطــع‬\n                                 ‫ً‬         ‫واألمصــار‪ ،‬فــرب تعزيــر يف بلــد يكــون‬\n     ‫الطيلســان ليــس تعزيـ ًـرا يف الشــام فإنــه إكــرام‪ ،‬وكشــف الــرأس‬\n     ‫باألندلــس ليــس هوانــا ومبصــر والعــراق هــوان ) نقلــه ابــن فرحــون‬\n     ‫ثــم عقــب عليــه بقولــه‪( :‬والتعزيــر ال يختــص بفعــل معــن وال قــول‬\n     ‫معــن فقــد عــزر رســول اهلل ‪ -‬بالهجــر‪ ،‬وذلــك يف حــق الثالثة الذين‬\n     ‫يومــا ال‬\n           ‫ذكرهــم اهلل تعالــى يف القــرآن الكــرمي‪ ،‬فهجــروا خمســن ً‬\n           ‫يكلمهــم أحــد) [تبصــرة احلــكام‪ ،‬البــن فرحــون ‪.] 2 / 295 ،296‬‬\n     ‫‪1212‬وقــال الشــربيني رحمــه اهلل‪( :‬يجتهــد اإلمــام يف جنــس التعزيــر‬\n     ‫ـرعا فيجتهــد يف ســلوك األصــح فلــه‬       ‫وقــدره‪ ،‬ألنــه غيــر مقــدر شـ ً‬\n     ‫أن يشــهر يف النــاس مــن أدى اجتهــاده إليــه) [مغنــى احملتــاج شــرح‬\n                                                      ‫املنهــاج للشــربيني‪.]4/192‬‬\n     ‫‪1313‬مــا نصــت عليــه املــادة العشــرين مــن نظــام مكافحــة الغــش التجــاري‬\n     ‫الصــادر باملرســوم امللكــي رقــم‪ :‬م ‪ 11/‬يف ‪1404/5/29‬هــ‪( :‬تشــهر وزارة‬\n     ‫طبقا ألحكام‬‫التجــارة باملخالــف الصــادر ضــده قــرار نهائــي باإلدانــة ً‬\n     ‫هــذا النظــام والئحتــه بوســيلة علــى األقــل مــن وســائل اإلعــام)‪،‬‬\n                                     ‫ويكــون النشــر علــى نفقــة احملكــوم عليــه‪.‬‬\n     ‫‪1414‬مــا نصــت عليــه املــادة الرابعــة مــن نظــام مكافحــة التســتر الصــادر‬\n     ‫باملرســوم امللكــي رقــم م‪ 22/‬يف ‪1425/5/4‬هــ‪( :‬ينشــر منطــوق قــرار‬\n     ‫العقوبــة يف واحــدة أو أكثــر مــن الصحــف احملليــة علــى نفقــة‬\n                                                                        ‫املخالــف)‪.‬‬\n     ‫‪ 1515‬مــا جــاء يف املــادة احلاديــة والعشــرون بعــد املائــة مــن نظــام األوراق‬\n     ‫التجاريــة املضافــة باملرســوم امللكــي رقــم م‪ 45/‬يف ‪1409/9/12‬هــ‪:‬‬\n\n\n‫‪87‬‬\n\f‫(يجــوز احلكــم بنشــر أســماء األشــخاص الذيــن يصــدر بحقهــم‬\n‫حكــم اإلدانــة مبوجــب هــذا النظــام‪ ،‬ويحــدد احلكــم كيفيــة ذلــك)‪.‬‬\n‫أيضــا علــى قــرار مجلــس‬ ‫‪1616‬إن احلكــم بعقوبــة التشــهير مســتند ً‬\n‫القضــاء األعلــى بهيئتــه العامــة رقم ‪ 187 /40‬يف ‪1414/3/2‬هـ املبلغ‬\n‫للمحاكــم بتعميــم وزارة العــدل رقــم ‪/ - 8‬ت‪ 158/‬يف ‪1414/5/8‬ه ـ‬\n‫ونصــه‪( :‬تلقينــا خطــاب ســماحة رئيــس مجلــس القضــاء األعلــى‬\n‫رقــم ‪ 1/387‬يف ‪1414/3/28‬ه ـ ومشــفوعة قــرار املجلــس بهيئتــه‬\n                    ‫العامــة رقــم ‪ 187/40‬يف ‪1414/3/2‬ه ـ املتضمــن‪:‬‬\n‫‪ -1‬أن القضــاة إذا نصــوا يف األحــكام الصــادرة منهــم علــى تعيــن‬\n                                   ‫مــكان اجللــد فينبغــي األخــذ بــه‪.‬‬\n‫‪ -2‬ينبغــي عنــد إصــدار مثــل هــذه األحــكام مراعــاة كالم أهــل‬\n‫العلــم يف ذلــك ومراعــاة مــا يناســب اجلرميــة مــن التشــهير إذ‬\n‫كان املقــام يســتدعي ذلــك حســب شــناعة اجلرميــة أو ســوابق‬\n‫املجــرم ودرجــة انتشــار اجلرميــة مــع مراعــاة تــرك تعيــن املــكان‬\n‫إذا كانــت العقوبــة خفيفــة أو كانــت حــال إيقاعهــا تقتضــي‬\n‫غيــر التعيــن وذلــك مــرده لنظــر القاضــي واجتهــاده )‪ .‬يراجــع‬\n            ‫التصنيــف املوضوعــي لتعاميــم وزارة العــدل‪.1/785 :‬‬\n‫‪1717‬أن أوجــه احلكــم بعقوبــة التشــهير علــى املدعــى عليهــم والتشــديد‬\n‫عليهــم بهــا مــع مــا تقــرر بحقهــم مــن عقوبــات تعزيزيــة أخــرى‪ ،‬هــو‬\n‫الظــروف املشــددة التــي حلقــت بجنايتهــم وبيانهــا كمــا يلــي‪ :‬أن‬\n‫املدعــى عليهــم لــم يراعــو حرمــة املــكان فقــد قامــوا باجلرميــة يف‬\n‫البيــت احلــرام‪ ،‬وقــد قــال اهلل تعالــى‪( :‬إن الذيــن كفــروا ويصــدون‬\n‫عــن ســبيل اهلل واملســجد احلــرام الــذي جعلنــاه للنــاس ســواء‬\n\n\n                                                                              ‫‪88‬‬\n\f     ‫العاكــف فيــه والبــاد ومــن يــرد فيــه باحلــاد بظلــم نذقــه مــن عــذاب‬\n     ‫أليــم ) [احلــج آيــة‪ ]25‬قــال القرطبــي رحمــه اهلل‪( :‬وهــذا اإلحلــاد‬\n     ‫والظلــم يجمــع جميــع املعاصــي مــن الكفــر إلــى الصغائــر‪ ،‬فلعظــم‬\n     ‫حرمــة املــكان توعــد اهلل تعالــى علــى نيــة الســيئة فيــه) [اجلامــع‬\n     ‫ألحــكام القــرآن ‪ ]12/36‬ونقــل عــن ابــن عبــاس رضــي اهلل عنهمــا يف‬\n     ‫تفســير هــذه اآليــة‪( :‬هــو أن تســتحل مــن احلــرم مــا حــرم اهلل عليــك‬\n     ‫مــن لســان أو قتــل‪ ،‬فتظلــم مــن ال يظلمــك وتقتــل مــن ال يقتلــك‬\n     ‫فــإذا فعــل ذلــك فقــد وجــب لــه العــذاب األليــم) [تفســير ابــن كثيــر‬\n                                                                         ‫‪. ] 5/411‬‬\n     ‫‪1818‬ارتــكاب اجلرميــة املعاقــب عليهــا مــن خــال عصابــة منظمــة لهــذا‬\n                                                                          ‫الغــرض‪.‬‬\n     ‫‪1919‬ســبق صــدور أحــكام قضائيــة باإلدانــة بحــق اثنــن مــن اجلنــاة يف‬\n                                                                ‫جرائــم مماثلــة‪.‬‬\n     ‫‪2020‬انتشــار هــذه اجلرميــة يف بنــي جنســهم‪ ،‬والتشــهير بهــم يف وســائل‬\n     ‫اإلعــام الصــادرة بلغــة مقــروءة لهــم‪ ،‬تــردع مــن تســول لــه نفســه‬\n                                        ‫منهــم القيــام مبثــل هــذه اجلنايــة‪.‬‬\n\n\n\n     ‫ادعــى املدعــي العــام علــى املدعــى عليهــم بتكويــن عصابــة للنشــل يف‬\n     ‫املســجد احلــرام‪ ،‬وذلــك بقيــام املدعــى األول بالنشــل مــن زوار بيــت اهلل‬\n     ‫احلــرام‪ ،‬وقيــام الثانــي باســتالم مــا يتــم نشــله وإخفــاؤه يف مالبســه‪،‬‬\n     ‫والثالــث بــدور املراقبــة والتغطيــة عليهمــا أثنــاء النشــل ‪ ،‬حيــث تضمــن‬\n     ‫القبــض علــى املدعــى عليهــم أعــاه مشــاهدتهم مــن قبل مأمــوري البحث‬\n\n‫‪89‬‬\n\f‫عندمــا كان املدعــى عليهــم األول ميــد يــده اليمنــى إلــى اجليــب األيســر‬\n‫للمجنــي عليــه ‪ ،‬ثــم رفــع محفظتــه وأخذهــا بيــده اليســرى وأعطاهــا‬\n‫للمدعــى عليــه الثانــي الــذي وضعهــا يف جيــب بنطالــه اخللفــي‪ ،‬وكان‬\n‫املدعــى عليــه الثالــث يتســتر عليهمــا ‪ ،‬وعند القبــض عليه وجد احملفظة‬\n‫بحــوزة املدعــى عليــه الثانــي كمــا وجــد معــه رخصــة اإلقامــة‪ ،‬وبطاقــة‬\n‫التعريــف اخلاصــة باملجنــي عليــه‪ ،‬كمــا وجــد مــع املدعــى عليــه األول‬\n‫مبالــغ ماليــة وعمــات مختلفــة‪ ،‬وهاتــف نقــال‪ ،‬وبطاقــات ال تخصــه‪،‬‬\n‫ووجــد مــع املدعــى عليــه الثالــث مبالغ مالية وهاتــف نقال ‪ ،‬طلب املدعي‬\n‫العــام إقامــة حــد الســرقة علــى املدعــى عليهــم األول والثانــي ‪ ،‬وتعزيــر‬\n‫املدعــى عليــه الثالــث لقــاء مــا نســب إليــه‪ ،‬واحلكــم بإيــداع مــا مت ضبطه‬\n‫بحوزتهــم مــن مبالــغ ماليــة وهاتــف نقــال يف بيــت مــال املســلمني ‪ ،‬أنكــر‬\n‫املدعــى عليهــم مــا جــاء يف دعــوى املدعــي العــام ‪ ،‬طلــب مــن املدعــي‬\n‫معروفــا بالعدالــة ‪ -‬شــهد‬\n                        ‫ً‬        ‫ـاهدا ‪-‬‬\n                                    ‫العــام البينــة علــى دعــواه‪ ،‬فأحضــر شـ ً‬\n‫بصحــة الواقعــة ‪ ،‬أنكــر املدعــى عليهــم مــا جــاء يف شــهادة الشــاهد ‪،‬‬\n‫مت االطــاع علــى أوراق املعاملــة ومــن ضمنهــا إقــرارات املدعــى عليهــم‬\n‫حتقيقــا وبعرضهــا عليهــم أنكــروا مــا جــاء فيهــا ‪ ،‬حكمــت احملكمــة‬   ‫ً‬\n‫بــرد طلــب املدعــي العــام إقامــة حــد الســرقة علــى املدعــى عليهــم األول‬\n‫والثانــي‪ ،‬وقضــت بتعزيــر املدعــى عليهــم بالســجن واجللــد واملصــادرة ملــا‬\n‫مت ضبطــه معهــم‪ ،‬التعزيــر بالتشــهير والتوصيــة باإلبعــاد عــن البــاد بعــد‬\n‫انتهــاء محكوميتهــم‪ ،‬قنــع املدعــى عليهــم باحلكــم وقــرر املدعــي العــام‬\n‫اعتراضــه علــى احلكــم بالئحــة اعتراضيــة عــادت املعاملــة مــن محكمة‬\n‫االســتئناف باملالحظــة ومتــت اإلجابــة عليهــا‪ ،‬ومت تصديــق احلكــم مــن‬\n                                                         ‫محكمــة االســتئناف‪.‬‬\n\n\n                                                                                    ‫‪90‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلدينــا نحــن القضــاة باحملكمــة العامــة مبكــة‬\n     ‫املكرمــة بنــاء علــى املعاملــة احملالــة إلينــا مــن فضيلــة الرئيــس برقــم يف‬\n     ‫‪1433/9/19‬ه ـ واملقيــدة بهــذه احملكمــة برقــم يف ‪1433/9/19‬ه ـ‬\n     ‫عليــه ففــي يــوم االربعــاء املوافــق ‪1433/10/18‬ه ـ افتتحــت اجللســة‬\n     ‫الســاعة التاســعة صباحــا وفيهــا حضــر املدعــى العــام بهــذه احملكمــة‬\n     ‫املكلــف باالدعــاء العــام مبوجــب خطــاب التكليــف الصــادر مــن رئيــس‬\n     ‫فــرع هيئــة التحقيــق مبكــة املكرمــة برقــم م‪ 41010/1/1‬يف‬\n     ‫‪1431/11/1‬ه ـ بدعــوى محــررة جــاء فيهــا ‪ :‬بصفتــي مدعيــا عامــا‬\n     ‫بدائــرة اإلدعــاء العــام مبكــة املكرمــة أدعــي علــى ‪)32( ،......../ 1:‬‬\n     ‫ســنة ‪ ،‬بنجالديشــي اجلنســية ‪ ،‬مبوجــب البطاقــة البديلــة رقــم (‪،)........‬‬\n     ‫موقــوف بســجون مكــة املكرمــة مبوجــب أمــر متديــد التوقيــف للمــرة‬\n     ‫الثانيــة رقــم (‪ )7/4/20/176‬وتاريــخ ‪1433/7/20‬ه ـ ‪ ،‬واعتبــار توقيفه‬\n     ‫مــن تاريــخ القبــض عليــه يف ‪1433/7/18‬ه ـ ‪ )48( ،......../ 2.‬ســنة ‪،‬‬\n     ‫بنجالديشــي اجلنســية ‪ ،‬مبوجــب البطاقــة البديلــة رقــم (‪ ،)........‬موقــوف‬\n     ‫بســجون مكــة املكرمــة مبوجــب أمــر متديــد التوقيــف للمــرة الثانيــة‬\n     ‫رقــم (‪ )7/4/20/177‬وتاريــخ ‪1433/7/20‬ه ـ ‪ ،‬واعتبــار توقيفــه مــن‬\n     ‫تاريــخ القبــض عليــه يف ‪1433/7/18‬ه ـ ‪ )49( ،......../ 3.‬ســنة ‪،‬‬\n     ‫بنجالديشــي اجلنســية ‪ ،‬مبوجــب البطاقــة البديلــة رقــم (‪ ،)........‬موقــوف‬\n     ‫بســجون مكــة املكرمــة مبوجــب أمــر متديــد التوقيــف للمــرة الثانيــة‬\n     ‫رقــم (‪ )7/4/20/178‬وتاريــخ ‪1433/7/20‬ه ـ ‪ ،‬واعتبــار توقيفــه مــن‬\n     ‫تاريــخ القبــض عليــه يف ‪1433/7/18‬ه ـ ‪ .‬وبتاريــخ ‪1433/7/18‬ه ـ تســلم‬\n\n‫‪91‬‬\n\f‫مخفــر شــرطة احلــرم كتــاب قائــد القــوة اخلاصــة ألمــن املســجد احلــرام‬\n‫رقــم (‪ /1224‬م س) املتضمــن القبــض علــى املدعــى عليهــم أعــاه‬\n‫ملشــاهدتهم مــن قبــل مأمــوري البحــث رقــم (‪ )778‬ورقــم (‪ )444‬ورقــم‬\n‫(‪ )152‬ورقــم (‪ )2054‬عندمــا كان املدعــى عليــه األول ميــد يــده اليمنــى‬\n‫إلــى اجليــب األيســر للمجنــي عليــه ‪ ،‬مصــري اجلنســية ‪ ،‬ثــم رفع محفظته‬\n‫وأخذهــا بيــده اليســرى وأعطاهــا للمدعــى عليــه الثانــي الــذي وضعهــا يف‬\n‫جيــب بنطالــه اخللفــي ‪ ،‬وكان املدعــى عليــه الثالــث يتســتر عليهمــا ‪،‬‬\n‫وعنــد القبــض عليهــم كانــت احملفظــة املنشــولة بحــوزة املدعــى عليــه‬\n‫الثانــي ‪ ،‬وبتفتيشــها وجــد بهــا رخصــة إقامــة وبطاقــة تعريــف مصريــة‬\n‫وبعــض األوراق اخلاصــة باملجنــي عليــه ‪ ،‬وبتفتيشــهم وجــد مــع املدعــى‬\n‫عليــه األول محفظــة ســوداء اللــون بهــا مبلــغ مالــي قــدرة (‪ )3255‬ثالثــة‬\n‫آالف ومائتــان وخمســة وخمســون ريــا ًال ســعودي ًا ‪ ،‬ومبلــغ (‪ )67‬ســبعة‬\n‫وســتون دوالر ًا أمريكيـ ًا ‪ ،‬ومبلــغ (‪ )3500‬ثالثــة آالف وخمســمائة عملــة‬\n‫بنجالديشــية ‪ ،‬وهاتــف نقــال مــن نــوع (‪ )....‬اســود اللــون ‪ ،‬ونظــارة‬\n‫شمســية‪ .‬ووجــد مــع املدعــى عليــه الثانــي بجيــب بنطالــه الداخلــي مبلــغ‬\n‫قــدره (‪ )1460‬ألــف وأربعمائــة وســتون ريــا ًال ســعودي ًا ‪ ،‬وبجيــب بنطالــه‬\n‫األميــن مبلــغ مالــي قــدره (‪ )400‬أربعمائــة دوالر ًا أمريكي ـ ًا ‪ ،‬ومبلــغ‬\n‫(‪ )140000‬مائــة وأربعــون ألــف دينــار ًا عراقيـ ًا ‪ ،‬ومحفظــة ســوداء اللــون‬\n‫بهــا مبلــغ مالــي قــدره (‪ )2‬ريــاالن ســعوديان ‪ ،‬ومبلــغ (‪ )689‬ســتمائة‬\n‫وتســعة وثمانــون عملــة ماليزيــة ‪ ،‬ومبلــغ (‪ )1‬دوالر عملــة برونــاى ‪،‬‬\n‫وبطاقــة باســم ‪ ،......../‬ماليــزي اجلنســية ‪ ،‬صــادرة مــن بــاده ‪ ،‬كمــا‬\n‫وجــد يف جيبــه األيســر محفظــة ســوداء اللــون بهــا مبلــغ مالــي قــدره‬\n‫(‪ )545‬خمســمائة وخمســة وأربعــون ريــا ًال ســعودي ًا ‪ ،‬ومبلــغ (‪)325‬‬\n\n\n                                                                                  ‫‪92‬‬\n\f     ‫ثالثمائة وخمســة وعشــرون عملة ســنغافورية ومبلغ (‪ )10‬عشــرة رياالت‬\n     ‫قطريــة ‪ ،‬وصــورة بطاقــة باســم ‪ ، ......../‬وبطاقــة صــرف (فيــزا) ‪ ،‬كمــا‬\n     ‫وجــد معــه محفظــة أخــرى بنيــة اللــون بهــا مبلــغ مالــي قــدره (‪)562‬‬\n     ‫خمســمائة واثنــان وســتون ريــا ًال ســعودي ًا ‪ ،‬وعــدد (‪ )4‬أربــع رخــص‬\n     ‫إقامــات للمدعــو ‪........ /‬وعائلتــه ‪ ،‬كمــا وجــد معــه محفظــة ثالثــة بنيــة‬\n     ‫اللــون بهــا مبلــغ مالــي قــدره (‪ )1775‬ألــف وســبعمائة وخمســة وســبعون‬\n     ‫ريــا ًال ســعودي ًا ‪ ،‬ومبلــغ (‪ )1000‬ألــف درهــم إماراتــي ‪ ،‬وبطاقــة صــراف‪،‬‬\n     ‫وهاتــف نقــال مــن نــوع (‪ )....‬اســود اللــون‪ .‬ووجــد مــع املدعــى عليــه الثالــث‬\n     ‫بجيــب ثوبــه العلــوي مبلــغ مالــي قــدره (‪ )89‬تســعة وثمانــون ريــا ًال ســعودي ًا‬\n     ‫‪ ،‬ويف ســرواله الداخلــي مبلــغ (‪ )800‬ثمامنائــة ريــا ًال ســعودي ًا ‪ ،‬وهاتــف‬\n     ‫نقــال مــن نــوع (‪(. )....‬جــرى فــرز أوراق مســتقلة إلقامتهــم بالبــاد بطريقة‬\n     ‫غيــر نظاميــة)‪ .‬وبعــرض احملافــظ املضبوطــة بحــوزة املدعــى عليهــم‬\n     ‫تعــرف املجنــي عليــه ‪ ........‬علــى احدهــا (جــرى تســليم احملفظــة املنشــولة‬\n     ‫للمجنــي عليــه ‪ ........‬مــن قبــل مــن قبل اجلهة القابضة لفة (‪ ، )4‬واحملفظة‬\n     ‫املنشــولة األخــرى للمجنــي عليــه ‪ ........‬لفــة (‪ )2‬ص‪.)3‬وبضبــط أقــوال‬\n     ‫املجنــي عليــه ‪ ، ........‬أفغانــي اجلنســية أفــاد بأنــه فقــد محفظــة بنيــة اللون‬\n     ‫وبهــا مبلــغ مالــي قــدره (‪ )562‬خمســمائة واثنــان وســتون ريــا ًال ســعودي ًا ‪،‬‬\n     ‫وعــدد (‪ )4‬رخــص إقامــات لــه ولعائلتــه وباســتجواب املدعــى عليــه األول‬\n     ‫أقــر بوضــع يــده اليمنــى علــى اجليــب األيســر ألحــد املعتمريــن ورفــع‬\n     ‫محفظتــه وأخذهــا بيــده اليســرى وإعطائهــا لزميلــه اآلخــر (املدعــى‬\n     ‫عليــه الثانــي) ‪ ،‬وذكــر أن املضبوطــات التــي وجــدت بحوزتــه تخصــه‬\n     ‫ولكنــه لــم يتعــرف عليهــا ‪ ،‬كمــا ذكــر انــه يعــرف املدعــى عليهمــا‬\n     ‫الثانــي والثالــث مــن الســابق ‪ ،‬ويســكنون مبدينــة جــده ‪ ،‬وتقابلــوا‬\n\n\n‫‪93‬‬\n\f‫جميع ـ ًا قبــل صــاة اجلمعــة أمــام شــركة ‪ ،....‬واتفقــوا علــى ممارســة‬\n‫النشــل داخل املســجد احلرام ‪ ،‬وبعد الصالة قاموا بالنشــل يف الســاحات‬\n‫الغربيــة أمــام البــاب رقــم (‪ . )86‬وباســتجواب املدعــى عليــه الثانــي أقــر‬\n‫باالتفــاق مــع املدعــى عليهمــا األول والثالــث علــى ممارســة النشــل‬\n‫باملســجد احلرام ‪ ،‬وكان دوره حفظ ما يتم نشــله ‪ ،‬كما أقر باســتالم‬\n‫احملفظــة املنشــولة مــن قبــل زميلــه (املدعــى عليــه األول) ووضعهــا يف‬\n‫جيــب بنطالــه اخللفــي ‪ ،‬وذكــر أن مــا يخصــه مــن املضبوطــات التــي‬\n‫وجــدت بحوزتــه مبلــغ وقــدره (‪ )1550‬ألــف وخمســمائة وخمســون ريــا ًال‬\n‫‪ ،‬وباقــي املبالــغ األخــرى واحملافــظ ممــا مت نشــله مــن املعتمريــن ‪.‬‬\n‫وباســتجواب املدعــى عليــه الثالــث اقــر باالتفــاق مــع املدعــى عليهمــا‬\n‫األول والثانــي علــى ممارســة النشــل باملســجد احلــرام ‪ ،‬وانــه مت حتديــد‬\n‫موعــد املقابلــة أمــام ‪ ،‬وكان دوره التســتر عليهمــا أثنــاء عمليــة النشــل ‪،‬‬\n‫وذكــر أن املضبوطــات التــي وجــدت بحوزتــه تخصه‪.‬وقــد انتهــى‬\n‫التحقيــق إلــى توجيــه اإلتهــام للمدعــى عليــه بتكويــن عصابــة للنشــل يف‬\n‫املســجد احلــرام ‪ ،‬وذلــك بقيــام املدعــى عليــه األول بالنشــل مــن زوار بيــت‬\n‫اهلل احلــرام ‪ ،‬وقيــام الثانــي باســتالم مــا يتــم نشــله وإخفائــه مبالبســه ‪،‬‬\n‫وجــدت بحوزتــه عنــد القبــض عليــه ‪ ،‬وقيــام الثالــث بــدور املراقبــة‬\n‫والتغطيــة عليهمــا أثنــاء النشــل ‪ ،‬واملؤيــد بقــرار جلنــة إدارة الهيئــة رقــم‬\n‫(‪ /1800‬م) لعــام ‪1433‬ه ـ ‪ ،‬وذلــك لألدلــة والقرائــن التاليــة‪ 1 :‬ـ ـ مــا جاء‬\n‫بإقراراتهــم املدونــة بالصفحــة رقــم (‪ 2‬ـ ‪ )3‬لفــة رقــم (‪ 2.)1‬ـ ـ مــا جــاء‬\n‫بشــهادة مآميــر البحــث رقــم‪ ........‬ورقــم‪ ........‬ورقــم‪ ........‬املدونــة‬\n‫مبحضــر القبــض ‪ ،‬املرفــق ص (‪ )10 ، 6‬لفــة (‪ 3.)3‬ـ ـ مــا جــاء يف محضر‬\n‫تســليم املجنــي عليهمــا حملفظتهمــا املنشــولة لفــة (‪ )4‬و لفــة (‪ )2‬ص‪. 3‬‬\n\n\n                                                                                      ‫‪94‬‬\n\f     ‫وبالبحــث عــن ســوابقهم عثــر للمدعــى عليــه الثانــي علــى ثــاث ســوابق‬\n     ‫اثنتــن منهــا نشــل إحداهمــا مقترنــة بعــودة بعــد إبعــاد والثالثــة تكويــن‬\n     ‫عصابــة للنشــل مقترنــة بعــودة بعــد إبعــاد ‪ ،‬وعثــر للمدعــى عليــه الثالــث‬\n     ‫علــى أربــع ســوابق اثنتــن نشــل واثنتــن عــودة بعــد إبعــاد ‪ ،‬ولــم يعثــر‬\n     ‫للمدعــى عليــه األول علــى ســوابق مســجلة ‪ .‬وحيــث إن مــا قــام بــه املدعــى‬\n     ‫عليهــم وهــم بكامــل أهليتهــم املعتبــرة شــرع ًا مــن التعــرض لبعــض‬\n     ‫قاصــدي بيــت اهلل احلــرام بأخــذ مــا يف جيوبهــم مــن أمــوال دون مراعــاة‬\n     ‫حلرمــة املــكان فعــل محــرم ومعاقــب عليــه شــرع ًا ‪ ،‬وهــو ســرقة مــال‬\n     ‫محتــرم مــن حــرزه بعــد هتكــه يزيــد علــى النصــاب ال شــبهة لهــم فيــه‬\n     ‫لــذا اطلــب إثبــات مــا أســند إليهــم ‪ ،‬واحلكــم علــى املدعــى عليهمــا األول‬\n     ‫والثانــي بحــد الســرقة الــوارد يف اآليــة الكرميــة رقــم (‪ )38‬مــن ســورة‬\n     ‫املائــدة يف ضــوء قــرار مجلــس القضــاء األعلــى رقــم (‪ )46/421‬يف‬\n     ‫‪ 1418/11/17‬ه ـ ‪ ،‬وعلــى املدعــى عليــه الثالــث بعقوبــة تعزيريــة لقــاء‬\n     ‫مــا نســب إليهــم ‪ ،‬واحلكــم بإيــداع مــا مت ضبطــه بحوزتهــم (ثالثــة عشــر‬\n     ‫ألــف ريــال ســعودي ‪ ،‬جــوال مــن نــوع (‪ )....‬موديــل (‪ )....‬اســود اللــون ‪،‬‬\n     ‫وهاتــف نقــال مــن نــوع (‪ )....‬موديــل (‪ ) ....‬اســود وفضــي اللــون ‪ ،‬وهاتــف‬\n     ‫جيبــي نقــال مــن نــوع (‪ )....‬موديــل (‪ ).....‬بيــت مــال املســلمني اســتنادا‬\n     ‫للمــادة (‪ )92‬مــن نظــام اإلجــراءات اجلزائيــة ‪(.‬علمـ ًا بأنــه احلقــوق اخلاصــة‬\n     ‫مازالــت قائمــة وانتهــت بحــق املجنــي عليهمــا ‪ ........‬و ‪ )........‬هــذه دعــواي‬\n     ‫وبعــرض ذلــك علــى املدعــى عليهــم بواســطة مترجــم احملكمــة ‪........‬‬\n     ‫باكســتاني اجلنســية مبوجــب رخصــة االقامــة رقــم‪ ........‬أجــاب األول‬\n     ‫ا ‪ :‬مــا ذكــره املدعــي العــام مــن دعــواه‬    ‫بواســطة املترجــم نفســه قائ ـ ً‬\n     ‫ا والصحيــح أنــه خرجــت مــن احلــرم‬      ‫كلــه غيــر صحيــح جملــة وتفصي ـ ً‬\n\n\n‫‪95‬‬\n\f‫ووجــدت محفظــة ملقــاة علــى األرض ونزلــت ألخذها ثــم أخذتها وعرفت‬\n‫بهــا ملــن هــذه وكان املدعــى عليــه الثانــي بجــواري فقــال لــي ‪ :‬أرنــي‬\n‫أنظــر إليهــا فأخذهــا وليــس لــي عالقــة باملدعــى عليهمــا اآلخريــن قبــل‬\n‫ولــم أرهمــا مــن قبــل أو اتصــل بهمــا أو ســكنا ســوي ًا وأول مشــاهدة لهــم‬\n‫يف وقــت القبــض واملبلــغ املقبــوض معــي لــي هكــذا أجــاب كمــا اجــاب‬\n‫ا مــا ذكــره املدعــي العــام يف دعــواه كلــه غيــر‬   ‫املدعــى عليــه الثانــي قائـ ً‬\n‫ا والصحيــح أنــي رأيــت املدعــى عليــه األول أثنــاء‬     ‫صحيــح جملــة وتفصيـ ً‬\n‫خروجــي مــن احلــرم ينــادي علــى محفظــة فقلــت لــه ‪ :‬أرنــي أنظــر إليهــا‬\n‫وأثنــاء تفحصهــا وهــي يف يــدي قبــض عليــه ‪ ،‬وليــس عالقــة باملدعــى‬\n‫عليهمــا وال أعرفهمــا مــن قبــل وأمــا املبلــغ فليــس لــي منــه ســوى ‪400‬‬\n‫اربعمائــة دوالر و‪ 1460‬ألــف واربعمائــة وســتون ريــال ســعودي والباقــي‬\n‫ليــس معــي وال أعــرف كيــف وضــع لــي ‪ ،‬وأمــا الســوابق فهــي صحيحــة‬\n‫إال أنهــا كانــت تهمــة هكــذا أجــاب كمــا أجــاب املدعــى عليــه الثالــث‬\n‫بواســطة املترجــم نفســه ‪ :‬ماذكــره املدعــي العــام يف دعــواه كلــه غيــر‬\n‫ا وال أعــرف املدعــى عليهمــا وليــس لــي بهمــا أي‬      ‫صحيــح جملــة وتفصيـ ً‬\n‫عالقــة واملبلــغ املوجــود معــي ملكــي وقــد قبــض علــي لكونــي قريــب‬\n‫منهمــا ذاهــب لبيتــي وذلــك أثنــاء القبــض علــي وامــا الســوابق فهــي‬\n‫صحيحــة إال أنهــا كانــت تهمــة هكــذا أجــاب كمــا جــرى منــا الرجــوع‬\n‫ألوراق املعاملــة ووجــد مــن بينهــا إقــرارات املدعــى عليهــم املدونــة مبلــف‬\n‫التحقيــق املرفــق باملعاملــة لفــه رقــم (‪ )1‬وصحيفــة رقــم ( ‪) 4 ،3 ،2‬‬\n‫وجــدت أنهــا تتضمــن إقــرار اعتــراف بتاريــخ ‪1433/7/18‬ه ـ ونصــه‬\n‫((أقــر أنــا املوقــع اســمي أدنــاه املدعــو ‪ ......../‬بنقالــي اجلنســية ابلــغ مــن‬\n‫العمــر ‪32‬ســنه ال أحمــل هويــه واعطــي بطاقــة بديلــة برقــم‪ ........‬مــن قبــل‬\n\n\n                                                                                          ‫‪96‬‬\n\f     ‫مخفــر شــرطة احلــرم بأننــي وبكامــل قــواي العقليــة املعتبــره شــرعا بغيــر‬\n     ‫اكــراه منــي وال إجبــار بأننــي يف هــذا اليــوم قمــت بوضــع يــدي اليمنــى‬\n     ‫جتــاه اجليــب االميــن ألحــد املعتمريــن وقمــت بأخذهــا بيــدي اليســرى‬\n     ‫وإعطائهــا الــى املدعــو ‪ ........‬بنقالــي اجلنســية وقــام بوضعهــا يف جيــب‬\n     ‫بنطلونــه اخللفــي كمــا انــه كان يوجــد اتفــاق بيننــا بأننــا نقــوم بعمليــة‬\n     ‫النشــل هــذا اليــوم يف احلــرم وهــذا إقــرار منــي بذلــك وعليــه جــرى‬\n     ‫التوقيــع‪ )).‬كمــا جــرى اإلطــاع علــى إقــرار اإلعتــراف بتاريــخ‬\n     ‫‪1433/7/18‬ه ـ ونصــه (( أقــر أنــا املوقــع اســمي أدنــاه املدعــو ‪........‬‬\n     ‫بنقالــي اجلنســية ابلــغ مــن العمــر ‪48‬ســنة ال أحمــل هويــة وأعطــي بطاقــة‬\n     ‫بديلــة رقــم بأننــي وبكامــل قــواي العقليــة املعتبــرة شــرعا بغيــر إكــراه‬\n     ‫منــي وال إجبــار بأننــي قمــت مبســاعدة املدعــو‪ ........‬يف عمليــة النشــل‬\n     ‫حيــث كان هــو يقــوم بالنشــل وأنــا أقــوم بوضــع احملافــظ املنشــولة يف‬\n     ‫جيوبــي وقــد كان بيننــا اتفــاق مســبق بأننــا يف هــذا اليــوم نقــوم بالنشــل‬\n     ‫داخــل احلــرم وهــذا إقــرار منــي بذلــك وعليــه جــرى التوقيــع)) كمــا جــرى‬\n     ‫اإلطــاع علــى إقــرار اإلعتــراف بتاريــخ ‪1433/7/18‬ه ـ ونصــه (( أقــر أنا‬\n     ‫املوقــع إســمي أدنــاه املدعــو ‪ ........‬بنقالــي اجلنســية ال أحمــل هويــة وأعطــي‬\n     ‫بطاقــة بديلــة برقــم صــادرة مــن مخفــر شــرطة احلــرم بأننــي وبكامــل‬\n     ‫قــواي العقليــة املعتبــرة شــرعا بغيــر إكــراه منــي وال إجبــار بأننــي كنــت‬\n     ‫أقوم بالتســتر على كال من املدعو ‪ ........‬واملدعو ‪ ........‬بنقالي اجلنســية‬\n     ‫لكــي يتمكنــوا مــن النشــل وال أحــد يراهــم كمــا أنــه كان يوجــد‬\n     ‫بيننــا إتفــاق مســبق بــأن نقــوم بالنشــل لهــذا اليــوم داخــل احلــرم وهــذا‬\n     ‫إقــرار منــي بذلــك وعليــه جــرى التوقيــع ‪ )) .‬أ‪ .‬ه ـ وبعرض هــذه االقرارات‬\n     ‫علــى املدعــى عليهــم أجابــوا جميع ـ ًا بواســطة املترجــم ‪ :‬بــان مــا جــاء يف‬\n\n\n‫‪97‬‬\n\f‫هــذه االقــرارات غيــر صحيــح والصحيــح مــا ذكرناه يف إجابتنا الســابقة‬\n‫وقــد كان االقــرار حتــت اإلكــراه والضــرب هكــذا أجابــوا كمــا‬\n‫جــرى االطــاع علــى محضــر القبــض املــدون مبلــف احلقيــق املرفــق‬\n‫باملعاملــة لفــه ( ‪ )3‬وصحيفــة رقــم (‪ )6‬ونصــه (( أنــه يف الســاعة الثانيــة‬\n‫ظهــرا يــوم اجلمعــة املوافــق ‪1433/7/18‬ه ـ ويف الســاحات الغربيــة أمــام‬\n‫باب ‪ 86‬مت مشــاهدة املدعو ‪ ........‬بنقالي اجلنســية ‪32‬ســنة حســب أقواله‬\n‫مــن قبــل مأمــور بحــث رقــم وهــو يقــوم بوضــع يــده اليمنــى علــى اجليــب‬\n‫األيســر للمدعــو ‪ ........‬مصــري اجلنســية وقــام برفعهــا مــن جيبــه وعنــد‬\n‫خروجهــا قــام بأخذهــا بيــده اليســرى وإعطائهــا شــخص كان معــه‬\n‫واتضــح أنــه يدعــى‪48 ........‬ســنه حســب أقوالــه وقــام بوضعهــا يف جيــب‬\n‫بنطلونــه اخللفــي وكان يســتر عليهــم كذلــك شــخص كان معهــم‬\n‫وأتضــح أنــه يدعــى‪ 49 ........‬ســنه حســب أقوالــه ومت القبــض عليهــم‬\n‫مبســاندة الزمــاء مآميــر البحــث رقــم واحملفظــة بحــوزة املدعــو‪........‬‬\n‫وبتفتيــش احملفظــة املنشــولة وجــد بداخلهــا رخصــة إقامــة رقــم وبطاقــة‬\n‫تعريــف مصريــة وأوراق خاصــة فقــط )) أ‪ .‬ه ـ ‪ .‬وبعرض ذلك على املدعي‬\n‫العــام أجــاب بقولــه ‪ :‬الصحيــح مــا جــاء يف الدعــوى العامــة ولــدي البينــة‬\n‫علــى ذلــك وأحضــر ‪........‬ســعودي بالســجل املدنــي رقــم‪ ........‬ويعمــل‬\n‫ا‪:‬‬ ‫مأمــور بالبحــث والتحــري يف شــرطة احلــرم وباستشــهاد شــهد قائ ـ ً‬\n‫أنــه يف منتصــف شــهر رجــب الفائــت وبعــد صــاة اجلمعــة ويف ســاحات‬\n‫احلــرم يف مشــاية شــاهدت املدعــى عليــه هــذا احلاضــر ‪ -‬وأشــار إليــه وهــو‬\n‫يتلمــس جيــوب املصلــن ويطالــع فيهــا ثــم تفــرق أصحابــه االثنــن عنهــم ‪،‬‬\n‫واتصــل عليهــم بالهاتــف وحضــروا إليــه ثــم خرجــوا واجتهــوا ناحيــة بــاب‬\n‫امللــك الفهــد وامــام مشــربيات ســلم بــاب شــاهدت املدعــى عليــه وهــو‬\n\n\n                                                                                    ‫‪98‬‬\n\f     ‫يرفــع محفظــة مــن جيــب أحــد املــارة وشــاهدت احملفظــة يف يــده بعــد‬\n     ‫إخراجهــا وســلمها لصاحبــه املدعــى عليــه الثانــي ‪ ....‬ووضعهــا يف جيبــه‬\n     ‫اخللفــي مباشــرة ‪ ،‬وكان املدعــى عليــه الثالــث يراقــب الوضــع ويتســتر‬\n     ‫عليهــم أثنــاء حصــول النشــل ‪ ،‬ثــم انتظــرت حضــور بقية أعضــاء الفرقة‪،‬‬\n     ‫فلمــا حضــروا قبضنــا عليهــم وبتفتيــش املدعــى عليــه الثانــي وجــد معــه‬\n     ‫احملفظــة املنشــولة وبداخلهــا رخصــة إقامــة وبطاقــة تعريــف مصريــة‬\n     ‫وأوراق خاصــة فقــط وليــس فيهــا مبلــغ مالــي كمــا وجــد معــه محافــظ‬\n     ‫أخــرى ومبالــغ ماليــه هــذا مــا لــدي مــن شــهادة كمــا حضــر ســعودي‬\n     ‫بالهويــة الوطنيــة رقــم ويعمــل مأمــور بالبحــث والتحــري بشــرطة احلــرم‬\n     ‫ا ‪(( :‬إنــي قــد تلقيــت اتصــا ًال مــن الشــاهد زميلنــا‬\n                                                              ‫وباستشــهاده شــهد قائـ ً‬\n     ‫يف الفرقــة وعلــى إثــره حضــرت إلــى الســاحات الغربيــة للحــرم وقبضــت‬\n     ‫علــى املدعــى عليهــم وبتفتيــش املدعــى عليــه الثانــي وأشــار إليــه وجــدت‬\n     ‫معــه عــدة محافــظ منهــا محفظــة لشــخص أفغانــي فيهــا أربــع إقامــات‬\n     ‫كمــا وجدنــا معــه علــى مبالــغ ماليــه ال أعلــم مقدارهــا علــى وجــه‬\n     ‫التحديــد هــذا مــا لــدي مــن شــهادة )) وبعرضــه علــى املدعــى عليهــم‬\n     ‫أجابــوا بواســطة املترجــم نفســه ‪ :‬ال صحــة ملــا ذكــره الشــاهد جملــة‬\n     ‫ا والصحيــح مــا ذكرتــه وبســؤال املدعــي العــام هــل لديــه زيــادة‬   ‫وتفصيـ ً‬\n     ‫بينــة قــال ‪ :‬ليــس لــدي ســوى مــا أحضــرت وقــد جــرى ســؤال املدعــى‬\n     ‫عليهــم عــن عالقتهــم ببعــض قبــل وقــت القبــض فأفــادوا جميع ـ ًا بعــدم‬\n     ‫معرفتهــم ببعــض قبــل وقــت احلــادث هكــذا أفــادوا عنــد ذلــك ســألت‬\n     ‫املدعــي العــام هــل لديــه مــا يبــن عالقتهــم ببعــض مــن بيــان باالتصــاالت‬\n     ‫بينهــم ؟ فأجــاب ‪ :‬ليــس يف املعاملــة مايفيــد ذلــك وأطلــب مهلــة للكتابــة‬\n     ‫جلهــات االختصــاص لالفــادة عــن ذلــك وســأزودكم بصــورة مــن خطابــي‬\n\n\n‫‪99‬‬\n\f‫طلــب االفــادة ‪ ،‬ثــم يف يــوم اليــوم االثنــن املوافــق ‪1434/04/08‬ه ـ‬\n‫افتتحــت اجللســة يف متــام الســاعة التاســعة صباحـ ًا ومبشــاركة القاضــي‬\n‫بهــذه احملكمــة ‪ ،‬وفيهــا حضــر املدعــي العــام واملدعــى عليهــم واملترجــم‬\n‫املنــوه عنهــم بعاليــه وباإلطــاع علــى خطــاب املشــرف علــى مكتــب‬\n‫اإلدعــاء العــام باحملكمــة العامــة مبكــة املكرمــة برقــم ه ـ م ‪ /2 /‬ب ‪/‬‬\n‫‪ 296‬يف ‪1434 / 3 / 1‬ه ـ املبنــي علــى خطــاب مديــر مخفــر شــرطة احلــرم‬\n‫برقــم ‪ 180828‬يف ‪1434/3/1‬ه ـ املبنــي علــى خطــاب مديــر شــعبة‬\n‫التحريــات والبحــث اجلنائــي برقــم ‪ 501652‬يف ‪1434/1/26‬ه املتضمــن‬\n‫بأنــه مت مخاطبــة شــركات االتصــاالت ومت اإلفــادة كمــا هــو موضــح‬\n‫يف النشــرة املرفقــة وباالطــاع علــى النشــرة املرفقــة مــن شــركة موبايلي‬\n‫وجدنــا اإلفــادة بــ( ال يوجــد ) ‪ .‬وبعــد دراســة القضيــة وتأملهــا ومــا تقــدم‬\n‫مــن الدعــوى واإلجابــة ومبــا أن املدعــى عليهــم أنكــروا مــا نســبه لهــم‬\n‫املدعــي العــام مــن تكويــن عصابــة لنشــل زوار بيــت اهلل احلــرام وقيــام‬\n‫املدعــى عليــه األول بالنشــل داخــل املســجد احلــرام وقيــام املدعــى عليــه‬\n‫الثانــي باســتالم مــا يتــم نشــله وإخفــاؤه مبالبســه ‪ ،‬وقيــام املدعــى عليــه‬\n‫الثالــث بــدور املراقبــة والتغطيــة عليهمــا أثنــاء النشــل ‪ ،‬وحيــث أن مــا‬\n‫قدمــه املدعــي العــام مــن بينــات وقرائــن الســيما مــا جــاء يف شــهادة‬\n‫الشــاهد املدونــة شــهادته ‪ ،‬والــذي ظهــر يف عــدة قضايــا عدالتــه وضبطه‬\n‫للشــهادة ‪ ،‬ومــا جــاء يف إقــرار املدعــى عليهــم حتقيقــا مــن قيامهــم‬\n‫بالنشــل داخــل املســجد احلــرام ومــا قبــض بحوزتهــم مــن عمــات متفرقــة‬\n‫وأوراق ثبوتيــة ليســت بعائــدة لهــم ‪ ،‬مــع أن للمدعــى عليــه الثانــي ثــاث‬\n‫ســوابق منهــا ســابقتني نشــل وســابقة تكويــن عصابــة وللمدعــى عليــه‬\n‫الثالــث أربــع ســوابق منهــا ســابقتني نشــل وســابقتني عــودة بعــد إبعــاد‬\n\n\n                                                                                      ‫‪100‬‬\n\f      ‫وهــذا يــدل علــى امتهانهمــا لذلــك وعــدم توبتهمــا منهــا ولســوابق املدعــى‬\n      ‫عليهمــا و والتــي أقــرا بصحتهــا كلــه يســتوجب معهــا تعزيرهــم ‪ ،‬وبنــاء‬\n      ‫علــى املــادة (‪ )159‬مــن نظــام اإلجــراءات اجلزائية املجيــزة ملقام احملكمة‬\n      ‫تعديــل الوصــف اجلرمــي مبــا يتفــق والفعــل الثابــت بحــق املدعــى عليــه ‪،‬‬\n      ‫لذلــك كلــه فقــد قررنــا مــا يلــي ‪ :‬أو ًال ‪ :‬لــم يثبــت لدينــا مــا يوجــب إقامــة‬\n      ‫حــد الســرقة علــى املدعــى عليهمــا األول والثانــي ورددنــا دعــوى املدعــي‬\n      ‫العــام طلبــه ذلــك ‪ .‬ثاني ـ ًا ‪ :‬ثبــت لدينــا إدانــة املدعــى عليهــم بتكويــن‬\n      ‫عصابــة للنشــل يف املســجد احلــرام وقررنــا تعزيرهــم مبــا يلــي ‪:‬ـ بســجن‬\n      ‫ـداء مــن تاريــخ إيقافــه علــى ذمــة القضيــة‬ ‫املدعــى عليــه ســت ســنوات ابتـ ً‬\n      ‫وجلــده ألــف وخمســمائة جلــدة مفرقــة علــى دفعــات متســاوية يف كل‬\n      ‫دفعــة خمســون جلــدة بــن كل دفعــة والتــي تليهــا مــدة ال تقــل عــن خمســة‬\n      ‫ـداء‬\n      ‫عشــر يومـ ًا وســجن املدعــى عليهمــا ‪ .......‬و‪ ..........‬ثــاث ســنوات ابتـ ً‬\n      ‫مــن تاريــخ إيقافهمــا علــى ذمــة القضيــة وجلــد كل منهمــا ألــف جلــدة‬\n      ‫مفرقــة علــى دفعــات متســاوية يف كل دفعــة خمســون جلــدة بــن كل‬\n      ‫دفعــة والتــي تليهــا مــدة ال تقــل عــن خمســة عشــر يومــا وحكمنــا‬\n      ‫مبصــادرة املبالــغ املوجــودة بحــوزة املدعــى عليهــم وإيداعهــا يف اخلزانــة‬\n      ‫العامــة يف الدولــة كمــا حكمنــا بــأن يشــهر باملدعــى عليهــم بذكــر مــا‬\n      ‫ثبــت إدانتهــم بــه وصورهــم يف جريدتــن مــن اجلرائــد الصــادرة يف‬\n      ‫ـزاء لهــم‬\n              ‫اململكــة العربيــة الســعودية بغيــر اللغــة العربيــة ‪ ،‬وذلــك جـ ً‬\n      ‫وردع ـ ًا ألمثالهــم ‪ ،‬ومبــا تقــدم حكمنــا ونوصــي بإبعادهــم عــن البــاد‬\n      ‫بعــد انتهــاء فتــرة محكوميتهــم اتقــاء لشــرهم و بإعــان احلكــم علــى‬\n      ‫الطرفــن قــرر املدعــى عليهــم القناعــة بــه واملدعــي العــام اإلعتــراض‬\n      ‫وطلــب االســتئناف بالئحــة اعتراضيــة وجــرى تســليمه نســخه مــن القرار‬\n\n\n‫‪101‬‬\n\f‫املنظــوم بهــذه القضيــة وإفهامــه بــأن عليــه تقــدمي الئحتــه االعتراضيــة‬\n‫خــال ثالثــن يوم ـ ًا مــن تاريــخ تســليمه وإنــه إذا مضــت املــدة فســيرفع‬\n‫احلكــم بــدون الئحــة اعتراضيــة وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n                ‫محمد وعلى اله وصحبه وسلم حرر يف ‪1434/04/08‬هـ ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪:‬‬\n‫ففــي هــذا اليــوم األربعــاء املوافــق ‪1434/07/05‬ه ـ افتتحــت اجللســة‬\n‫وكان قــد وردتنــا املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة‬\n‫برقــم يف ‪1434/06/24‬ه ـ واملالحــظ عليهــا بقــرار الدائــرة اجلزائيــة‬\n‫اخلماســية الثانيــة مبحكمــة االســتئناف مبكــة املكرمــة رقــم يف‬\n‫‪1434/06/17‬ه ـ ونــص احلاجــة منــه ‪ (( :‬وبدراســة احلكــم وصــورة‬\n‫ضبطــه تقــرر باألكثريــة إعادتهــا ألصحــاب الفضيلــة حــكام القضيــة‬\n‫ملالحظــة مــا يلــي ‪ :‬احلكــم بــأن يشــهر املدعــى عليهــم وصورهــم يف‬\n‫جريدتــن بغيــر اللغــة العربيــة يف غيــر محلــه ؛ ألن فيــه تكلــف ‪ ،‬وحكم‬\n‫متعــد ‪ ،‬وغيــر واضــح ‪ ،‬فمــا هــي اجلريدتــان ‪ ،‬ومــا حجــم اإلعــان ‪ ،‬ومــن‬\n‫يدفــع الثمــن‪ ،‬وهــذا احلكــم فيــه جهالــة ومــن األولــى تركــه ‪ ،‬وبــاهلل‬\n‫التوفيــق )) ‪ ،‬وعليــه جنيــب أصحــاب الفضيلــة ‪ ،‬وفقهــم اهلل وســددهم‪:‬‬\n‫بــأن احلكــم بالتشــهير يف محلــه‪ ،‬وموافــق للقواعــد الشــرعية‪ ،‬والعــادة‬\n‫النظاميــة الــواردة يف عــدد مــن األنظمــة املرعيــة‪ ،‬واملبــادئ القضائيــة‬\n‫وليــس فيــه تعــدٍ أو غمــوض و بيــان ذلــك وتفصيلــه يف األوجــه التاليــة ‪:‬‬\n‫األول ‪ -:‬أن احلكــم بتشــهير املدعــى عليهــم علــى الوجــه املســطور يف‬\n‫منطــوق احلكــم هــو مــن بــاب التعزيــر ‪ ،‬ومــن املتقــرر أن التعزيــر عقوبــة‬\n‫مفوضــة للقضــاة واحلــكام قــدر ًا وحتديــداً‪ ،‬ومــادام أنهــا خاضعــة‬\n‫لنظرهــم‪ ،‬فهــم املنــوط بهــم مالحظــة املناســب وتقديــره واعتمــاده ‪،‬‬\n\n\n                                                                                   ‫‪102‬‬\n\f      ‫وإليهــم يرجــع وضــع العقوبــة املالئمــة للظــروف ‪ ،‬واحملققــة للمقاصــد‬\n      ‫حســب األحــوال املختلفــة‪ .‬فقــد يكــون التعزيــر بالضــرب أو احلبــس‬\n      ‫أو التوبيــخ أو التشــهير أو ببعضهــا أوبهــا جميع ـ ًا وغيــر ذلــك‪ ،‬حســب‬\n      ‫اختــاف مراتــب النــاس ‪ ،‬واختــاف املعاصــي ‪ ،‬واختــاف األعصــار‬\n      ‫واألمصــار ‪ .‬وعلــى ذلــك فالتعزيــر بالتشــهير جائــز إذا علــم احلاكــم أن‬\n      ‫املصلحــة فيــه ‪ ،‬وهــذا احلكــم هــو بالنســبة لــكل معصيــة ال حــد فيهــا‬\n                                                              ‫وال كفــارة يف اجلملــة ‪.‬‬\n      ‫ينظــر يف تقريــر هــذا املعنــى ‪ ،‬أي تفويــض العقوبــة التعزيريــة للقضــاة‬\n      ‫قــدر ًا وحتديــداً‪ (( :‬السياســة الشــرعية‪ ،‬البــن تيميــة ص‪ ،91‬حاشــية ابن‬\n      ‫عابديــن ‪ ، 183/3‬ونهايــة احملتــاج للرملــي ‪ 174 / 7‬ـ ‪ ،175‬واألحــكام‬\n              ‫الســلطانية للمــاوردي ص ‪ ، 224‬واحلســبة البــن تيميــة ص ‪. ))38‬‬\n      ‫وقــد ذكــر الفقهــاء التشــهير مــن احلاكــم كعقوبــة يلجــأ إليهــا يف‬\n      ‫التعازيــر‪ ،‬قــال املــاوردي ‪-‬رحمــه اهلل‪ ( :-‬لألميــر إذا رأى مــن الصــاح‬\n      ‫يف ردع الســفلة ‪ :‬أن يشــهرهم وينــادي عليهــم بجرائمهــم‪ ،‬ســاغ لــه ذلــك)‬\n      ‫[األحــكام الســلطانية للمــاوردي ص ‪ .]221‬وقــال أيض ـاً‪( :‬يجــوز يف‬\n      ‫نــكال التعزيــر أن يجــرد مــن ثيابــه ‪ ،‬إال قــدر مــا يســتر عورتــه ‪ ،‬ويشــهر‬\n      ‫يف النــاس ‪ ،‬وينــادى عليــه بذنبــه إذا تكــرر منــه ولــم يتــب) [املرجــع‬\n      ‫الســابق ص ‪ ،]239‬وقــال ابــن فرحــون ‪،‬رحمــه اهلل‪ ( :-‬إن رأى القاضــي‬\n      ‫املصلحــة يف قمــع الســفلة بإشــهارهم بجرائمهــم فعــل) [تبصــرة احلــكام‬\n      ‫البــن فرحــون‪ .] 126/2 ،‬وقــال البهوتــي ‪،‬رحمــه اهلل‪( :‬القــوادة ‪ -‬التــي‬\n      ‫تفســد النســاء والرجــال ‪ -‬أقــل مــا يجــب فيهــا الضــرب البليــغ ‪ ،‬وينبغــي‬\n      ‫شــهرة ذلــك بحيــث يســتفيض يف الرجــال والنســاء لتجتنــب) [كشــاف‬\n      ‫القنــاع ‪ . ] 127/6‬ويقــول املوفــق ابــن قدامــة ‪،‬رحمــه اهلل‪( :-‬فمتــى ثبــت‬\n\n\n‫‪103‬‬\n\f‫عنــد احلاكــم عــن رجــل أنــه شــهد بــزور عمــدا عــزره وشــهره يف قــول‬\n‫أكثــر أهــل العلــم ‪ .‬روي ذلــك عــن عمــر رضــي اهلل عنــه ‪ ،‬وبــه يقــول‬\n‫شــريح والقاســم بــن محمــد وســالم بــن عبــد اهلل واألوزاعــي وابــن أبــي‬\n‫ليلــى ومالــك والشــافعي وعبــد امللــك بــن يعلــى قاضــي البصــرة) [املغنــي‬\n‫يف شــرح مختصــر اخلرقــي ‪ ] 261 / 9‬وقــال البهوتــي ‪-‬رحمــه اهلل‪( :-‬إذا‬\n‫عــزر مــن وجــب عليــه التعزيــر وجــب علــى احلاكــم أن يشــهره ملصلحــة‬\n‫كشــاهد زور ليجتنب)‪[ .‬كشــاف القناع ‪ 125 / 6‬ـ ‪ .]127‬قال القرايف‬\n‫‪-‬رحمــه اهلل‪( : -‬إن التعزيــر يختلــف باختــاف األعصــار واألمصــار ‪،‬‬\n‫فــرب تعزيــر يف بلــد يكــون إكرامــا يف بلــد آخــر ‪ ،‬كقطــع الطيلســان‬\n‫ليــس تعزيــرا يف الشــام فإنــه إكــرام ‪ ،‬وكشــف الــرأس باألندلــس ليــس‬\n‫هوانــا ومبصــر والعــراق هــوان) نقلــه ابــن فرحــون ثــم عقــب عليــه بقولــه‪:‬‬\n‫(والتعزيــر ال يختــص بفعــل معــن وال قــول معــن ‪ ،‬فقــد « عــزر رســول‬\n‫اهلل صلــى اهلل عليــه وســلم بالهجــر» ‪ ،‬وذلــك يف حــق الثالثــة الذيــن‬\n‫ذكرهــم اهلل تعالــى يف القــرآن الكــرمي ‪ ،‬فهجــروا خمســن يومــا ال‬\n‫يكلمهــم أحــد) [تبصــرة احلــكام؛ البــن فرحــون ‪ .]295،296/2‬وقــال‬\n‫الشــربيني ‪،‬رحمــه اهلل‪( :-‬يجتهــد اإلمــام يف جنــس التعزيــر وقــدره ؛‬\n‫ألنــه غيــر مقــدر شــرعا ‪ ،‬فيجتهــد يف ســلوك األصــح ‪ ،‬فلــه أن يشــهر يف‬\n‫النــاس مــن أدى اجتهــاده إليــه) [مغنــي احملتــاج شــرح املنهــاج للشــربيني‬\n                                                                      ‫‪. ]192/4‬‬\n‫كل هــذه النصــوص الفقهيــة تــدل علــى أن التشــهير مــن العقوبــات‬\n‫الشــرعية يف التعازيــر‪ ،‬وأنهــا ليســت متكلفــة‪ ،‬وهي مــن جنس ماجاءت‬\n‫به الشــريعة املطهـ ـ ــرة‪ ،‬وليس يف كتاب اهلل أو ســنة رســوله‪،‬صلى اهلل‬\n‫عليــه وســلم‪ -‬أو يف كالم فقهــاء الشــريعة املعتبريــن مايــدل علــى فســاد‬\n\n\n                                                                                    ‫‪104‬‬\n\f      ‫العقوبــة بالتشــهير بــل إنهــا يف كثيــر مــن األحيــان أكثــر نكايــة وأبلــغ‬\n      ‫مــن العقوبــات املعتــادة‪ .‬والشــك أن القاضــي يجــب أن يكــون علــى فهــم‬\n      ‫بالواقــع حتــى يوقــع العقوبــة علــى الوجــه الشــرعي‪ ،‬فليــس مــن املناســب‬\n      ‫مــع تقــدم الزمــان أن يكــون بتجريــد الثيــاب أو قطــع الطيلســان أو‬\n      ‫تســويد الوجــه والطــواف بــه يف البلــدان‪ ،‬بــل إن الوســائل اإلعالميــة‬\n      ‫كالصحــف والتلفــاز حتقــق املقصــد مــن هــذه العقوبــة الشــرعية‪،‬‬\n           ‫ويرتــدع بهــا مــن تســول لــه نفســه القيــام مبثــل هــذا العمــل املشــن ‪.‬‬\n      ‫الثانــي‪ :‬أن عقوبــة التشــهير ليســت بدع ـ ًا يف األنظمــة الســعودية‪ ،‬فقــد‬\n      ‫وردت يف عــدد مــن األنظمــة املرعيــة ممايــدل علــى أن الدوائــر التنظيميــة‬\n      ‫يف اململكــة العربيــة الســعودية‪ ،‬رأت جــدوى ذلــك يف بعــض ماســنته‬\n      ‫مــن أنظمــة‪ ،‬وأثــره يف ضبــط األفعــال املخلــة مبصلحــة اجلماعــة‪ ،‬ومــن‬\n      ‫ذل ــك علــى ســبيل املثــال ‪ :‬أ‪ -‬مــا نصــت عليــه املــادة العشــرين مــن نظــام‬\n      ‫مكافحــة الغــش التجــاري الصــادر باملرســوم امللكــي رقــم‪ :‬م‪ 11/‬يف‬\n      ‫‪1404/5/29‬هــ‪ُ ( :‬تش ـ ِّهر وزارة ال ِتجــارة باملُخا ِلــف الصــادِر ضــده قــرار‬\n      ‫نهائــي باإلدانــة ِطبقـ ًا ألحــكام هــذا ال ِنظــام والئحتــه بوســيلة علــى األقــل‬\n            ‫مــن وســائل اإلعــام‪ .‬ويكــون النشــر علــى نفقــة احملكــوم عليــه)‪.‬‬\n      ‫ب‪ -‬مــا نصــت عليــه املــادة الرابعــة مــن نظــام مكافحــة التســتر الصــادر‬\n      ‫باملرســوم امللكــي رقــم‪ :‬م‪ 22/‬يف‪1425/5/4‬ه ـ ‪ ...( :‬ت‪ -‬ينشــر منطــوق‬\n      ‫قــرار العقوبــة يف واحــدة أو أكثــر الصحــف احمللية علــى نفقة املخالف)‪.‬‬\n      ‫ت‪ ،‬مــا جــاء يف املــادة احلاديــة والعشــرون بعــد املائــة مــن نظــام األوراق‬\n      ‫التجاريــة املضافــة باملرســوم امللكــي رقــم م ‪ 45 /‬يف ‪1409/9/12‬ه ـ ‪:‬‬\n      ‫(يجــوز ا ُحلكــم بنشــر أســماء األشــخاص الذيــن يصـ ُـدر بحقِ هــم ُحكــم‬\n      ‫ويحــدِ د ا ُحلكــم كيفيــة ذلــك) ‪ .‬ومــن‬   ‫باإلدانــة مبوجــب هــذا ال ِنظــام ‪ُ ،‬‬\n\n‫‪105‬‬\n\f‫مجمــوع هــذه النصــوص النظاميــة‪ ،‬وغيرهــا يتبــن أن ثمت عــادة نظامية‬\n‫مســتقرة يف تضمــن بعــض النصــوص العقابيــة‪ ،‬احلكــم بالتشــهير‪،‬‬\n                                    ‫فمــن أيــن أتــى التعــدي أو الغمــوض إذاً!!‪.‬‬\n‫ـتند أيض ـ ًا علــى قــرار مجلــس‬\n                                ‫الثالــث‪ :‬أن احلكــم بعقوبــة التشــهير مسـ ٌ‬\n‫القضــاء األعلــى بهيئتــه العامــة رقــم ‪ 40/187‬يف ‪1414/3/2‬هــ‪ ،‬املبلــغ‬\n‫للمحاكــم بتعميــم وزارة العــدل رقــم ‪8‬ـ‪/‬ت‪ 158/‬يف ‪1414/5/8‬هــ‪،‬‬\n‫ونصــه‪ (( :‬تلقينــا خطــاب ســماحة رئيــس مجلــس القضــاء األعلــى رقــم‬\n‫‪ 387/1‬يف ‪1414/3/28‬ه ـ ومشــفوعه قــرار املجلــس بهيئتــه العامــة رقــم‬\n‫‪ 40/187‬يف ‪1414/3/2‬ه ـ املتضمــن ‪ -1...‬أن القضــاة إذا نصــوا يف‬\n‫األحــكام الصــادرة منهــم علــى تعيــن مــكان اجللــد فينبغــي األخــذ بــه‪.‬‬\n‫‪ -2‬ينبغــي عنــد إصــدار مثــل هــذه األحكام مراعــاة كالم أهل العلم يف‬\n‫ذلــك ومراعــاة مــا يناســب اجلرميــة مــن التشــهير إذ كان املقــام يســتدعي‬\n‫ذلــك حســب شــناعة اجلرميــة أو ســوابق املجــرم ودرجــة انتشــار اجلرميــة مــع‬\n‫مراعــاة تــرك تعيــن املــكان إذا كانــت العقوبــة خفيفــة أو كانــت حــال‬\n‫إيقاعهــا تقتضــي غيــر التعيــن وذلــك مــرده لنظــر القاضــي واجتهــاده)‪.‬‬\n           ‫املوضوعِ ــي لتعاميــم وزارة العــدل‪] 785/1 :‬‬‫ُ‬     ‫يراجــع [ التصنيــف‬\n‫فتبــن إذاً؛ مــن الوجــوه الثالثــة املشــار إليهــا أن العقوبــة بالتشــهير هــي‬\n‫ـدي مــن الشــريعة‬  ‫عقوبــة ليــس فيهــا تعــدٍ أو متكلفــة ‪ ،‬وأنهــا علــى هـ ٍ‬\n‫ـاس مــن املبــادئ القضائيــة‬ ‫املطهــرة‪ ،‬وســن مــن األنظمــة املرعيــة‪ ،‬وأسـ ٍ‬\n‫الرابع‪ :‬أن وجه احلكم بعقوبة التشــهير على املدعى عليهم‪ ،‬والتشــديد‬\n‫عليهــم بهــا‪ ،‬مــع ماتقــرر بحقهــم مــن عقوبــات تعزيريــة أخــرى‪ ،‬ه ــو‬\n               ‫الظــروف املشــددة التــي حلقــت بجنايتهــم وبيانهــا كمايلــي‪:‬‬\n‫‪ -1‬أن املدعــى عليهــم لــم يراعــو حرمــة املــكان فقــد قامــوا باجلرميــة يف‬\n\n\n                                                                                     ‫‪106‬‬\n\f        ‫ون َعــنْ‬\n                ‫ك َفـ ُـروا َو َي ُصـ ُّـد َ‬  ‫البيــت احلــرام‪ ،‬وقــد قــال اهلل تعالــى‪ِ (( :‬إ َّن الَّذِ يـ َـن َ‬\n      ‫ـف فِ ي ـ ِه‬\n                 ‫اكـ ُ‬  ‫ـاس َسـ َـو ًاء ا ْل َع ِ‬            ‫الـ َـر ِام ا َّلــذِ ي َج َع ْل َنـ ُ‬\n                                                  ‫ـاه لِل َّنـ ِ‬                                     ‫َســجدِ ْ َ‬                ‫يل َّ ِ‬\n                                                                                                                     ‫الل َو ْال ْ ِ‬       ‫َس ـ ِب ِ‬\n      ‫اب َأ ِليـ ٍـم )) [احلــج آيــة‬       ‫َوا ْل َبــا ِد َو َمــنْ ُيـ ِـردْ فِ ي ـ ِه ِب ِإ ْ َلــا ٍد ِب ُظ ْلـ ٍـم ُنذِ ْق ـ ُه مِ ــنْ َعـ َـذ ٍ‬\n      ‫‪ ]25‬قــال القرطبــي ‪-‬رحمــه اهلل‪(( :-‬وهــذا اإلحلــاد والظلــم يجمــع جميــع‬\n      ‫املعاصــي مــن الكفــر إلــى الصغائــر‪ ،‬فلعظــم حرمــة املــكان توعــد اهلل‬\n      ‫تعالــى علــى نيــة الســيئة فيــه)) [اجلامــع ألحــكام القــرآن ‪ ،]36/12‬ونقــل‬\n      ‫عــن ابــن عبــاس ‪،‬رضــي اهلل عنهمــا‪ -‬يف تفســير هــذه اآليــة‪ (( :‬هــو أن‬\n      ‫تســتحل مــن احلــرم مــا حــرم اهلل عليــك مــن لســان أو قتــل‪ ،‬فتظلــم مــن ال‬\n      ‫يظلمــك‪ ،‬وتقتــل مــن ال يقتلــك‪ ،‬فــإذا فعــل ذلــك فقــد وجــب لــه العــذاب‬\n                                                                     ‫األليــم)) [تفســير ابــن كثيــر ‪.]411/5‬‬\n      ‫‪ -2‬ارتــكاب اجلنــاة اجلرميــة املعاقــب عليهــا مــن خــال عصابــة منظمــة‬\n                                                                                                                          ‫لهــذا الغــرض‪.‬‬\n      ‫‪ -3‬ســبق صــدور أحــكام قضائيــة باإلدانــة بحــق اثنــن مــن اجلنــاة يف‬\n                                                                                                                        ‫جرائــم مماثلــة‪.‬‬\n      ‫‪ -4‬انتشــار هــذه اجلرميــة يف بنــي جنســهم‪ ،‬والتشــهير بهــم يف وســائل‬\n      ‫اإلعــام الصــادرة بلغــة مقــرؤة لهــم‪ ،‬تــردع مــن تســول لــه نفســه منهــم‬\n                                                                                             ‫القيــام مبثــل هــذه اجلنايــة‪.‬‬\n      ‫الرابع‪ :‬أن وجه احلكم بعقوبة التشــهير على املدعى عليهم‪ ،‬والتشــديد‬\n      ‫عليهــم بهــا‪ ،‬مــع ماتقــرر بحقهــم مــن عقوبــات تعزيريــة أخــرى‪ ،‬ه ــو‬\n                           ‫الظــروف املشــددة التــي حلقــت بجنايتهــم وبيانهــا كمايلــي‪:‬‬\n      ‫اخلامــس‪ :‬أن احلكــم بالتشــهير وفــق املنطــوق أعــاه منضبــط وميكــن‬\n      ‫تنفيــذه ‪ ،‬وإختيــار اجلريدتــان وحجــم االعــان هــو مــن إجــراءات تنفيــذ‬\n      ‫األحــكام اجلزئيــة ‪ ،‬ومردهــا للحاكــم اإلداري ال احملكمــة‪ ،‬وكــون‬\n\n\n‫‪107‬‬\n\f‫العقوبة املقرة ليســت على وجه العقوبات املعروفة ‪-‬الســجن أو اجللد‪ -‬ال‬\n‫يعنــي أن هــذا ال ميكــن تنفيــذه ‪ ،‬بــل لــدى احلاكــم اإلداري طــرق لتنفيــذ‬\n‫التشــهير واســتيفاء ثمنــه مــن اجلنــاة ‪ ،‬وممــا يــدل علــى ذلــك إعالنــات‬\n‫التشــهير املتكــررة يف الصحــف ‪ ،‬والواجــب علــى احلاكــم اإلداري أن‬\n‫يتخــذ اإلجــراءات الالزمــة لتنفيــذ احلكــم اجلزائــي‪ ،‬وقــد نصــت املــادة‬\n‫(يرســل رئيــس احملكمــة‬ ‫(‪ )219‬مــن نظــام اإلجــراءات اجلزائيــة علــى أن‪ِ :‬‬\n     ‫ِ‬\n‫احلاكــم‬     ‫الواجــب التنفيــذ الصــادِر مــن احملكمــة إلــى‬\n                                                             ‫ِ‬        ‫ا ُحلكــم اجلزائــي‬\n‫احلاكــم اإلداري ا ِتخــاذ‬‫ِ‬       ‫اإلداري ال ِتخــاذ إجــراءات تنفيــذِ ه‪ .‬وعلــى‬\n                                   ‫اإلجــراءات الال ِزمــة لتنفيــذ ا ُحلكــم فــوراً)‪.‬‬\n‫وعليــه وملــا تقــدم فإنــا النــزال علــى ماحكمنــا بــه ســابقا‪ ،‬وقررنــا إحلــاق‬\n‫ذلــك وبعثهــا حملكمــة االســتئناف الكمــال الزمهــا وفــق املــادة (‪)205‬‬\n‫مــن نظ ــام اإلجــراءات اجلزائيــة‪ ،‬أمــا فضيلــة الشــيخ فهــو منتــدب ملــدة‬\n‫شــهرين يف دورة القضــاء املتخصــص‪ ،‬وبــاهلل التوفيــق وصلــى اهلل وســلم‬\n‫علــى نبينــا محمــد وعلــى آله وصحبه أجمعني حــرر يف ‪1434/07/05‬هـ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن النبــي بعــده وبعــد ‪:‬‬\n‫ففــي هــذا اليــوم اخلميــس املوافــق ‪1434/09/17‬ه ـ افتتحــت اجللســة‬\n‫يف متــام الســاعة الثانيــة ظهــر ًا لدينــا نحــن كل مــن وكان قــد وردتنــا‬\n‫املعاملــة مــن محكمــة االســتئناف برقــم يف ‪1434/07/26‬ه ـ واملقيــدة‬\n‫باحملكمــة برقــم يف ‪1434/08/02‬ه ـ واملالحــظ عليهــا بقــرار الدائــرة‬\n‫اجلزائيــة اخلماســية الثانيــة رقــم يف ‪1434/07/22‬ه ـ ونــص احلاجــة‬\n‫منــه‪ (( :‬وبدراســة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر‬\n‫باألكثريــة إعادتهــا ألصحــاب الفضيلــة حــكام القضيــة ملالحظــة أن‬\n‫جــواب صاحبــي الفضيلــة غيــر مقنــع ‪ ،‬وعليهــم النظــر والتأمــل واإلجابــة‬\n\n\n                                                                                            ‫‪108‬‬\n\f      ‫مــن كامــل األعضــاء ‪ ،‬وألن التشــهير مــن اختصــاص جهــات التنفيــذ‪،‬‬\n      ‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n      ‫وســلم)) عليــه جنيــب أصحــاب الفضيلــة ـ ـ ـ حفظهــم اهلل ـ ـ بــأن ماجــاء‬\n      ‫يف قــرار أصحــاب الفضيلــة بــأن اجلــواب غيــر مقنــع هــو كالم مرســل إذ‬\n      ‫لــم يبينــوا وجــه عــدم اإلقنــاع فيــه ســيما وأ ّنــا قــد ســقنا إليهــم حشــد ًا مــن‬\n      ‫األقــوال الفقهيــة واملبــادئ القضائيــة والنصــوص النظاميــة وأوضحنــا‬\n      ‫مســتند حكمنــا بأوضــح عبــارة وأبينهــا ‪ ،‬واملــادة اخلامســة بعــد املائتــن‬\n      ‫مــن نظــام اإلجــراءات اجلزائيــة قــد ألزمــت محكمــة اإلســتئناف بيــان‬\n      ‫مســتند املالحظــة ولــم جنــد أصحــاب الفضيلــة قــد بينوهــا لنرجــع إلــى‬\n      ‫قولهــم إن كان موافق ـ ًا لألصــول الشــرعية ‪ ،‬فاحلــق أحــق أن يتبــع ‪،‬‬\n      ‫وأمــا ماجــاء يف قــرار أصحــاب الفضيلــة بــأن علينــا النظــر والتأمــل فقــد‬\n      ‫جــرى منــا بحمــد اهلل النظــر والتأمــل قبــل إصــدار احلكــم‪ ،‬دينـ ًا نديــن‬\n      ‫اهلل بــه أوالً‪ ،‬ورعايــة للعدالــة وحفظ ـ ًا للحقــوق مبــا فيهــا حــق جماعــة‬\n      ‫املســلمني والتــي رأينــا أن يصــان جنابــه بالتشــهير باملدعــى عليهــم لثبــوت‬\n      ‫إدانتهــم بتشــكيل عصابــة للنشــل يف بيــت اهلل احلــرام‪ ،‬أمــا ماذكــره‬\n      ‫أصحــاب الفضيلــة مــن كــون اإلجابــة مــن كامــل األعضــاء فــإن‬\n      ‫القاضــي ‪ ........‬كان منتدب ـ ًا يف حينــه يف دورة تدريبيــة ملــدة شــهرين‪،‬‬\n      ‫وظــروف القضيــة وكــون املدعــى عليهــم مســاجني اســتدعى اجلــواب‬\n      ‫مــن البقيــة وعليــه جــرى العمــل‪ ،‬وأمــا مــا ذكــره أصحــاب الفضيلــة‬\n      ‫بقولهــم (( وألن التشــهير مــن اختصــاص جهــات التنفيــذ )) فهــو لفــظ‬\n      ‫مجمــل يحتمــل معنيــن‪ :‬فــإن كان املقصــود هــو إيقــاع عقوبــة التشــهير‬\n      ‫دون نــص يف احلكــم فهــو معنـ ًـى مــردود بنــص املــادة الثالثــة مــن نظــام‬\n      ‫اإلجــراءات اجلزائيــة ونصهــا‪ (( :‬ال يجــوز توقيــع عقوبــة جزائيــة علــى أي‬\n\n\n‫‪109‬‬\n\f‫شــخص إال علــى أمــر محظــور ومعاقــب عليــه شــرع ًا أو نظام ـ ًا وبعــد‬\n‫تــرى وفق ـ ًا‬‫ـاء علــى حكــم نهائــي بعــد محاكمــة ُ ْ‬          ‫ثبــوت إدانتــه بنـ ً‬\n‫للوجــه الشــرعي))‪ ،‬وإن كان املقصــود أن تنفيــذ عقوبــة التشــهير‬\n‫بعــد احلكــم بهــا مــن اختصــاص جهــات التنفيــذ فــإن هــذا هــو مقتضــى‬\n‫املــادة ( ‪ )50‬مــن النظــام األساســي للحكــم ‪ ،‬واملــادة (‪ )219‬مــن نظــام‬\n‫اإلجــراءات اجلزائيــة ‪ ،‬وعقوبــة التشــهير يف هــذه احلــال أســوة العقوبــات‬\n‫األخــرى املعهــودة يف أذهــان أصحــاب الفضيلــة كالســجن واجللــد‪،‬‬\n‫ـتثن لعقوبــة التشــهير فيمــا نعلــم والقاعــدة أن األصــل العمــوم‬          ‫وال مسـ ٍ‬\n‫وعلــى مدعــي االســتثناء الدليــل‪ ،‬وإن كان لــدى أصحــاب الفضيلــة‬\n‫دليــل الســتثناء عقوبــة التشــهير وكــون إيقاعهــا مــن اختصــاص جهــات‬\n‫التنفيــذ فليبــرزه لنــا؛ لنرجــع إليــه‪ ،‬وعليــه فإنــه بعــد دراســة املعاملــة مــن‬\n‫كافــة جوانبهــا ومــا أجبنــا بــه أخيــر ًا وبعــد التأمــل واملداولــة فإنــا نقــرر‬\n‫جميعـ ًا بأنــه لــم يظهــر لنــا ســوى مــا حكمنــا بــه ســابق ًا وقررنــا إعادتهــا‬\n‫ألصحــاب الفضيلــة قضــاة محكمــة االســتئناف وفقهــم اهلل وســددهم‬\n‫إلكمــال الزمهــا وفــق املــادة اخلامســة بعــد املائتــن مــن نظــام اإلجــراءات‬\n‫اجلزائيــة واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                               ‫وصحبــه أجمعــن حــرر يف ‪1434/09/17‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد‪ :‬ففــي يــوم اخلميــس املوافــق ‪1435/01/11‬ه ـ‬\n‫عــادت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة برقــم‬\n‫وتاريــخ ‪1435/01/02‬ه ـ واملقيــدة بأســاس هــذه احملكمــة برقــم وتاريخ‬\n‫‪1435/01/08‬ه ـ املرفــق بهــا القــرار رقــم وتاريــخ ‪1434/12/23‬ه ـ‬\n‫واملــدون علــى ظهــر الصــك املتضمــن املوافقــة علــى احلكــم مــن الدائــرة‬\n‫اجلزائيــة اخلماســية الثانيــة مبحكمــة االســتئناف مبكــة املكرمــة ‪ .‬لــذا‬\n\n\n                                                                                          ‫‪110‬‬\n\f      ‫جــرى حتريــر ذلــك وإحلاقــه حتــى ال يخفــى وبــاهلل التوفيــق وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1435/01/11‬هــ‪.‬‬\n\n\n\n\n‫‪111‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":85,"source_page_end":111,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9167c8cb93321fdf877620eba5e3f720c3c198443322f2ee8b0544567b0a8b64","normalized_text_hash":"e3f84a362651cf881f7a6e852aabac47130d673647001760d76127b22a2515b6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p85-34183961"},{"id":"171720bd-d66a-541a-89f4-20ca03d2ae3e","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة سيارة -بيع سيارة مسروقة -شراء سيارة مسروقة- قيادة سيارة مسروقة -وساطة يف بيع سيارة مسروقة -مقاومة قوات األمن -تستر -ممارسة تفحيط -عدم وجود سوابق -رجوع عن إقرار مصدق شرع ا -التعزير بالسجن واجللد -ترك عقوبة التفحيط للجهة املختصة -مراعاة تخفيف التعزير لصغر السن نظام املرور الصادر به املرسوم امللكي رقم م 85/يف 1428/10/26ه، ونص احلاجة من النظام(ثاني ا استمرار اجلهات التي تتولى حالي ا","document_number":"33471840","case_number":"33589234","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/1","year":"1434","subject":"سرقة -سرقة سيارة -بيع سيارة مسروقة -شراء سيارة مسروقة- قيادة سيارة مسروقة -وساطة يف بيع سيارة مسروقة -مقاومة قوات األمن -تستر -ممارسة تفحيط -عدم وجود سوابق -رجوع عن إقرار مصدق شرع ا -التعزير بالسجن واجللد -ترك عقوبة التفحيط للجهة املختصة -مراعاة تخفيف التعزير لصغر السن نظام املرور الصادر به املرسوم امللكي رقم م 85/يف 1428/10/26ه، ونص احلاجة من النظام(ثاني ا استمرار اجلهات التي تتولى حالي ا","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك ‪ 33471840:‬تاريخه ‪1433/12/1:‬هـ‬\n                    ‫رقم الدعوى ‪33589234:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34245303‬تاريخه‪1434/06/19 :‬ه‬\n\n\n\n‫ســرقة ‪ -‬ســرقة ســيارة‪ -‬بيــع ســيارة مســروقة‪ -‬شــراء ســيارة مســروقة‪-‬‬\n‫قيــادة ســيارة مســروقة‪ -‬وســاطة يف بيــع ســيارة مســروقة‪ -‬مقاومــة‬\n‫قــوات األمــن ‪ -‬تســتر ‪ -‬ممارســة تفحيــط ‪ -‬عــدم وجــود ســوابق‪ -‬رجــوع‬\n‫عــن إقــرار مصــدق شــرع ًا ‪ -‬التعزيــر بالســجن واجللــد‪ -‬تــرك عقوبــة‬\n‫التفحيــط للجهــة املختصــة ‪ -‬مراعــاة تخفيــف التعزيــر لصغــر الســن‬\n\n\n\n\n‫نظــام املــرور الصــادر بــه املرســوم امللكــي رقــم م‪ 85/‬يف ‪1428/10/26‬هــ‪،‬‬\n‫ونــص احلاجــة مــن النظام(ثانيـ ًا اســتمرار اجلهــات التــي تتولــى حاليـ ًا‬\n‫الفصــل يف املنازعــات والقضايــا املروريــة مهمتهــا حلــن مباشــرة الدوائر‬\n                                  ‫املختصــة بذلــك يف احملاكــم العامــة)‪.‬‬\n\n\n\n\n‫الئحــة الدعــوى ضــد تســعة مواطنــن املدعــى عليهــم األول والثانــي‬\n‫والثالــث والرابــع ســجناء‪ ،‬املدعــى عليهــم اخلامــس والســادس والســابع‬\n‫والثامــن والتاســع مفــرج عنهــم بالكفالــة‪ ،‬تضمنت الئحــة الدعوى اتهام‬\n‫الرابــع بســرقة ســيارة وبيعهــا وقيــام األول والثانــي والثالــث بشــرائها‬\n‫وقيادتهــا ومحاولــة األول الهــروب مــن رجــال األمــن وقيــام اخلامــس‬\n\n                                                                                 ‫‪112‬‬\n\f      ‫والســادس والســابع بــدور الوســاطة يف بيــع ذات الســيارة املســروقة‬\n      ‫وحضورهــم مــع الثامــن والتاســع ملشــاهدة التفحيــط وتوجيــه االتهــام لهــم‬\n      ‫جميع ـ ًا بتســترهم علــى بعضهــم وطلــب املدعــي العــام إثبــات مــا أســند‬\n      ‫إليهــم واحلكــم عليهــم بعقوبــة تعزيريــة والفصــل يف الدعــوى حيــال قيــام‬\n      ‫األول والثانــي والثالــث بالتفحيــط‪ ،‬وقــد مت القبــض علــى املدعــى عليهــم‬\n      ‫بعــد بــاغ ســرقة ســيارة جــرى التعميــم عليهــا ‪ ،‬قبــض علــى املدعــى‬\n      ‫عليــه األول والســيارة بقيادتــه ثــم مت القبــض علــى بقيــة املدعــى عليهــم‬\n      ‫لتفــاوت مســؤوليتهم فيمــا نســب إليهــم مــن جــرم ‪ ،‬ومت ســماع الدعــوى‬\n      ‫يف حــق املدعــى عليهــم الســجناء األول والثانــي والثالــث والرابــع ‪ ،‬وأقــر‬\n      ‫األول والثالــث بالدعــوى كمــا أقــر الثانــي بالدعــوى ســوى مــا يتعلــق‬\n      ‫بقيــادة الســيارة والتفحيــط عليهــا‪ ،‬ومــع إنــكار الرابــع للدعــوى إال‬\n      ‫أنــه تبــن وجــود إقــرار مصــدق شــرع ًا للرابــع كمــا تبــن عــدم وجــود‬\n      ‫بينــة للمدعــي العــام علــى مــا أنكــر الثانــي فيمــا يتعلــق بقيــادة الســيارة‬\n      ‫والتفحيــط عليهــا‪ ،‬ومت تعزيــر املدعــى عليهــم األول والثانــي والثالــث‬\n      ‫والرابــع بالســجن واجللــد‪ ،‬وثبــت إدانــة األول والثانــي والثالــث مبمارســة‬\n      ‫التفحيــط وتــرك عقابهــم للجهــة املختصــة ومت إرجــاء محاكمــة مــن لــم‬\n      ‫يحضــر حتــى حضــوره ومت تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫‪113‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...........‬القاضــي يف احملكمة اجلزائية‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ ......‬وتاريــخ ‪ ........‬ه ـ املقيــدة باحملكمــة‬\n‫برقــم ‪ ............‬وتاريــخ ‪ ...........‬ه ـ ففــي يــوم الثالثــاء املوافــق‪ ..........‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 09 : 00‬وفيهــا حضــر املدعــي العــام ‪...........‬‬\n‫وحضــر حلضــوره املدعــى عليــه األول ‪ ........‬ســعودي اجلنســية مبوجــب‬\n‫بطاقــة الســجني رقــم ‪ 2/33/442‬واملدعــى عليــه الثانــي ‪ ........‬ســعودي‬\n‫اجلنســية مبوجــب بطاقــة الســجني رقــم ‪ ......‬واملدعــى عليــه الثالــث ‪........‬‬\n‫ســعودي اجلنســية مبوجــب بطاقــة الســجني رقم‪.....‬واملدعــى عليــه الرابــع‬\n‫‪ ................‬ســعودي اجلنســية مبوجــب بطاقــة الســجني رقم‪........‬وادعــى‬\n‫األول قائــا بصفتــي عضــو هيئــة التحقيــق واالدعــاء العــام مبدينــة‬\n                                                             ‫الريــاض ادعــي علــى ‪/‬‬\n‫‪1‬ـ ‪ ........‬البالــغ مــن العمــر(‪ )19‬عامـ ًا ‪،‬ســعودي اجلنســية مبوجــب الهويــة‬\n‫رقم(‪،).............‬أعــزب ‪ ،‬متعلــم ‪،‬عاطــل‪ ،‬يقيــم مبدينــة الريــاض‬\n‫‪،‬أوقــف بتاريخ‪.......‬ه ـ وأحيــل لشــعبة ســجن امللــز مبوجــب مذكــرة‬\n‫التوقيــف رقم(‪)......‬وتاريخ‪.......‬ه ـ اســتنادا للقــرار الــوزاري رقــم(‪)1900‬‬\n        ‫املبنــي علــى املــادة رقــم (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة‪، .‬‬\n‫‪2‬ـ ‪ ، ........‬البالغ من العمر(‪ )22‬عام ًا ‪ ،‬ســعودي اجلنســية مبوجب الهوية‬\n‫رقــم(‪ ،)..........‬يقيــم مبدينــة الريــاض ‪،‬أوقــف بتاريخ‪.........‬ه ـ وأحيــل‬\n‫لشــعبة ســجن امللــز مبوجــب مذكــرة التوقيــف رقم(‪).....‬وتاريخ‪........‬ه ـ‬\n‫اســتنادا للقــرار الــوزاري رقــم(‪ )1900‬املبنــي علــى املــادة رقــم (‪ )112‬مــن‬\n                                                    ‫نظــام اإلجــراءات اجلزائيــة‪، .‬‬\n                                                                                              ‫‪114‬‬\n\f      ‫‪3‬ـ ‪ ، ..........‬البالــغ مــن العمــر(‪ )18‬عام ـ ًا ‪ ،‬ســعودي اجلنســية مبوجــب‬\n      ‫الهويــة رقــم(‪ )...........‬يقيــم مبدينــة الريــاض ‪،‬أوقــف بتاريخ‪........‬ه ـ‬\n      ‫وأحيــل لشــعبة ســجن امللــز مبوجــب مذكــرة التوقيــف رقــم(‪)............‬‬\n      ‫وتاريخ‪..........‬ه ـ اســتنادا للقــرار الــوزاري رقــم(‪ )1900‬املبنــي علــى املــادة‬\n                                      ‫رقــم (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة‪، .‬‬\n      ‫‪4‬ـ ‪ ،............‬البالغ من العمر(‪ )21‬عام ًا ‪ ،‬سعودي اجلنسية مبوجب الهوية‬\n      ‫رقــم(‪ ،)...........‬يقيــم مبدينــة الريــاض ‪،‬أوقــف بتاريخ‪1433/7/2‬ه ـ‬\n      ‫وأحيــل لشــعبة ســجن امللــز مبوجــب مذكــرة التوقيــف رقــم(‪).........‬‬\n      ‫وتاريخ‪......‬ه ـ اســتنادا للقــرار الــوزاري رقــم(‪ )1900‬املبنــي علــى املــادة‬\n                                          ‫رقــم (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة‪.‬‬\n      ‫‪5‬ـ ‪ ،..........‬البالــغ مــن العمــر(‪ )18‬عام ـ ًا ‪ ،‬اجلنســية مبوجــب الهويــة‬\n      ‫رقم(‪،)..........‬يقيــم مبدينــة الريــاض مفــرج عنــه بالكفالــة اســتنادا‬\n                                 ‫للمــادة (‪ )120‬مــن نظــام اإلجــراءات اجلزائيــة‪.، .‬‬\n      ‫‪6‬ـ ‪ ،............‬البالــغ مــن العمــر(‪ )23‬عام ـ ًا ‪ ،‬ســعودي اجلنســية مبوجــب‬\n      ‫الهويــة رقــم(‪ ،)............‬يقيــم مبدينــة الريــاض ‪،‬مفــرج عنــه بالكفالــة‬\n                           ‫اســتنادا للمــادة (‪ )120‬مــن نظــام اإلجــراءات اجلزائيــة‪.‬‬\n      ‫‪7‬ـ ‪ ، .........‬البالــغ مــن العمــر(‪ )21‬عام ـ ًا ‪ ،‬ســعودي اجلنســية مبوجــب‬\n      ‫الهويــة رقــم(‪ ،)............‬يقيــم مبدينــة الريــاض مفــرج عنــه بالكفالــة‬\n                         ‫اســتنادا للمــادة (‪ )120‬مــن نظــام اإلجــراءات اجلزائيــة‪.‬‬\n      ‫‪8‬ـ ‪ ، ............‬البالــغ مــن العمــر(‪ )20‬عام ـ ًا ‪ ،‬ســعودي اجلنســية مبوجــب‬\n      ‫الهويــة رقــم(‪ ،)...........‬يقيــم مبدينــة الريــاض‪ ،‬مفــرج عنــه بالكفالــة‬\n                        ‫اســتنادا للمــادة (‪ )120‬مــن نظــام اإلجــراءات اجلزائيــة‪، .‬‬\n\n\n\n‫‪115‬‬\n\f‫‪9‬ـ ‪، ................‬البالــغ مــن العمــر(‪ )19‬عامـ ًا ‪ ،‬ســعودي اجلنســية مبوجــب‬\n‫الهويــة رقــم(‪ ،)...........‬يقيــم مبدينــة الريــاض مفــرج عنــه بالكفالــة‬\n                      ‫اســتنادا للمــادة (‪ )120‬مــن نظــام اإلجــراءات اجلزائيــة‪.‬‬\n‫بتاريــخ ‪......‬ه ـ ابلــغ املواطــن ‪ ........ /‬عــن ســرقة ســيارته مــن نــوع ‪ ....‬اللــون‬\n‫أزرق موديــل ‪ 2009‬لوحــة رقــم( ‪ )... ....‬العائــد ة ملكيتهــا لشــركه ‪.....‬‬\n‫جــرى التعميــم عــن الســيارة والتحــري عــن اجلانــي وبتاريــخ ‪.....‬ه ـ ورد‬\n‫كتــاب مركــز شــرطة الســويدي رقــم ‪ ..........‬املتضمــن القبــض علــى ‪/‬‬\n‫‪19 ........‬عــام هويــة رقــم (‪ ).......‬مــن قبــل دوريات االمن لقيامه بالتفحيط‬\n‫علــى ســيارة مــن نــوع ‪....‬اللــون أزرق لوحــة رقــم ( ‪ ).... ...‬ومحاولــة الهــروب‬\n‫وصــدم ســيارة أخــرى مــن نــوع ‪ ....‬لوحــة رقــم (‪ ).... ...‬وباالستفســار عــن‬\n‫الســيارة أتضــح إنهــا مســروقه ومعمــم عنهــا ‪.‬ومت القبــض علــى بقيــة‬\n‫املدعــى عليهــم الحقــا مــن قبــل البحــث والتحــري‪ ،‬وضبــط يف جيــب‬\n‫الســادس حشــيش مخــدر (فــرزت اوراق مســتقلة لقضيــة حيــازة احلشــيش‬\n‫املخــدر )‪،‬ومبعاينــة الســيارة اتضــح وجــود غطــاء البنزيــن مخلــوع وفيــه‬\n‫خــدش باجلانــب االميــن واملــرآة اليمنــى محطمــة وكذلــك أثــر خــدوش‬\n‫بالصــدام االمامــي وحتــت البــاب االميــن االمامــي ووجــود صدمــه‬\n‫بالصــدام اخللفــي والبــاب االيســر االمامــي وكذلــك االســطبات اخللفيــة‬\n‫والهيــكل اخلارجــي للســيارة االمامــي وفــوق مقصــورة القيــادة بــه اثــار‬\n‫ضربــات واتضــح ان اجلنــط االيــس اخللفــي واالميــن مكســر وان ثــاث‬\n                                ‫عجــات للســيارة مت تغيرهــا وليســت االصليــة ‪.‬‬\n‫وباســتجواب املدعــى عليــه‪ ........ /‬أفــاد أنــه يف يــوم الثالثــاء ‪....../5/25‬‬\n‫الســاعة الثالثــة عصــر ًا كان مــع صديقــه ‪ ..........‬يتجــوالن علــى ســيارة‬\n‫مــن نــوع ‪ ....‬بحــي الســويدي وأثنــاء ذلــك أتصــل ‪ ........ /‬علــى ‪ .......‬وابلغــه‬\n\n\n                                                                                              ‫‪116‬‬\n\f      ‫بوجــود ســيارة مســروقة لديــه مــن نــوع ‪ ....‬وطلــب منــه عــرض الســيارة‬\n      ‫مببلــغ ثالثــة االف ريــال ملــن يرغــب بشــرائها فأخبــره ‪ ....‬بذلــك فوافــق‬\n      ‫علــى هــذا العــرض واتصــل علــى صديقــه ‪........‬واخبــره عــن العــرض‬\n      ‫فاتفقــا علــى توفيــر املبلــغ مناصف ـ ًة ثــم توجــه مــع ‪ .......‬الــى اســتراحة‬\n      ‫‪ ........‬بحــي ‪ ......‬وقابــاه واعطــاه املبلــغ وأحضــر لهــم مفتــاح الســيارة‬\n      ‫وركباهــا وفــى يــوم الســبت ‪.......‬ه ـ مــارس التفحيــط ويرافقــه ‪....... /‬‬\n      ‫وألقــي القبــض عليــه مــن قبــل دوريــات األمــن وهــرب ‪ ....... /‬وصدقــت‬\n                                                                              ‫اقوالــه بذلــك شــرع ًا ‪.‬‬\n      ‫وباســتجواب املدعــى عليــه ‪ ........ /‬أف ـ ـ ــاد أنـ ـ ــه ف ـ ــي يـ ـ ــوم الثالث ـ ــاء‬\n      ‫‪1433/5/25‬ه ـ أتص ـ ـ ـ ـ ــل عليــه ‪ ......../‬وعــرض عليــه ســيارة مســروقه‬\n      ‫مــن نــوع ‪....‬اللــون أزرق مــن أجــل التفحيــط عليهــا فرفــض وابلغــه بأنــه‬\n      ‫ال يســتخدم الســيارات املســروقة بالتفحيــط وبعــد ذلــك أتصــل عليــه‬\n      ‫‪ ......‬وأثنــاء احلديــث معــه ذكــر لــه بأنــه عرضــت عليــه ســيارة مســروقه‬\n      ‫مقابــل ثالثــة االف ريــال فذكــر‪ ........ /‬بــأن صديقــه ‪ ........‬يرغــب‬\n      ‫بشــراء الســيارة املســروقة وبعــد حوالــى ســاعه حضــر ‪ ..../‬ويرافقــه ‪........‬‬\n      ‫الــى اســتراحته بحــي ‪....‬فأعطــاه ‪ .........‬املبلــغ وطلــب منــه مفتــاح الســيارة‬\n      ‫فاحضــره عــن طريــق ‪ ........‬وأخبــره مبوقــع الســيارة وصدقــت أقوالــه‬\n                                                                                       ‫بذلــك شــرع ًا ‪0‬‬\n      ‫وباســتجواب املدعــى عليــه ‪ ......../‬أفــاد أنــه يف يــوم الثالثــاء ‪.........‬هـ ورده‬\n      ‫اتصــال مــن ‪ ........ /‬وأبلغــه عــن ســيارة مســروقه عنــد ‪ ........‬يريــد بيعهــا‬\n      ‫مببلــغ وقــدره ‪ ........‬وطلــب منــه مشــاركته بدفــع املبلــغ فوافــق علــى ذلــك‬\n      ‫واعطــاه نصــف املبلــغ ويف نفــس اليــوم أحضــر ‪ ........‬الســيارة املســروقة‬\n      ‫وأوقفهــا عنــد مســجد ‪ .......‬بالقــرب مــن منزلــه بحــي ‪....‬وســلمه املفتــاح‬\n\n\n‫‪117‬‬\n\f‫وفــى يــوم االربعــاء ‪.......‬ه ـ أخــذ الســيارة املســروقة ومــارس بهــا التفحيــط‬\n‫وكان برفقته‪ ........‬وصدقت أقواله بذلك شــرعاً‪ .‬وباســتجواب املدعى‬\n‫عليــه ‪ ...........‬أفــاد أنــه يف صبــاح يــوم الســبت ‪.......‬ه ـ كان يتجــول علــى‬\n‫ســيارة والــده مــن نــوع ‪....‬بشــارع قــرب شــارع ‪....‬وكان متعاطي ـ ًا ملــادة‬\n‫الروش(فــرزت اوراق مســتقلة لتعاطيــه املخــدرات) فشــاهد ســيارة‬\n‫مــن نــوع ‪....‬اللــون ازرق بوضــع التشــغيل فقــام بالــدوران للجهــة املقابلــة‬\n‫وأوقــف ســيارة والــده التــي كان يقودهــا ثــم ذهــب للســيارة ‪....‬وســرقها‬\n‫متجهـ ًا الــى حــي ‪....‬واوقفهــا مبواقــف اســواق ‪....‬ثــم أســتقل ســيارة اجــره‬\n‫وذهــب الــى املوقــع الســابق واخــذ ســيارة والــده وأوقفهــا عنــد منزلــه بحي‬\n‫‪....‬ثــم عــاد للســيارة املســروقة وبقيــت معــه ويف يــوم الثالثــاء ‪.......‬ه ـ ذهــب‬\n‫بهــا الــى‪ .....‬وطلــب منــه عرضهــا للبيــع بقيمــة خمســمائة ريــال وبعدهــا‬\n‫احضــر لــه ‪ ......‬املبلــغ واخــذ املفتــاح لكــي يســلمه ل‪ ........‬الــذي وافــق‬\n                                ‫علــى شــراءها وصدقــت اقوالــه بذلــك شــرعاً‪.‬‬\n‫وباســتجواب املدعــى عليــه ‪ .......‬افــاد أنــه يف يــوم الثالثاء ‪1433/5/25‬هـ‬\n‫عنــد الســاعة الرابعــة عصــر ًا كان يرافقــه ‪ ........‬يتجــوالن علــى ســيارته‬\n‫مــن نــوع ‪ ....‬يف حــي ‪....‬وأثنــاء ذلــك أتصــل عليــه ‪ ........‬وذكــر لــه بأنــه‬\n‫توجــد ســيارة مســروقه مــن نــوع ‪....‬وعــرض عليــه شــرائها مببلــغ ثالثــة‬\n‫االف ريــال فرفــض ذلــك وكان ‪ ........‬يســمع املكاملــة فقــال لــه بأنــه‬\n‫يرغــب باحلصــول علــى الســيارة فأخبــر ‪ ........‬بــأن شــخص يرغــب بشــراء‬\n‫هــذه الســيارة وأتصــل ‪ ........‬علــى ‪ .....‬وعــرض عليــه الســيارة فاتفقــا علــى‬\n‫شــرائها مناصفـ ًة وبعدهــا ذهــب هــو و‪ ........‬الــى اســتراحة ‪ ........‬وأعطــوه‬\n‫املبلــغ املتفــق عليــه وقــام بتســليمهما املفتــاح وأخبرهمــا مبوقــع الســيارة‬\n                                                    ‫فذهــب ‪ ........‬وأخــذ الســيارة‪.‬‬\n\n\n                                                                                          ‫‪118‬‬\n\f      ‫وباســتجواب املدعــى عليــه ‪ ....../‬افــاد بأنــه يف يــوم الثالثاء ‪.......‬هـ اتصل‬\n      ‫عليــه ‪ ......./‬وعــرض عليــه شــراء ســيارة مســروقه مــن نــوع ‪....‬اللــون ازرق‬\n      ‫كحلـ ـ ـ ــي بقيمــة خمســمائة ريــال فأتصــل علــى ‪ ........‬وعــرض عليــه‬\n      ‫الســيارة فوافــق و احضــر املبلــغ املتفــق عليــه وســلمه لــه وبعدهــا ذهــب‬\n      ‫الــى ‪ ......‬واســتلم منــه مفتــاح الســيارة وأخبــره مبوقعهــا وســلمه املبلــغ ثــم‬\n      ‫ذهــب ل‪ ........‬وســلمه مفتــاح الســيارة وأنكــر ركوبــه بهــا‪ .‬وباســتجواب‬\n      ‫املدعــى عليــه‪ ........‬أفــاد بأنــه يف يــوم الثالثــاء ‪ ........‬ه ـ حضــر لديــه ‪........‬‬\n      ‫علــى ســيارة ‪....‬اللــون ازرق كحلــي عنــد منزلــه بحــي ‪ ....‬واخبــره بــأن‬\n      ‫الســيارة مســروقه ويرغــب أن يقــوم بعرضهــا للبيــع علــى ‪ ........‬بقيمــة‬\n      ‫خمسمائـ ــة ريــال فوافــق علــى ذلــك وقــام باالتصــال علــى‪ ....‬وأخبــره‬\n      ‫بذلــك فأحضــر إليــه ‪ ......‬املبلــغ املتفــق عليــه وســلمه املفتــاح وأبلغــه‬\n      ‫مبوقعهــا وســلم املبلــغ لــ‪ . ......‬وباســتجواب املدعــى عليــه ‪ ........‬اعتــرف‬\n      ‫حتقيقــا بركوبــه مــع الثالــث يف ســيارة ‪ ....‬وهــو يعلــم بانهــا مســروقه‬\n      ‫حيــث اخبــره الثالــث بــان الســيارة مســروقة ولــم يبلــغ اجلهــات االمنيــة عن‬\n      ‫ســرقة الســيارة وتســتر علــى اجلنــاة‪ .‬وباســتجواب املدعــى عليــه ‪ .....‬أفــاد‬\n      ‫أنــه يف يــوم االربعــاء ‪......‬ه ـ الســاعة الثامنــة والنصــف صباح ـ ًا ركــب‬\n      ‫مــع ‪ .......‬علــى الســيارة املســروقة ‪.‬وقــد أســفرت إجــراءات التحقيــق عــن‬\n      ‫توجيــه االتهــام للمدعــى عليــه الرابــع بســرقة ســيارة وبيعهــا وقيــام االول‬\n      ‫والثانــي والثالــث بشــرائها وقيادتهــا ومحاولــة االول الهــروب مــن رجــال‬\n      ‫االمــن ‪،‬وقيــام اخلامــس والســادس والســابع بــدور الوســاطة يف بيــع ذات‬\n      ‫الســيارة املســروقة وحضورهــم والثامــن والتاســع ملشــاهدة التفحيــط‬\n      ‫وتوجيــه االتهــام لهــم جميعــا بتســترهم علــى بعضهــم البعــض وتعاونهــم‬\n      ‫علــى االثــم والعــدوان املعاقــب علــى ذلــك شــرعا‪ .‬وتوجيــه االتهــام لــأول‬\n\n\n‫‪119‬‬\n\f‫والثانــي والثالــث بقيامهــم مبمارســة التفحيــط املعاقــب علــى ذلــك‬\n                            ‫مبوجــب املــرور‪ .‬وذلــك لألدلــة والقرائــن التاليــة ‪-:‬‬\n‫‪ -1‬مــا تضمنتــه اعتــراف االول املنــوه عنــه املــدون علــى الصفحــات‬\n      ‫رقم(‪)14-13‬مبلــف االســتدالل املرفقــة علــى اللفــات رقــم (‪.)3‬‬\n‫‪ -2‬مــا تضمنــه اعتــراف الثانــي املنــوه عنــه املــدون علــى الصفحــة رقــم‬\n                               ‫(‪ )4‬مبلــف االســتدالل املرفــق علــى اللفــة (‪. )9‬‬\n‫‪ -3‬اعتــراف الثالــث املنــوه عنــه املــدون علــى الصفحــة رقــم (‪ )2-1‬مبلــف‬\n                                                ‫االســتدالل املرفــق علــى اللفــة (‪.)1‬‬\n‫‪ -4‬اعتــراف الرابــع املنــوه عنــه املــدون علــى الصفحــة رقــم (‪)11-10‬‬\n                                     ‫مبلــف االســتدالل املرفــق علــى اللفــة (‪.)4‬‬\n‫‪ -5‬اعترافــات اخلامــس والســادس والســابع والثامــن والتاســع املنــوه‬\n‫عنهــا املــدون علــى الصفحــات رقــم (‪ )3-1‬مبلــف االســتدالل املرفــق علــى‬\n‫اللفــة (‪ )8‬والصفحــات رقــم (‪ )8-6‬لفــة(‪ )9‬والصفحتــن رقــم (‪)10-8‬‬\n                         ‫لفــة رقــم(‪ )10‬والصفحــات رقــم (‪ )12-7‬لفــة (‪. )11‬‬\n‫‪ -6‬مــا تضمنــه محاضــر القبــض املرفقــة علــى اللفــة رقــم‬\n                                                   ‫( ‪. )4 4 ، 2 9 ، 2 2 ، 2 1 ، 1 3‬‬\n‫‪7‬ـ مــا تضمنــه بــاغ املبلــغ املنــوه املطابــق العتــراف الرابــع يف اجلملــة املنــوه‬\n                 ‫عنــه املــدون علــى الصفحتــن(‪ )11-10‬املرفــق لفــه رقــم(‪. )6‬‬\n‫وببحــث ســوابقهم اتضــح خلــو صحيفــة ســوابقهم مــن أي ســابقة ماعــدا‬\n‫املدعــى عليــه الثامــن والتاســع فلــم تــرد صحيفــة ســوابقهم‪ .‬وببحــث‬\n‫دخوالتهــم لــدار املالحظــة االجتماعيــة اتضــح ان الثانــي ســبق ان اوقــف‬\n‫بالــدار يف قضيــة ســرقة اغنــام وثــاث ســيارات وتفحيــط ‪،‬واتضــح ان‬\n‫الثالــث ســبق ان اوقــف بالــدار يف قضيــة اطــاق نــار‪ .‬وحيــث إن مــا أق ــدم‬\n\n\n                                                                                            ‫‪120‬‬\n\f      ‫عل ــيه ال ــمذكورون ف ــعل م ــحرم وم ــعاقب عليــه شــرع ًا لــذا أطلــب إثبــات‬\n                                              ‫مــا أســند إليهــم واحلكــم عليهــم باالتــي‬\n      ‫‪1‬ـ بعقوبــة تعزيريــة بحقــه تزجــره وتــردع غيرهــم وتشــديد العقوبــة علــى‬\n                         ‫االول والثانــي والثالــث والرابــع خلطــورة مــا أقدمــوا عليــه‬\n      ‫‪2‬ـ اطلــب الفصــل يف الدعــوى حيــال مــا أق ــدم عل ــيه ال ــمذكورون االول‬\n      ‫والثانــي والثالــث مبمارســة التفحيــط لكونه موجب ملســؤليتهم مبوجب‬\n      ‫املــادة (‪)60‬مــن نظــام املــرور الصــادر باملرســوم امللكــي رقم(‪)85‬وتاريــخ‬\n      ‫‪1426/10/28‬ه ـ وفقــا للفقــرة (ثانيا)مــن النظــام مــن النظــام املشــار‬\n      ‫اليــه‪ .‬علمــا بــان احلــق اخلــاص انتهــى بالتنــازل هــذه دعــواي وبســؤال‬\n      ‫املدعــى عليهــم عــن دعــوى املدعــي العــام أجــاب األول ‪........‬قائــا صحيــح‬\n      ‫أننــي اشــتريت الســيارة محــل الدعــوى مــن نــوع ‪....‬اللــون أزرق وال أعــرف‬\n      ‫موديلهــا مببلــغ وقــدره ثالثــة اآلف ريــال وكنــت أعلــم أنهــا مســروقة‬\n      ‫واشــتريتها مــن املدعــى عليــه الثانــي ‪ ........‬وصحيــح أننــي قمــت بقيــادة‬\n      ‫الســيارة والتفحيــط عليهــا وهربــت مــن رجــال األمــن وتســترت علــى مــن‬\n      ‫معــي وتعاونــت معهــم علــى اإلثــم والعــدوان وأنــا نــادم أشــد النــدم علــى مــا‬\n      ‫فعلــت هكــذا أجــاب وأجــاب الثانــي ‪ ........‬قائــا صحيــح أننــي اشــتريت‬\n      ‫الســيارة مــع علمــي بأنهــا مســروقة وتســترت علــى مــن معــي وتعاونــت‬\n      ‫معهــم علــى اإلثــم والعــدوان ولكننــي لــم أقــد الســيارة ولــم أفحــط عليهــا‬\n      ‫وأنــا نــادم علــى مــا فعلــت وتائــب إلــى اهلل تعالــى هكــذا أجــاب وأجــاب‬\n      ‫الثالــث ‪ .....‬قائــا صحيــح أننــي اشــتريت الســيارة مــع علمــي بأنهــا‬\n      ‫مســروقة وتســترت علــى مــن معــي وتعاونــت معهــم علــى اإلثــم والعــدوان‬\n      ‫وصحيــح أننــي قــدت الســيارة و قمــت بالتفحيــط عليهــا وأنــا نــادم علــى‬\n      ‫مــا فعلــت وتائــب إلــى اهلل تعالــى هكــذا أجــاب وأجــاب الرابــع ‪ .....‬قائــا‬\n\n\n‫‪121‬‬\n\f‫مــا ذكــره املدعــي العــام كلــه غيــر صحيــح جملــة وتفصيــا هكــذا‬\n‫أجــاب فجــرى ســؤال املدعــي العــام البينــة علــى قيــادة الثانــي للســيارة‬\n‫املســروقة والتفحيــط عليهــا وعلــى ســرقة الرابــع للســيارة وبيعهــا وتســتره‬\n‫علــى مــن معــه والتعــاون معهــم علــى اإلثــم والعــدوان فقــال أطلــب تأجيــل‬\n‫اجللســة إلحضارهــا لــذا رفعــت اجللســة إلــى يــوم األربعــاء املوافق‪.......‬ه ـ‬\n‫الســاعة ‪ 11‬وأقفلــت اجللســة الســاعة ‪10.00‬ص وبــاهلل التوفيــق وصلــى‬\n          ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن حــرر يف ‪....‬ه ـ‬\n‫احلمــد اهلل وحــده وبعــد ويف يــوم االربعــاء ‪1433/12/1‬ه ـ افتتحــت‬\n‫اجللســة وحضــر االطــراف وقــال املدعــي العــام بينتــي اقــرار املدعــى‬\n‫عليــه ونصــه «انــه يف صبــاح يــوم الســبت ‪1433/05/22‬ه ـ كنــت اجتــول‬\n‫علــى ســيارة والــدي مــن نــوع ‪ ....‬بشــارع قــرب ‪ ....‬وكنــت متعاطي ـ ًا ملــادة‬\n‫الــروش فشــاهدت ســيارة مــن نــوع ‪ ....‬اللــون ازرق بوضــع التشــغيل‬\n‫فقمــت بالــدوران للجهــة املقابلــة وأوقفــت ســيارة والــدي التــي كان‬\n‫أقودهــا ثــم ذهبــت للســيارة ‪....‬وســرقتها متجه ـ ًا الــى حــي ‪ ....‬واوقفتهــا‬\n‫مبواقــف اســواق ‪....‬ثــم أســتقلت ســيارة اجــره وذهبــت الــى املوقــع الســابق‬\n‫واخــذت ســيارة والــدي وأوقفتهــا عنــد منزلــي بحــي ‪ ....‬ثــم عــدت للســيارة‬\n‫املســروقة وبقيــت معــي ويف يــوم الثالثــاء ‪1433/5/25‬ه ـ ذهبــت بهــا‬\n‫الــى ‪ ....../‬وطلبــت منــه عرضهــا للبيــع بقيمــة خمســمائة ريــال وبعدهــا‬\n‫احضــر لــي ‪ ...... /‬املبلــغ واخــذت املفتــاح لكــي أســلمه ل‪ .....‬الــذي وافــق‬\n‫علــى شــرائها انتهــى وقــد صــدق مــن قبــل فضيلــة رئيــس احملكمــة‬\n‫بتاريــخ ‪1433/7/5‬ه ـ وبعرضــه علــى املدعــى عليــه الرابــع ‪ .....‬قــال هــذا‬\n‫االعتــراف كلــه غيــر صحيــح والبصمــة هــي بصمتــي وكان منتزعــا‬\n‫منــي باإلكــراه مــن قبــل الضابــط ‪ ........‬فجــرى ســؤاله هــل ذكــرت‬\n\n\n                                                                                      ‫‪122‬‬\n\f      ‫ذلــك لفضيلــة رئيــس احملكمــة الــذي قــام بتصديــق هــذا االعتــراف‬\n      ‫فقــال ال هكــذا قــرر فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ونظــرا‬\n      ‫إلقــرار املدعــى عليــه األول والثالــث بدعــوى املدعــي العــام كاملــة‬\n      ‫وإلقــرار الثانــي بدعــوى املدعــي العــام ســوى مــا يتعلــق بقيــادة الســيارة‬\n      ‫والتفحيــط عليهــا ولعــدم البينــة علــى ذلــك كمــا مضــى رصــده ونظــرا‬\n      ‫إلنــكار املدعــى عليــه الرابــع دعــوى املدعــي العــام كاملــة وبنــاء علــى‬\n      ‫االعتــراف املصــدق شــرعا وحيــث أن الســرقة للســيارة وهــي بوضــع‬\n      ‫التشــغيل ونظــرا لصغــر ســنهم ولعــدم وجــود ســوابق عليهــم جميعــا وملــا‬\n      ‫أظهــره األول والثانــي والثالــث مــن توبــة والنتهــاء احلــق اخلــاص بالتنــازل‬\n      ‫وألن مــا أقــدم عليــه املذكــورون فعــل محــرم ومعاقــب عليــه شــرعا فقــد‬\n      ‫ثبــت لــدي مــا أســند إلــى املدعــى عليهــم يف دعــوى املدعــي العــام مــن قيــام‬\n      ‫الرابــع بســرقة ســيارة وبيعهــا وقيــام االول والثانــي والثالــث بشــرائها‬\n      ‫وقيــادة األول والثالــث لهــا ومحاولــة االول الهــروب مــن رجــال االمــن‬\n      ‫ولهــم جميعــا بتســترهم علــى بعضهــم البعــض وتعاونهــم علــى االثــم‬\n      ‫والعــدوان املعاقــب علــى ذلــك شــرعا‪ .‬وتوجيــه االتهــام لــأول والثالــث‬\n      ‫بقيامهــم مبمارســة التفحيــط املعاقــب علــى ذلــك مبوجــب املــرور ولــم‬\n      ‫يثبــت لــدي قيــادة الثانــي للســيارة املســروقة والتفحيــط عليهــا وحكمت‬\n      ‫عليهــم مبــا يلــي أوال ‪ :‬حكمــت علــى كل واحــد مــن املدعــى عليهــم‬\n      ‫األول ‪ ........‬والثانــي ‪........‬والثالــث ‪ ......‬تعزيــرا بالســجن ملــدة ســنة مــن‬\n      ‫تاريــخ توقيــف كل واحــد منهــم حتســب منهــا مــدة التوقيــف وجلــد كل‬\n      ‫واحــد منهــم تعزيــرا مائتــي جلــدة مفرقــة علــى أربــع دفعــات كل دفعــة‬\n      ‫خمســون جلــدة بــن كل دفعــة وأخــرى مــدة أســبوع ثانيــا ‪:‬حكمــت‬\n      ‫علــى املدعــى عليــه الرابــع ‪ ....‬تعزيــرا بالســجن ملــدة ســنة وســتة أشــهر من‬\n\n\n‫‪123‬‬\n\f‫تاريــخ توقيفــه حتســب منهــا مــدة التوقيــف وجلــد ه تعزيــرا مائتــي جلــدة‬\n‫مفرقــة علــى أربــع دفعــات كل دفعــة خمســون جلــدة بــن كل دفعــة‬\n‫وأخــرى مــدة أســبوع ثالثــا ‪:‬ثبــت لــدي إدانــة املدعــى عليــه األول ‪........‬‬\n‫والثالــث ‪ .....‬مبمارســة التفحيــط املعاقــب عليــه بنظــام املــرور وأفهمتهمــا‬\n‫بــأن العقوبــة عائــدة إلــى اجلهــة املختصــة ولــم تثبــت لــدي إدانــة املدعــى‬\n‫عليــه الثانــي ‪ ........‬بالتفحيــط هــذا مــا حكمــت بــه وبعرضــه عليهــم‬\n‫قــرر املدعــى عليهــم األول والثانــي والثالــث القناعــة وقــرر املدعــي العــام‬\n‫عــدم القناعــة مكتفيــا بالئحــة االدعــاء وقــرر املدعــى عليــه الرابــع عــدم‬\n‫القناعــة وطلــب تقــدمي الئحــة اعتراضيــة فأجيــب إلــى طلبــه وأفهــم بــأن‬\n‫مــدة االعتــراض ثالثــون يومــا تبــدأ مــن تاريــخ تســليم صــورة احلكــم يف‬\n‫هــذا اليــوم وإذا لــم يتقــدم خاللهــا فيســقط حقــه يف االعتــراض وترفــع‬\n‫املعاملــة حملكمــة االســتئناف دون الئحتــه ففهــم ذلــك وعليــه جــرى‬\n‫التوقيــع وأرجــأت احلكــم علــى البقيــة حلــن حضورهــم وأقفلــت اجللســة‬\n‫الســاعة‪ 10.30‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                     ‫آلــه وصحبــه وســلم ‪ .‬حــرر ونطــق احلكــم يف ‪ ........‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق‪ ......‬ه ـ افتتحــت اجللســة‬\n‫الساعة‪ 11.00‬وفيها حضر ‪ ...........‬سجله املدني ‪ ......‬الوكيل عن ‪......‬‬\n‫بالوكالــة رقــم ‪ ....‬يف ‪.......‬ه ـ الصــادرة مــن كاتــب عــدل وزارة الداخليــة‬\n‫املكلــف ولــه فيهــا حــق املرافعــة واملدافعــة واإلقــرار واإلنــكار واســتالم‬\n‫الصكــوك واالعتــراض علــى األحــكام وقبولهــا وتقــدمي اللوائــح وحيــث‬\n‫أن القــرار تأخــر وروده مــن قســم الوثائــق فقــد جــرى تســليم املدعــى‬\n‫عليــه وكالــة صــورة مــن القــرار الشــرعي مــن أجــل إعــداد الالئحــة ومت‬\n‫احتســاب املــدة النظاميــة مــن هــذا اليــوم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n\n\n                                                                                         ‫‪124‬‬\n\f                   ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ ......‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .............‬القاضــي يف احملكمــة‬\n      ‫اجلزائيــة بالريــاض واملكلــف باملكتــب القضائــي (‪ )........‬و يف يــوم‬\n      ‫األربعــاء املوافــق‪ .......‬ه ـ افتتحــت اجللســة الســاعة ‪ 11،15‬وفيهــا قــدم‬\n      ‫املعتــرض الئحتــه االعتراضيــة املكونــة مــن (‪ )7‬صفحــات وقيــدت‬\n      ‫باحملكمــة بتاريــخ ‪......‬ه ـ يف وقــت إجازتــي الرســمية وباالطــاع عليهــا‬\n      ‫لــم أجــد مــا يؤثــر علــى حكمــي الســابق وقــررت رفعهــا إلــى محكمــة‬\n      ‫االســتئناف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                    ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ ......‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n      ‫مالحظ ـ ًا عليهــا بقرارهــم رقــم ‪ .....‬يف‪.....‬ه ـ حيــث ال حــظ أصحــاب‬\n      ‫الفضيلــة اآلتــي ‪:‬ـ «أثبــت فضيلتــه إدانــة املدعــى عليهمــا األول والثالــث‬\n      ‫مبمارســة التفحيــط وإفهامهمــا بــأن عقابهمــا عائــد للجهــة املختصــة‬\n      ‫وهــذا إفهــام غيــر متوجــه إذ أن املتعــن احلكــم علــى املدعــى عليهمــا‬\n      ‫مبــا يتناســب مــع جرمهمــا وتعزيرهمــا لقــاء ذلــك وفقــا ملقتضــى املــادة‬\n      ‫(‪ )69‬مــن نظــام املــرور وبــاهلل التوفيــق» عليــه أجيــب أصحــاب الفضيلــة‬\n      ‫أن املرســوم امللكــي رقــم م‪ 85 /‬يف ‪1428/10/26‬ه ـ قــد نــص علــى مــا‬\n      ‫يلــي‪ :‬ثانيــا ‪ :‬اســتمرار اجلهــات التــي تتولــى حاليــا الفصــل يف املنازعــات‬\n      ‫والقضايا واملخالفات املرورية يف مباشرة مهماتها حلني مباشرة الدوائر‬\n      ‫املختصــة بذلــك يف احملاكــم العامــة أنتهــى ‪ .‬لــذا وحيــث أن العمــل قبــل‬\n      ‫صــدور هــذا النظــام علــى إثبــات اإلدارة وتــرك العقوبــة للجهــة املختصــة‬\n      ‫فإنــه ال وجــه لتقريــر العقوبــة مــن قبلنــا لــذا فإننــي الزلــت علــى حكمــي‬\n              ‫الســابق‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n\n\n‫‪125‬‬\n\f‫احلمــد هلل وحــده أطلــع قضــاة الدائــرة اجلزائيــة األولــى علــى املعاملــة‬\n‫الــواردة مــن احملكمــة اجلزائيــة بالريــاض برقــم‪ ......‬تاريــخ ‪ ........‬واملرفــق‬\n‫بهــا القــرار الصــادر مــن فضيلــة القاضــي ‪ ......‬برقــم ‪ ......‬وتاريــخ ‪.......‬ه ـ‬\n‫واخلــاص بدعــوى املدعــي العــام ضــد ‪ ........‬ورفقــاه وموضوعهــا ســرقه‬\n‫وتفحيــط وبعــد التدقيــق يف إجابــة فضيلــة ناظــر القضيــة وفقــه اهلل علــى‬\n‫قــرار محكمــة االســتئناف الســابق تقــرر املصادقــة علــى احلكــم لعــدم‬\n             ‫موجــب املالحظــة وصلــى اهلل علــى نبينــا محمــد واهلل املوفــق‪.‬‬\n\n\n\n\n                                                                                         ‫‪126‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":112,"source_page_end":126,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"087939418591bf51f30634ac3858c08b09a94ba9d74750ffea72027efebf2ec6","normalized_text_hash":"23e28fbe8817d21cf89fba5e815ca12ff7e576d7773646a58431c13bcfc3c9e4","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p112-33471840"},{"id":"92bbb7bb-2ea0-5b79-a8ad-55c76471e3b1","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة دواجن ودراجة نارية وجوال وبطارية سيارة ومضخة مياه -املشاركة يف السرقة -الرجوع عن قرار مصدق شرعا -درء حد السرقة بالشبهة -وجود سابقه للمدعى عليه الثالث -التعزير بالسجن واجللد -صرف نظر عن مصادرة السيارة .","document_number":"34173949","case_number":"33589458","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باألحساء","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/28","year":"1434","subject":"سرقة -سرقة دواجن ودراجة نارية وجوال وبطارية سيارة ومضخة مياه -املشاركة يف السرقة -الرجوع عن قرار مصدق شرعا -درء حد السرقة بالشبهة -وجود سابقه للمدعى عليه الثالث -التعزير بالسجن واجللد -صرف نظر عن مصادرة السيارة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34173949 :‬تاريخه ‪1434/03/28:‬هـ‬\n                           ‫رقم القضية‪33589458 :‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34238667‬تاريخه‪1434/06/12 :‬هـ‬\n\n\n\n      ‫ســرقة ‪ -‬ســرقة دواجــن ودراجــة ناريــة وجــوال وبطاريــة ســيارة ومضخــة‬\n      ‫ميــاه ‪ -‬املشــاركة يف الســرقة ‪ -‬الرجــوع عــن قــرار مصــدق شــرعا ‪ -‬درء‬\n      ‫حــد الســرقة بالشــبهة ‪ -‬وجــود ســابقه للمدعــى عليــه الثالــث ‪ -‬التعزيــر‬\n                       ‫بالســجن واجللــد ‪ -‬صــرف نظــر عــن مصــادرة الســيارة ‪.‬‬\n\n\n\n\n              ‫‪1 .1‬قوله صلى اهلل عليه وسلم‪(( :‬ادرؤوا احلدود بالشبهات)) ‪.‬‬\n      ‫‪2 .2‬مــا ذكــره أهــل العلــم أن الرجــوع عــن اإلقــرار شــبهة توجــب درء‬\n                                                                     ‫احلــد‪.‬‬\n                 ‫‪3 .3‬الشريعة جاءت بحفظ الضرورات اخلمس ومنها املال‪.‬‬\n\n\n\n\n      ‫ادعى املدعي العام على األول باالشــتراك يف ســرقة حمام من مزرعة‪،‬‬\n      ‫وســرقة جهــاز هاتــف محمــول ‪ ،‬وغيرهــا مــن املســروقات ‪ ،‬والثانــي‬\n      ‫والثالــث بالقيــام بالقفــز إلــى داخــل عــدة مــزارع باالشــتراك يف ســرقة‬\n      ‫حمــام ‪ ،‬ودجــاج منهــا ‪ ،‬وغيرهــا مــن املســروقات ‪ ،‬حيــث تقــدم أحــد‬\n      ‫األشــخاص ببــاغ الشــرطة يفيــد فيــه ســرقة عــدد مــن الدجــاج واحلمــام‬\n      ‫مــن احلــوش التابــع لــه ‪ ،‬كمــا تقــدم شــخص آخــر يفيد فيه بســرقة حمام‬\n      ‫مــن مزرعتــه ‪ ،‬كمــا تقــدم شــخص ثالــث يفيــد فيــه عــن ســرقة حمــام‬\n\n‫‪127‬‬\n\f‫ودجــاج مــن احلــوش التابــع لــه ‪ ،‬كمــا تقــدم شــخص رابــع يفيــد بســرقة‬\n‫مائــة وخمســن دجاجــة مــن مزرعتــه ‪ ،‬كمــا تقــدم شــخص خامــس يفيد‬\n‫بســرقة دراجتــن ناريتــن مــن منزلــه ‪ ،‬كمــا تقــدم شــخص ســادس يفيــد‬\n‫بســرقة جــوال مــن احملــل الــذي يعمــل فيــه ‪ ،‬كمــا تقــدم شــخص ســابع‬\n‫يفيــد بســرقة عــدد مــن الدجــاج واحلمــام مــن مزرعتــه ‪ ،‬وباالطــاع علــى‬\n‫خطــاب شــعبة التحريــات والبحــث اجلنائــي ‪ ،‬مت القبــض علــى املدعــى‬\n‫عليهــم لقيامهــم بعــدة ســرقات يف أماكــن مختلفــة ن وباالنتقــال ملنــزل‬\n‫املدعــى عليــه الثانــي ‪ ،‬عثــر علــى ماطــور املــاء الــذي متــت ســرقته مــن‬\n‫أحــد املنــازل حتــت اإلنشــاء ‪ ،‬وطلــب املدعــي العــام إقامــة حــد الســرقة‬\n‫بحــق املدعــى عليهــم ‪ ،‬ومصــادرة الســيارة املســتخدمة يف ارتــكاب‬\n‫اجلرائــم ‪ ،‬أنكــر املدعــى عليهــم مــا جــاء بدعــوى املدعــي العــام وبطلــب‬\n‫البينــة مــن املدعــي العــام علــى دعــواه ذكــر إقــرارات املدعــى عليهــم‬\n‫حتقيق ـ ًا مبــا جــاء بدعــوى املدعــي العــام ‪ ،‬قضــت احملكمــة بــدرء حــد‬\n‫الســرقة عــن املدعــي عليهــم واحلكــم بتعزيــر املدعــى عليهــم بالســجن‬\n‫واجللــد كمــا قضــت احملكمــة بصــرف النظــر عــن طلــب املدعــي العــام‬\n‫مصــادرة الســيارة املوصوفــة يف الدعــوى لعــدم ثبــوت موجبــه ‪ ،‬قنــع‬\n‫املدعــى عليهــم باحلكــم ‪ ،‬وقــرر املدعــي العــام اعتراضــه علــى احلكــم‬\n         ‫بالئحــة اعتراضيــة ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده لدينــا نحــن و و القضــاة يف احملكمــة العامــة باألحســاء‬\n‫ـاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n                                                                        ‫وبنـ ً‬\n‫مبحافظــة األحســاء برقــم‪33589458 /‬وتاريــخ ‪1433/10/08‬هـ حضر‬\n\n                                                                                   ‫‪128‬‬\n\f      ‫املدعــي العــام ‪ .....‬ســعودي بالســجل املدنــي رقــم‪ .....‬وادعــى علــى‬\n      ‫ا بصفتــي مدعي ـ ًا عام ـ ًا يف دائــرة االدعــاء العــام‬‫احلاضريــن معــه قائ ـ ً‬\n      ‫مبحافظــة األحســاء أدعــي علــى كل مــن ‪ 1 :‬ـ ‪ ،.....‬البالــغ مــن العمــر‬\n      ‫(‪ ).....‬عام ـ ًا ‪ ،‬غيــر محصــن ‪ ،‬الديانــة مســلم ‪ ،‬ســوداني اجلنســية ‪،‬‬\n      ‫مبوجــب جــواز الســفر رقــم (‪ ، ).....‬طالــب ‪ ،‬أوقــف بتاريخ ‪1433/5/9‬هـ‬\n      ‫ثم أفرج عنه بتاريخ ‪1433/5/17‬هـ وأعيد إيقافه بتاريخ ‪1433/9/4‬هـ‬\n      ‫ا لديهــم برقــم‬ ‫وأحيــل إلــى شــعبة ســجن محافظــة األحســاء وســجل نزيـ ً‬\n      ‫(‪ ).....‬مبوجــب املــادة (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة الفقــرة (‬\n      ‫األولــى ) مــن القــرار الــوزاري ( ‪ ) 1900‬وتاريــخ ‪1428/7/9‬ه ـ ‪2.‬ـ ‪،.....‬‬\n      ‫البالــغ مــن العمــر (‪ )21‬عام ـ ًا ‪ ،‬غيــر محصــن ‪ ،‬ســعودي اجلنســية ‪،‬‬\n      ‫مبوجــب الســجل املدنــي رقــم (‪ ، ).....‬متســبب ‪ ،‬أوقــف بتاريــخ‬\n      ‫‪1433/5/10‬ه ـ ثــم أفــرج عنــه بتاريــخ ‪1433/5/17‬ه ـ وأعيــد إيقافــه‬\n      ‫بتاريــخ ‪1433/9/4‬ه ـ وأحيــل إلــى شــعبة ســجن محافظــة األحســاء‬\n      ‫ا لديهــم برقــم (‪ ).....‬مبوجــب املــادة (‪ )112‬مــن نظــام‬        ‫وســجل نزي ـ ً‬\n      ‫اإلجــراءات اجلزائيــة الفقــرة ( األولــى ) مــن القــرار الــوزاري ( ‪) 1900‬‬\n      ‫وتاريــخ ‪1428/7/9‬ه ـ ‪ 3‬ـ ‪ ، .....‬البالــغ مــن العمــر (‪ )33‬عام ـ ًا ‪ ،‬غيــر‬\n      ‫محصــن ‪ ،‬ســعودي اجلنســية ‪ ،‬مبوجــب الســجل املدنــي رقــم (‪، ).....‬‬\n      ‫متســبب ‪ ،‬أوقــف بتاريــخ ‪1433/5/9‬ه ـ ثــم أفــرج عنــه بتاريــخ‬\n      ‫‪1433/5/17‬ه ـ وأعيــد إيقافــه بتاريــخ ‪1433/9/4‬ه ـ وأحيــل إلــى شــعبة‬\n      ‫ا لديهــم برقــم (‪ ).....‬مبوجــب‬    ‫ســجن محافظــة األحســاء وســجل نزي ـ ً‬\n      ‫املــادة (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة الفقــرة ( األولــى ) مــن القرار‬\n      ‫الــوزاري ( ‪ ) 1900‬وتاريــخ ‪1428/7/9‬ه ـ ‪.‬فباالطــاع علــى محضــر‬\n      ‫البــاغ ‪ :‬املعــد مــن قبــل رجــال الضبــط اجلنائــي تبــن أنــه يف يــوم الســبت‬\n\n\n‫‪129‬‬\n\f‫املوافــق ‪1433/5/15‬ه ـ تقــدم املواطــن‪ ...../‬ببــاغ يفيــد فيــه عــن ســرقة‬\n‫عــدد مــن الدجــاج واحلمــام تقــدر قيمتهــا مببلــغ مائتــا ريـ ـ ‪200‬ـ ـ ـ ـ ــال مــن‬\n‫احلــوش العائــد لــه الواقــع خلــف ‪ ....‬بــال‪. ....‬كمــا أنــه باالطــاع علــى‬\n‫محضــر البــاغ ‪ :‬املعــد مــن قبــل رجــال الضبــط اجلنائــي تبــن أنــه يف يــوم‬\n‫الســبت املوافــق ‪1433/5/15‬ه ـ تقــدم املواطــن‪ ...../‬ببــاغ يفيــد فيــه عــن‬\n‫ســرقة حمــام مــن مزرعتــه الواقعــة بحــي ‪ .....‬تقــدر قيمتهــا بألــف‬\n‫وخمســمائة ريــ‪ 1500‬ـ ـ ـ ــال ‪.‬وباالطــاع علــى محضــر البــاغ ‪ :‬املعــد مــن‬\n‫قبــل رجــال الضبــط اجلنائــي تبــن أنــه يف يــوم الســبت املوافــق‬\n‫‪1433/5/15‬ه ـ تقــدم املواطــن‪ ...../‬ببــاغ يفيــد فيــه عــن ســرقة دجــاج‬\n‫وحمــام مــن احلــوش التابــع لــه الواقــع علــى امتــداد طريــق قريــة ‪ .....‬تقــدر‬\n‫قيمتهــا بســبعمائة ري ــ‪ 700‬ـ ـ ـ ــال ‪.‬كمــا أنــه باالطــاع علــى محضر البالغ‬\n‫‪ :‬املعــد مــن قبــل رجــال الضبــط اجلنائــي تبــن أنــه يف يــوم الســبت املوافــق‬\n‫‪1433/5/15‬ه ـ تقــدم املواطــن‪ ...../‬ببــاغ يفيــد فيــه عــن ســرقة عــدد‬\n‫مائــة وخمســون دجاجــة مــن مزرعتــه الواقعــة خلــف ‪ .....‬تقــدر قيمتهــا‬\n‫بخمســة االف ري ــ‪5000‬ـ ـ ـ ـ ــال ‪.‬كمــا أنــه باالطــاع علــى محضــر البــاغ‬\n‫‪ :‬املعــد مــن قبــل رجــال الضبــط اجلنائــي تبــن أنــه يف يــوم األحــد املوافــق‬\n‫‪1433/5/16‬ه ـ تقــدم املواطــن‪ /‬ببــاغ يفيــد فيــه عــن ســرقة دراجتــن‬\n‫ناريتــن األولــى مــن نــوع ( ‪ ) ....‬والثانيــة نــوع ( ‪ ) ......‬مــن منزلــه تقــدر‬\n‫قيمتهــا بألفــن وخمســمائة ري ـ ـ ‪ 2500‬ـ ـ ـ ـ ـ ـ ــال ‪.‬كمــا أنــه باالطــاع علــى‬\n‫محضــر البــاغ املعــد مــن قبــل رجــال الضبــط اجلنائــي تبــن أنــه يف يــوم‬\n‫األحــد املوافــق ‪1433/5/16‬ه ـ تقــدم املقيم‪( ...../‬بنجالديشــي اجلنســية)‬\n‫ببــاغ يفيــد فيــه عــن ســرقة جهــازه اجلــوال مــن نــوع ( ‪ ) .....‬مــن احملــل‬\n‫الــذي يعمــل بــه وتقــدر قيمتــه بثالثــون ريــ‪ 30‬ـ ـ ــال ‪.‬كمــا أنــه باالطــاع‬\n\n\n                                                                                           ‫‪130‬‬\n\f      ‫علــى محضــر البــاغ املعــد مــن قبــل رجــال الضبــط اجلنائــي تبــن أنــه يف‬\n      ‫يــوم الثالثــاء املوافــق ‪1433/5/18‬ه ـ تقــدم املواطــن‪ ...../‬ببــاغ يفيــد‬\n      ‫فيــه عــن ســرقة عــدد مــن الدجــاج واحلمــام مــن مزرعتــه الواقعــة خلــف‬\n      ‫ملعــب األســتاد الرياضــي تقــدر قيمتهــا بخمســة آالف ري ــ‪5000‬ـ ـ ـ ــال‪.‬‬\n      ‫كمــا أنــه باالطــاع علــى محضــر تنفيــذ مهمــة املعــد مــن قبــل إحــدى‬\n      ‫الفــرق األمنيــة تبــن أنــه يف يــوم األحــد املوافــق ‪1433/5/9‬ه ـ وأثنــاء‬\n      ‫قيامهــم مبهامهــم مت القبــض علــى املدعــى عليهــم بنــاء علــى خطــاب‬\n      ‫شــعبة التحريــات والبحــث اجلنائــي رقــم ( ‪/9/21‬ص‪ ) 358/‬بتاريــخ‬\n      ‫‪1433/5/8‬ه ـ لقيامهــم بعــدة ســرقات يف أماكــن مختلفــة‪ .‬وباالنتقــال‬\n      ‫ملنــزل املدعــى عليــه الثانــي وتفتيشــه عثــر علــى ( ماطــور املــاء ) الــذي متــت‬\n      ‫ســرقته مــن املنــزل الــذي حتــت اإلنشــاء والواقــع خلف مركــز مكافحة‬\n      ‫التدخــن( ‪ .) ....‬وباســتجواب املدعــى عليــه األول أقــر أنــه منــذ أربعــة‬\n      ‫أشــهر قــام املدعــى عليهمــا الثانــي والثالــث باحلضــور لديــه عنــد املنــزل‬\n      ‫بحــي ‪ ....‬يف وقــت متأخــر مــن الليــل واجتهــوا ســوي ًا علــى ســيارة الثالــث‬\n      ‫نــوع ( ‪ ) ....‬إلــى مزرعــة بحــي ‪ ....‬وقامــوا بالقفــز داخــل املزرعــة وأحضــروا‬\n      ‫قفصــن كبيريــن بهمــا عــدد كبيــر مــن احلمــام وكان يراقــب لهمــا‬\n      ‫املــكان يف اخلــارج فيقــوم بالتصفيــر لهمــا يف حــال حضــور أي شــخص‪.‬‬\n      ‫وباســتجواب املدعــى عليــه الثانــي أقــر أنــه منــذ فتــرة قــام باالشــتراك مــع‬\n      ‫املدعــى عليــه الثالــث واحلــدث ( فــرزت لــه أوراق مســتقلة وأحيلــت لــدار‬\n      ‫املالحظــة ) يف عــدة ســرقات منهــا ســرقة دبــاب لــون ســماوي مــن منــزل‬\n      ‫بحــي ‪ ....‬فقــام احلــدث ‪ ....‬بالقفــز وفتــح بــاب املنــزل لهــم وقــام بتحميلــه‬\n      ‫مــع الثالــث بســيارته نــوع (‪ ، ) .....‬وقــام الثالــث بالقفــز وفتــح بــاب املنــزل‬\n      ‫ودخــل إلــى داخــل املنــزل وقــام بســرقة ( ماطــور ) مــاء لونــه أصفــر‬\n\n\n‫‪131‬‬\n\f‫ووضعــه يف منزلــه ‪ ،‬وقــام باالشــتراك مــع الثالــث واملتهــم ( فــرزت لــه‬\n‫أوراق مســتقلة كونــه هــارب ) يف ســرقة حمــام مــن مزرعــة علــى طريــق‬\n‫‪ .....‬وكان عــدد احلمــام ( ‪ ) 50‬حمامــة ودوره يف الســرقة مراقبــة املزرعــة‬\n‫‪ ،‬وقــام باالشــتراك مــع األول والثالــث يف ســرقة ( ثالثــن ) حمامــة مــن‬\n‫داخــل مزرعــة بالــ‪ ....‬حيــث قــام الثالــث بالقفز واســتخراج احلمام وكان‬\n‫دوره مراقبــة املوقــع مــع األول ‪ ،‬وقــام باالشــتراك مــع الثالــث يف ســرقة‬\n‫دجــاج مــن مزرعــة بحــي ‪ ......‬وعددهــا غيــر معــروف وكان دوره املراقبــة‬\n‫فيمــا قــام الثالــث بالقفــز وســرقة الدجــاج ‪ ،‬وقــام باالشــتراك مــع الثالــث‬\n‫يف ســرقة دجــاج وحمــام مــن مزرعــة قــرب ‪ .....‬ودوره املراقبــة أمــا الثالــث‬\n‫فقــد قــام بقــص الشــبك والدخــول معــه ‪ ،‬وقــام باالشــتراك مــع الثالــث‬\n‫بســرقة ثالثــة مــزارع وســرقا منهــا عــدد ( ‪ ) 100‬حمامــة غاليــة الثمــن‬\n‫وعــدد (‪ ) 20‬دجاجــة غاليــة الثمــن وعــدد ( ‪ ) 15‬دجاجــة وجميعهــا واقعــة‬\n‫علــى طريــق ‪ .....‬ودوره هــو املراقبــة ودور الثالــث القفــز والســرقة‪.‬‬\n‫وباســتجواب املدعــى عليــه الثالــث أقــر أنــه منــذ فتــرة شــاهد احلــدث‪.....‬‬\n‫وبحوزتــه دراجــة ناريــة وقــام بإيصالــه ملنــزل الثانــي الواقــع بحــي ‪......‬‬\n‫وباســتجواب احلــدث‪ ( .....‬املفــرزة لــه أوراق مســتقلة ) أفــاد أنــه قبــل‬\n‫حوالــي أربعــة أســابيع رغــب يف شــراء دراجــة ناريــة فقــام شــخص بإخباره‬\n‫أنــه يوجــد دراجــه لــدي الثانــي ‪ ،‬فتوجــه إليــه ويف أثنــاء احلديــث معــه‬\n‫حضــر الثالــث وأبلغــه بأنــه يوجــد لديــه دراجــة ناريــة وأنهــا موجــودة يف‬\n‫منــزل أهلــه الواقــع يف حــي ‪ .....‬فذهــب معــه وعنــد وصولهمــا للمنــزل‬\n‫أخــذ بالتحــدث عــن طريــق اجلــوال ثــم ذكــر لــه بــأن أهلــه اآلن غيــر‬\n‫موجوديــن ومســافرين خــارج املنطقــة وأمــره بــأن يقفــز إلــى املنــزل وقــام‬\n‫بالقفــز لداخــل املنــزل وقــام بفتــح البــاب لــه ثــم دخــل وقــام بإخــراج‬\n\n\n                                                                                     ‫‪132‬‬\n\f      ‫دراجتــن مــن املنــزل وقــام بوضعهمــا يف ســيارته التــي مــن نــوع ( ‪ ) .....‬ثــم‬\n      ‫غــادر املــكان وتركــه يف الشــارع ‪.‬وباالنتقــال رفــق املدعــى عليــه األول‬\n      ‫والثاني لإلرشاد عن مواقع األماكن التي قاموا بسرقتها وباالستدالل‬\n      ‫عليهــا تطابقــت تلــك املواقــع مــع اعترافاتهــم والبالغــات املنــوه عنهــا‪.‬‬\n      ‫وقــد أســفر التحقيــق معهــم عــن توجيــه االتهــام لــأول باالشــتراك يف‬\n      ‫ســرقة حمــام مــن مزرعــة وســرقة جهــاز هاتــف محمــول وبســرقة بطاريــة‬\n      ‫ســيارة نــوع ‪ .....‬وآلــة قطــع حديــد ( فرنــدل ) ‪ ،‬وتوجيــه االتهــام للثانــي‬\n      ‫والثالــث بالقيــام بالقفــز إلــى داخــل عــدة مــزارع وســرقة أعــداد كبيــرة‬\n      ‫مــن الدجــاج واحلمــام بعضهــا غاليــة الثمــن وبالقفــز إلــى داخــل منــزل أحد‬\n      ‫املواطنــن وســرقة دراجــة ناريــة منــه وســرقة (ماطــور) مــاء مــن منــزل‬\n      ‫حتــت اإلنشــاء‪ ،‬وذلــك لألدلــة والقرائــن التاليــة ‪ :‬ـ إقــرارات املدعــى‬\n      ‫عليهــم املنــوه عنهــا املدونــة علــى الصفحــات رقــم ( ‪13 ، 12 ، 11 ، 10‬‬\n      ‫‪ ) 16 ،‬مبلــف التحقيــق رقــم ( ‪ ) 3‬لفــة رقــم ( ‪ ) 3‬وعلــى الصفحــات رقــم‬\n      ‫( ‪ 1‬ـ ‪ ) 9‬مبلــف التحقيــق رقــم ( ‪ ) 5‬لفــة رقــم ( ‪2. ) 5‬ـ مــا جــاء يف أقــوال‬\n      ‫احلــدث‪ .....‬حديــد املنــوه عنهــا ‪ ،‬واملدونــة علــى الصفحــات رقــم (‪ 1‬ـ ‪)6‬‬\n      ‫مبلــف التحقيــق رقــم ( ‪ ) 7‬لفــة رقــم ( ‪ ) 7‬قرينــة قاطعــة علــى صحــة‬\n      ‫االتهــام ‪3‬ـ محضــر اإلرشــاد املنــوه عنــه املتضمــن قيــام األول والثانــي‬\n      ‫باإلرشــاد إلــى أماكــن الســرقات التــي ارتكبوهــا ‪ ،‬واملــدون علــى اللفــة‬\n      ‫رقــم ( ‪ . ) 62‬وبالبحــث عمــا إذا كان لهــم ســوابق عثــر للثالــث علــى‬\n      ‫ســابقة مقاومــة رجــال األمــن والهــروب مــن الســلطة ولــم يعثــر لــأول‬\n      ‫والثانــي علــى ســوابق مســجلة حتــى تاريخــه ‪ .‬وحيــث إن مــا أقــدم عليــه‬\n      ‫املذكوريــن فعــل محــرم ومعاقــب عليــه شــرعا وهــو ســرقة مــال محتــرم‬\n      ‫مــن حــرزه بعــد هتكــه ويزيــد عــن النصــاب ال شــبهة لهــم فيــه وطالــب بــه‬\n\n\n‫‪133‬‬\n\f‫أصحابــه ولكــون اجلنــاة مكلفــون غيــر مكرهــن ‪،‬لــذا أطلــب إثبــات‬\n‫مــا أســند إليهــم واحلكــم عليهــم مبــا يلــي ‪ :‬ـ ‪ 1‬ـ بحــد الســرقة الــواردة يف‬\n‫اآليــة الكرميــة رقــم ( ‪ ) 38‬مــن ســورة املائــدة ‪ 2.‬ـ مصــادرة الســيارة مــن‬\n‫نــوع ‪ ....‬والعائــدة ملكيتهــا للثالــث الســتخدامها يف ارتــكاب اجلرائــم ‪.‬‬\n‫( علمـ ًا بــأن احلقــوق اخلاصــة مــا زالــت قائمـ ًا ) أ‪.‬ه ـ وبســؤال املدعى عليهم‬\n‫عــن دعــوى املدعــي العــام أجــاب املدعــى عليــه األول قائــا مــا ذكــره‬\n‫املدعــي العــام يف دعــواه غيــر صحيــح والصحيــح أنــه حضــر إلــي املدعــى‬\n‫عليهمــا الثانــي والثالــث وركبــت معهــم ألجــل شــراء دبــاب مــن ‪ ....‬ويف‬\n‫الطريــق توقفنــا عنــد مزرعــة بحــي ‪ ....‬ونــزال وبقيــت يف الســيارة ثــم‬\n‫حضــرا ووضعــا شــيئ ُا يف صنــدوق الســيارة ال أعلــم مــا هــو ومــا ذكــر مــن‬\n‫ســرقتي جلهــاز جــوال وبطاريــة ‪ .....‬كلهــا غيــر صحيــح أيضــا هكــذا‬\n‫ا مــا ذكــره املدعــي العــام غيــر‬ ‫أجــاب وأجــاب املدعــى عليــه الثانــي قائـ ُ‬\n‫صحيــح والصحيــح أن املدعــى عليــه الثالــث أوهمنــي بــأن املــزارع‬\n‫املذكــورة يف الدعــوى ألقاربــه وأعمامــه وطلــب منــي الذهــاب معــه لهــا‬\n‫قــام هــو بأخــذ احلمــام والدجــاج منهــا أنــا بقيــت يف الســيارة وال أعلــم أنــه‬\n‫يقــوم بالســرقة ومــا ذكــر مــن أنــي قمــت بالقفــز إلــى داخــل منــزل أحــد‬\n‫املوطنــن وســرقة دراجــة ناريــة ومــا طــور مــاء غيــر صحيــح هكــذا أجاب‬\n‫وأجــاب املدعــى عليــه الثالــث قائــا مــا ذكــره املدعــي العــام غيــر‬\n‫صحيــح جملــة وتفصيــا ثــم جــرى ســؤال املدعــي العــام عــن البينــة علــى‬\n‫دعــواه قــال بينتــي مــا يف أوراق املعاملــة وبالرجــوع إلــى أوراق املعاملــة‬\n‫جــرى االطــاع علــى اعتــراف املدعــى عليــه األول علــى صحيفــة (‪)13‬‬\n‫لفــه (‪ )3‬ونصــه ( أقــر أنــا املدعــو ‪ .....‬ســوداني اجلنســية رقــم اجلــواز وأنــا‬\n‫بكامــل قــواي العقليــة املعتبــرة شــرع ًا غيــر مكــره وال مجبــر بأننــي‬\n\n\n                                                                                         ‫‪134‬‬\n\f      ‫منــذ أربــع أشــهر مــن تاريــخ هــذا االعتــراف قــام املدعــو و باحلضــور لــدي‬\n      ‫عنــد املنــزل بحــي ‪ ....‬يف وقــت متأخــر يف الليــل واجتهنــا ســويا على ســيارة‬\n      ‫املذكــور وهــي نــوع ‪ .....‬لــون ابيــض موديلهــا قدميــة واجتهنــا إلــى مزرعــة‬\n      ‫بحــي ‪ ....‬حيــث قــام بالقفــز داخــل املزرعــة وإحضــار قفصــن كبيريــن‬\n      ‫بهــا عــدد كبيــر مــن احلمــام فيمــا كنــت أراقــب لهمــا املكان مــن اخلارج‬\n      ‫حيــث أقــوم بالتصفيــر لهــم يف حــال حضــور اي شــخص وهــذا اعتــرايف‬\n      ‫وعليــه جــرى التوقيع)أ‪.‬ه ـ كمــا جــرى االطالع علــى اعترافه يف صحيفة‬\n      ‫(‪ )16‬لفــه (‪ )3‬املتضمــن قيامــه بســرقة بطاريــة ســيارة نــوع ‪ ...‬وســرقة آلــة‬\n      ‫حديــد نــوع ‪ ....‬مــن حــي ‪ ....‬كمــا قــام باملشــاركة يف ســرقة جــوال نــوع‬\n      ‫‪ ....‬مــن محــل النجاريــن كمــا جــرى االطــاع علــى اعتــراف املدعــى عليــه‬\n      ‫الثانــي صحيفــة (‪ )6‬لفــه (‪ )5‬ونصــه (أقــر أنــا املدعــو ســعودي اجلنســية‬\n      ‫ســجل مدنــي وانــا بكامــل قــواي العقليــة املعتبــرة شــرع ًا غيــر مكــره‬\n      ‫وال مجبــر بأننــي منــذ فتــره قمــت باالشــتراك يف عــدت ســرقات منها أو ًال‬\n      ‫ســرقة دبــاب لــون ســماوي مــن منــزل بحــي ‪ .....‬وذلــك باالشــتراك مــع‬\n      ‫املدعــو‪ ...../‬حيــث قــام املذكــور بالقفــز وفتــح بــاب املنــزل لنــا حيــث‬\n      ‫قمــت بتحميلــه مــع بســيارته نــوع ‪ ....‬لــون أبيــض وقــام بأخــذه وبعدهــا‬\n      ‫بفتــرة أي ((ثانــي )) الســرقات قمــت بالذهــاب مــع املذكــور مــع ســيارته‬\n      ‫وذهبنــا إلــى منــزل حتــت اإلنشــاء وقــام بالقفــز وفتــح بــاب املنــزل فيمــا‬\n      ‫دخلــت إلــى املنــزل وقمــت بســرقة ماطــور مــاء لونــه اصفــر ووصفــه يف‬\n      ‫منزلــي ثالثـ ًا قمــت باالشــتراك يف ســرقة حمــام مــن مزرعــة علــى طريــق‬\n      ‫‪ ....‬باالشــتراك مــع و وكان عــدد احلمــام (‪ )50‬حمامــة وكان دوري‬\n      ‫مراقبــة للمزرعــة رابع ـ ًا قمــت باالشــتراك يف ســرقة ثالثــون حمامــه يف‬\n      ‫داخل مزرعة بالـ‪ .....‬وكان يرافقني الذي بدوره قام بالقفز واســتخراج‬\n\n\n‫‪135‬‬\n\f‫احلمــام فيمــا كنــت مراقبــة للموقــع ومعــي الســوداني خامســا قمــت‬\n‫باالشــتراك يف ســرقة دجــاج مــن مزرعــة بحــي ‪ ....‬وعددهــا غيــر معــروف‬\n‫وكان يرافقنــي وكان دوري هــو املراقبــة فيمــا كان يقفــز ويســرق‬\n‫الدجــاج سادسـ ًا قمــت باالشــتراك يف ســرقة دجــاج ‪ +‬حمــام مــن مزرعــة‬\n‫قــرب ‪ .....‬وكان دوري هــو املراقبــة فيمــا كان يقــوم بقــص الشــبك‬\n‫والدخــول معــه ســابع ًا وثامن ـ ًا وتاســع ًا قمــت باالشــتراك مــع املذكــور‬\n‫بســرقة ثالثــة مــزارع وســرق منهــا عــدد (‪ )100‬حمامــه غاليــة الثمــن‬\n‫وعــدد(‪ )20‬دجاجــه وهــي غاليــة الثمــن نــوع حباحــب وعــدد(‪ )15‬دجاجــه‬\n‫وجميعهــا واقعــة علــى طريــق ‪ .....‬حيــث كان دوري هــي املراقبــة كذلك‬\n‫أمــا دوري هــو القفــز والســرقة وهــذا اعتــراف وعليــه جــرى التوقيع)أ‪.‬ه ـ‬\n‫كمــا جــرى االطــاع علــى اعتــراف احلــدث علــى صحيفــة (‪ )5‬لفــه ‪7‬‬\n‫ـاء علــى‬\n       ‫املتضمــن مشــاركة املدعــى عليــه الثالــث يف عــدة ســرقات فبنـ ً‬\n‫مــا تقــدم مــن الدعــوى واإلجابــة وحيــث أنكــر املدعــى عليهــم دعــوى‬\n‫املدعــي العــام وألنــه ال بينــة للمدعــي العــام ســوى اقراراتهــم التــي رجعــوا‬\n‫عنهــا وحيــث أقــر املدعــى عليــه األول والثانــي حتقيقــا بقيامهــم بعــدة‬\n‫ســرقات مفصلــه أعــاه ومؤاخــذه لهــم بإقرارهــم وألن الرجــوع عــن‬\n‫اإلقــرار شــبهه توجــب درء احلــد لقولــه صلــى اهلل عليــه وســلم (ادرؤوا‬\n‫احلــدود بالشــبهات ) وألن الشــبهة تــدور حــول املدعــى عليــه الثالــث‬\n‫إلقــرارات املدعــى عليهــم مبشــاركته ولوجــود عــدة ســوابق عليــه وحيث‬\n‫جــاءت الشــريعة بحفــظ الضــرورات اخلمــس ومنهــا املــال وحرمــت‬\n‫االعتــداء عليهــا فقــد قررنــا مــا يلــي أو ًال ‪ /‬درء حــد الســرقة عــن املدعــى‬\n‫عليهــم األول والثانــي والثالــث ثاني ـ ًا ‪ /‬تعزيــر املدعــى عليــه األول وذلــك‬\n‫بســجنه ســنتني اعتبــار ًا مــن تاريــخ ايقافــه وجلــده مائتــي جلــدة مفرقــة‬\n\n\n                                                                                       ‫‪136‬‬\n\f      ‫علــى دفعــات كل دفعــه خمســن جلــده وبــن كل دفعــه وأخــرى شــهر‬\n      ‫ثالث ـ ًا ‪ /‬تعزيــر املدعــى عليــه الثانــي ‪ .....‬وذلــك بســجنه خمــس ســنوات‬\n      ‫اعتبــارا مــن تاريــخ إيقافــه وجلــده خمســمائة جلــده مفرقــة علــى دفعــات‬\n      ‫كل دفعــة خمســن جلــدة وبــن كل دفعــه وأخــرى شــهر رابعـ ًا ‪ /‬تعزيــر‬\n      ‫املدعــى عليــه الثالــث وذلــك بســجنه ســنتني اعتبــارا مــن تاريــخ ايقافــه‬\n      ‫وجلــده مائتــي جلــده مفرقــة علــى دفعــات كل دفعــه خمســن جلــده وبــن‬\n      ‫كل دفعــه وأخــرى شــهر خامس ـ ًا ‪ /‬صــرف النظــر عــن طلــب املدعــي‬\n      ‫العــام مبصــادرة الســيارة املوصوفــة يف الدعــوى العائــدة للمدعــى عليــه‬\n      ‫الثالــث لعــدم ثبــوت موجبــه وبــه حكمنــا وبعــرض احلكــم قــرر املدعــى‬\n      ‫عليهــم القناعــة واملدعــي العــام عدهــا فأفهمنــاه باملراجعــة يف يــوم األثنني‬\n      ‫املوافــق ‪1434/4/1‬ه ـ الســتالم نســخة مــن احلكــم لتقــدمي الئحتــه‬\n      ‫االعتراضيــة خــال ثالثــن يومــا وإال يســقط حقــه يف االعتــراض إن لــم‬\n      ‫يتقــدم بشــيء وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                          ‫وصحبه وسلم ‪ .‬حرر يف ‪ 1434/03/25‬هـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعنــا نحــن ق ــضاة الدائـ ــرة اجلزائـي ــة‬\n      ‫اخلماسـي ــة األولــى يف محكمــة االســتئناف باملنطقــة الشــرقية علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامة مبحافظة األحســاء‬\n      ‫برقــم ‪ 34/1117072‬وتاريــخ ‪1434/5/21‬ه ـ واملقيــدة لــدى احملكمــة‬\n      ‫برقــم ‪/34/1274544‬خ‪ 1‬وتاريــخ ‪1434/5/26‬ه ـ املرفــق بهــا القــرار‬\n      ‫الشــرعي ذو الرقــم ‪ 34173949‬والتاريــخ ‪1434/3/28‬ه ـ الصــادر‬\n      ‫مــن أصحــاب الفضيلــة القضــاة باحملكمــة الشــيخ‪ .....‬والشــيخ‪.....‬‬\n      ‫والشــيخ‪.....‬اخلاص بدعــوى‪ .....‬املدعــي العــام ضــد‪ .....‬كل مــن ‪.....-1‬‬\n      ‫‪ .....-3 .....-2‬يف قضيــة ســرقه وقــد تضمــن القــرار حكــم أصحــاب‬\n\n\n‫‪137‬‬\n\f‫الفضيلــة مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه‬\n‫والالئحــة االعتراضيــة وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم‪.‬‬\n‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف‬\n                                                             ‫‪1434/6/12‬هــ‪.‬‬\n\n\n\n\n                                                                                 ‫‪138‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":127,"source_page_end":138,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"385689b1b508c598998c0fbdbc1f5e341e8bbd439e3d7f303c7fa9d12b9d2d23","normalized_text_hash":"342e309777fcb993b1072b4c9a7473f497dbd1d8b95a4401abe31bb8785f7f27","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p127-34173949"},{"id":"590a9a5a-0cc0-5cd5-bc12-09f392f326f5","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة إبل -مشاركة يف سرقة -إقامة بطريقة غير مشروعة -انتحال شخصية الغير -ادعاء اإلكراه يف انتزاع إقرار مصدق شرع ا -طلب بينة على ادعاء اإلكراه يف انتزاع إقرار مصدق شرع ا -إدانة املدعى عليه بناء على اإلقرار املصدق شرع ا -إنكار السرقة -تشديد عقوبة السرقة النتشارها درء حد السرقة النعدام هتك احلرز -التعزير بالسجن واجللد والتوصية باإلبعاد عن الباد.","document_number":"33430566","case_number":"33589804","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/18","year":"1434","subject":"سرقة -سرقة إبل -مشاركة يف سرقة -إقامة بطريقة غير مشروعة -انتحال شخصية الغير -ادعاء اإلكراه يف انتزاع إقرار مصدق شرع ا -طلب بينة على ادعاء اإلكراه يف انتزاع إقرار مصدق شرع ا -إدانة املدعى عليه بناء على اإلقرار املصدق شرع ا -إنكار السرقة -تشديد عقوبة السرقة النتشارها درء حد السرقة النعدام هتك احلرز -التعزير بالسجن واجللد والتوصية باإلبعاد عن الباد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك ‪ 33430566 :‬تاريخه ‪1433/10/18:‬هـ‬\n                            ‫رقم الدعوى ‪33589804:‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪349813 :‬‬\n                             ‫تاريخه‪1434/01/12 :‬ه‬\n\n\n\n         ‫ســرقة ‪ -‬ســرقة إبل ‪ -‬مشــاركة يف ســرقة ‪ -‬إقامة بطريقة غير مشــروعة‬\n         ‫‪ -‬انتحــال شــخصية الغيــر‪ -‬ادعــاء اإلكــراه يف انتــزاع إقــرار مصــدق‬\n         ‫شــرع ًا ‪ -‬طلــب بينــة علــى ادعــاء اإلكــراه يف انتــزاع إقــرار مصــدق شــرع ًا‬\n         ‫‪ -‬إدانــة املدعــى عليــه بنــاء علــى اإلقــرار املصــدق شــرع ًا ‪ -‬إنــكار الســرقة‬\n         ‫‪ -‬تشــديد عقوبــة الســرقة النتشــارها درء حــد الســرقة النعــدام هتــك‬\n              ‫احلــرز ‪ -‬التعزيــر بالســجن واجللــد والتوصيــة باإلبعــاد عــن البــاد‪.‬‬\n\n\n\n\n                          ‫عدم توفر شروط السرقة إذا لم يكن هناك هتك حرز‪.‬‬\n\n\n\n\n         ‫الئحــة الدعــوى ضــد املدعــى عليــه (مقيــم بطريقــة غيــر مشــروعة)‬\n         ‫بســرقة إبــل مــن حــوش صاحــب اإلبــل الــذي يعمــل لديــه مبشــاركة‬\n         ‫راعــي اإلبــل وشــخص ثالــث‪ ،‬وانتحالــه لشــخصية الغيــر‪ ،‬وطلــب املدعي‬\n         ‫العــام إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة مشــددة‪ ،‬مت‬\n         ‫القبــض علــى املدعــى عليــه بعــد بــاغ مــن أحــد األشــخاص يفيــد بتعــرض‬\n         ‫أربعــة مــن إبلــه للســرقة و يتهــم املدعــى عليــه كونــه راعيـ ًا لديــه واختفــى‬\n         ‫عــن األنظــار بعــد حادثــة الســرقة‪ ،‬أنكــر املدعــى عليــه الدعــوى ووجــود‬\n         ‫إقــرار للمدعــى عليــه مصــدق شــرعاً‪ ،‬إال أنــه ادعــى اإلكــراه يف انتــزاع‬\n\n‫‪139‬‬\n\f‫اإلقــرار املصــدق شــرعاً‪ ،‬عــدم وجــود بينــة علــى اإلكــراه‪ ،‬ثبــت إدانــة‬\n‫املدعــى عليــه‪ ،‬عــدم إقامــة حــد الســرقة ألنــه لــم يكــن هنــاك هتــك‬\n‫للحــرز ‪ ،‬حكمــت احملكمــة بتعزيــر املدعــى عليــه بالســجن واجللــد‬\n‫وتشــديد العقوبــة النتشــارها والتوصيــة بإبعــاد املدعــى عليــه عــن البــاد‬\n            ‫اتقــاء لشــره‪ ،‬مت تصديــق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمد هلل وحده وبعد فلدي أنا ‪ ............‬القاضي يف احملكمة اجلزائية‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ .....‬وتاريــخ ‪......‬ه ـ املقيــدة باحملكمــة برقــم‬\n‫‪ ......‬وتاريــخ‪ .......‬ه ـ ففــي يــوم االثنــن املوافــق ‪ .........‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 01 : 30‬وفيهــا حضــر ‪ .........‬عضــو هيئــة التحقيــق واالدعــاء‬\n‫العــام بالريــاض وادعــى علــى‪ 36( ....... /‬عاماً) ســوداني اجلنســية يقيم يف‬\n‫البــاد بطريقــة غيــر مشــروعة أوقــف بالســجن العــام مبوجــب مذكــرة‬\n                                             ‫رقــم ‪ 1866‬وتاريــخ ‪1433/3/7‬هــ‪.‬‬\n‫بتاريــخ ‪......‬ه ـ حضــر للمركــز‪ ........ /‬مبلغـ ًا عــن تعــرض احلــوش التابــع‬\n‫لــه والواقــع بطريــق اخلــرج لســرقة أربــع رؤوس مــن اإلبــل مختلفــة األنــواع‬\n‫وتقــدر قيمتهــا اإلجماليــة مببلــغ مائتــان وثالثــة وعشــرين ألــف ريــال‬\n‫ويتهــم الراعــي املدعــى عليــه الــذي اختفــى عــن أنظــاره بعــد ارتــكاب‬\n                                                                            ‫الســرقة ‪.‬‬\n‫بتاريــخ ‪........‬ه ـ ورد ملركــز شــرطة ‪ ....‬كتــاب مركــز شــرطة ‪.......‬‬\n‫املتضمــن حضــور ابــن املبلــغ لديهــم ‪ ......‬مفيــدا بــأن عثــر علــى أحــد اإلبــل‬\n‫التابعــة لوالــده لــدى ‪ .......‬وبتتبــع ذلــك مت التوصــل للــدالل ‪ ...........‬الــذي‬\n\n                                                                                            ‫‪140‬‬\n\f      ‫يعمــل بحــراج ســوق اإلبــل مبنطقــة ‪ ....‬وبســماع أقوالــه أفــاد بأنه اشــتراها‬\n      ‫مــن شــخص ســوداني اجلنســية يدعــى‪ ..... /‬وكان يرافقــه قائــد ســيارة‬\n      ‫‪ .....‬لوحــة رقــم (‪ )....‬يدعــى‪ .... /‬وعندمــا ســوره الشــك بــأن تلــك اإلبــل‬\n      ‫مســروقة تقــدم ملركــز شــرطة ‪ .....‬وأبلغهــم مبــا لديــه وبالتنســيق مــع مت‬\n      ‫القبــض علــى البائــع الرئيســي املدعــى عليــه والــذي ادعــى بــأن اســمه‪/‬‬\n      ‫‪ .....‬وباســتجواب املدعــى عليــه أفــاد أنــه ورده اتصــا ًال مــن زميلــه ‪....‬‬\n      ‫وطلــب منــه إحضــار ســيارة ‪ ....‬مفيــد ًا بــأن لديــه عــدد أربعــة رؤوس مــن‬\n      ‫اإلبــل يرغــب ببيعهــا يف الســوق وقــام هــو بــدوره باالتصــال علــى رفيقــه‪....‬‬\n      ‫وطلــب منــه إحضــار ســيارته نــوع ‪ ...‬وحضــر إليــه واجتهــا إلــى رفيقــه‪......‬‬\n      ‫بأحــد األحــواش الواقعــة بطريــق اخلــرج منطقــة ‪ ...‬وقامــوا بتحميــل عــدد‬\n      ‫أربعــة مــن اإلبــل ثــاث منهــا نــوع مجاهيــم والرابعــة نــوع عفــراء وأثنــاء‬\n      ‫الطريــق اتفقــوا جميع ـ ًا علــى بيعهــا مبنطقــة القصيــم بســوق اإلبــل ومت‬\n      ‫بيعهــا مببلــغ واحــد وأربعــون ألــف ريــال (‪ )41.000‬ألــف ريــال وتوزيــع‬\n      ‫املبلــغ بينهمــا حيــث ان نصيــب كل منهمــا مبلــغ اثنــي عشــر ألــف ريــال‬\n      ‫واملتبقــي خمســة آالف ريــال قيمــة إيجــار الســيارة ‪. ....‬ورد كتــاب مديــر‬\n      ‫إدارة الوافديــن رقــم ‪ 6329‬وتاريــخ ‪1433/5/3‬ه ـ بشــأن إقامــة املدعــى‬\n      ‫عليــه يف البــاد بطريقــة غيــر مشــروعة املتضمــن الســجن ملــدة شــهر‬\n                                                                    ‫وترحيلــه عــن البــاد‪.‬‬\n      ‫ـ جــرى فــرز أوراق مســتقلة بشــأن الهاربــن كل مــن‪ ...‬و‪ ....‬للتحقيــق‬\n                                                        ‫معهمــا حــال القبــض عليهمــا‪.‬‬\n      ‫وقــد أســفر التحقيــق عــن توجيــه االتهــام للمدعــى عليهمــا بســرقة اإلبــل‬\n                         ‫وانتحــال شــخصية الغيــر وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n                                       ‫‪1‬ـ اعترافه املصدق شرع ًا املرفق لفة رقم (‪.)6‬‬\n\n\n‫‪141‬‬\n\f                                  ‫‪2‬ـ ما جاء يف أقوال املبلغ املرفق لفة رقم (‪.)5‬‬\n                                               ‫‪3‬ـ ما جاء يف بالغ الدالل ‪. ...........‬‬\n‫وبالبحــث عــن ســوابقه لــم يعثــر لــه علــى ســوابق مســجلة عليــه حتــى‬\n‫تاريخــه‪ .‬وحيــث أن مــا أقــدم عليــه املدعــى عليــه فعــل محــرم ومعاقــب‬\n‫عليــه شــرع ًا أطلــب احلكــم عليــه بعقوبــة تعزيريــة مشــددة لقــاء مــا أســند‬\n                                   ‫إليــه (علم ـ ًا أن احلــق اخلــاص مــا زال قائم ـاً)‪.‬‬\n‫ويف هــذه اجللســة حضــر املدعــى عليــه وبعــرض دعــوى املدعــي العــام‬\n‫علــى املدعــى عليــه أجــاب املدعــى عليــه بــأن مــا ذكــره املدعــي العــام‬\n‫مــن اتفاقــي مــع ‪ ........‬علــى بيــع عــدد مــن اإلبــل وحضــوري مــع زميلــي‬\n‫‪ .....‬إلــى احلــوش الــذي يعمــل فيــه ‪ ......‬وقيامنــا بتحميــل أربعــة رؤوس‬\n‫مــن اإلبــل وبيعهــا يف منطقــة ‪ ....‬باملبلــغ املذكــور فهــذا صحيــح وقــد‬\n‫اســتلم املبلــغ ‪ .....‬وأعطانــي منــه ألفــان وخمســمائة ريــال (‪ )2500‬ووعــد‬\n‫بــأن يعطينــي مــن املبلــغ اثنــا عشــر ألــف ريــال (‪ )12000‬وكان ذلــك‬\n‫مقابــل عملــي معــه ولــم أقصــد ســرقة هــذه اإلبــل كمــا أن مــا ذكــره‬\n‫املدعــي العــام مــن انتحالــي الســم غيــر اســمي فهــو صحيــح وقــد اشــتهر‬\n‫اســمي عنــد زمالئــي ومــن أعمــل عندهــم باســم ‪ ....‬ولــم أقصــد انتحــال‬\n‫اســم شــخص آخــر وبســؤال املدعــي العــام عــن بينتــه قــال مــا ذكرتــه‬\n‫مــن األدلــة والقرائــن وباالطــاع عليهــا وجــدت اعتــراف املدعــى عليــه‬\n‫املصــدق شــرعا واملــدون علــى الصفحــة (‪ )6‬مــن ملــف التحقيــق املرفــق‬\n‫علــى لفــه (‪ )6‬املتضمــن إقــرار املدعــى عليــه بتلقيــه اتصــال مــن صديقــه‬\n‫‪ .......‬والــذي طلــب منــه إحضــار ســيارة ‪ .....‬لبيــع عــدد مــن اإلبــل وقيامــه‬\n‫باالتصــال بصديقــه ‪ ............‬وطلبــه إحضــار ســيارته وقيامــه مــع زمالئــه‬\n‫بتحميــل أربعــة رؤوس مــن اإلبــل الــذي يعمــل فيــه ‪ .....‬والتوجــه بهــا إلــى‬\n\n\n                                                                                            ‫‪142‬‬\n\f      ‫ســوق اإلبــل يف بريــدة وبيعهــا مببلــغ وقــدرة واحــد وأربعــون ألــف ريــال‬\n      ‫(‪ )41000‬وأنــه قــام باســتالمها مــن يــد الــدالل وبعــد اخلــروج مــن الســوق‬\n      ‫قــام بتســليم كامــل املبلــغ ‪ ....‬وقــام ‪ ...‬بإعطائــه مبلــغ اثنا عشــر ألف ريال‬\n      ‫(‪ )12000‬وأعطــى ‪ .....‬نفــس املبلــغ وأخــذ الباقــي وذكــر بأنــه لــم يعلــم‬\n      ‫بــأن اإلبــل مســروقة بعــد البيــع كمــا جــرى االطــاع علــى أقــوال الــدالل‬\n      ‫فوجدتهمــا مطابقــن ملــا ذكــره املدعــي العــام وبعــرض هــذه األدلــة‬\n      ‫علــى املدعــى عليــه قــال أمــا مــا ورد يف االعتــراف املصــدق شــرعا فغيــر‬\n      ‫صحيــح والصحيــح مــا ذكرتــه ســابقا وقــد وقعــت علــى هــذا اإلقــرار‬\n      ‫بإكــراه مــن احملقــق حيــث قــام بضربــي وبســؤاله هــل لديــه بينــه علــى‬\n      ‫اإلكــراه قــال ليــس لــدي بينــه وبنــاءا علــى الدعــوى واإلجابــة وحيــث‬\n      ‫ـاء علــى‬‫أنكــر املدعــى عليــه ســرقته لإلبــل محــل الدعــوى مــع زمالئــه وبنـ ً‬\n      ‫مــا قدمــه املدعــي العــام مــن أدلــة أقواهــا اإلقــرار املصــدق شــرعا الصادر‬\n      ‫مــن املدعــى عليــه وقــد ادعــى املدعــى عليــه بأنــه قــد أكــره عليــه وال‬\n      ‫بينــه لديــه علــى ذلــك فقــد ثبــت لــدي إدانــة املدعــى عليــه بســرقة اإلبــل‬\n      ‫محــل الدعــوى وانتحالــه شــخصية الغيــر ولعــدم توفــر شــروط إقامــة حــد‬\n      ‫الســرقة ألنــه لــم يكــن فيــه هتــك للحــرز حيــث أن أحــد املشــاركني يف‬\n      ‫الســرقة يعمــل يف احلــوش الــذي أخــذت منــه وحيــث أن مــا أقــدم عليــه‬\n      ‫املدعــى عليــه محــرم شــرعا وموجــب لتشــديد العقوبــة النتشــاره وملــا فيــه‬\n      ‫مــن تعــدٍ علــى أمــوال اآلخريــن فقــد حكمــت عليــه تعزيــر ًا بســجنه ثــاث‬\n      ‫ســنوات اعتبــارا مــن تاريــخ إيقافــه وجلــده خمســمائة جلــده مفرقــة علــى‬\n      ‫دفعــات كل دفعــة خمســون جلــده كل عشــرة أيــام وأوصــي بإبعــاده‬\n      ‫عــن البــاد بعــد انتهــاء محكوميتــه وعــدم الســماح لــه بالعــودة إتقــاء ًا‬\n      ‫لشــره وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه القناعــة‬\n\n\n‫‪143‬‬\n\f‫وقــرر املدعــي العــام عــدم القناعــة واكتفــى بالئحــة الدعــوى كالئحــة‬\n‫اعتراضيــة ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                   ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/10/16‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة الثالثــة‬\n‫لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيس احملكمة اجلزائيــة بالرياض برقم ‪ ......‬وتاريخ‬\n‫‪.......‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة‬\n‫الشــيخ ‪ ...... /‬املســجل برقــم ‪ ......‬وتاريــخ ‪........‬ه ـ اخلــاص بدعــوى العــام‬\n‫ضــد‪ ( ........ /‬ســوداني اجلنســية ) يف قضيــة ســرقة علــى النحــو املوضــح‬\n‫بالقــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون و مفصــل بــه بدراســة‬\n‫القــرار وصــورة ضبطــه وأوراق املعاملــة لــم يظهــر لألكثريــة مــا يوجــب‬\n‫املالحظــة علــى احلكــم مــع تنبيــه فضيلتــه إلــى تصحيــح األخطــاء يف‬\n‫الصفحــة األولــى مــن القــرار‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                                       ‫وعلــى الــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                       ‫‪144‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":139,"source_page_end":144,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"85e18089c196ea73f1380939d406e1456e16efc7daec2ee3d9b246724c28fb24","normalized_text_hash":"277b01f37446c24d91aaaecb03bfa38d72cec9964e446257ddfaaee578d50d8d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p139-33430566"}]$archive_payload$::jsonb AS data)
